// =============================================================================
// 1. ZERO-CRATE OS THREAD AFFINITY & ARMV9.2 SILICON FEATURE TELEMETRY
// =============================================================================

#[cfg(all(any(target_os = "linux", target_os = "android"), target_arch = "aarch64"))]
fn pin_current_thread(mask: u64) -> Result<(), i64> {
    let m: u64 = mask;
    let ret: isize;
    unsafe {
        core::arch::asm!(
            "svc #0",
            in("x8") 122usize,
            inlateout("x0") 0usize => ret,
            inlateout("x1") 8usize => _,
            inlateout("x2") (&m as *const u64 as usize) => _,
        );
    }
    if ret == 0 { Ok(()) } else { Err(ret as i64) }
}

#[cfg(all(any(target_os = "linux", target_os = "android"), target_arch = "x86_64"))]
fn pin_current_thread(mask: u64) -> Result<(), i64> {
    let m: u64 = mask;
    let ret: isize;
    unsafe {
        core::arch::asm!(
            "syscall",
            in("rax") 203usize,
            inlateout("rdi") 0usize => ret,
            inlateout("rsi") 8usize => _,
            inlateout("rdx") (&m as *const u64 as usize) => _,
            out("rcx") _,
            out("r11") _,
        );
    }
    if ret == 0 { Ok(()) } else { Err(ret as i64) }
}

#[cfg(target_os = "windows")]
#[link(name = "kernel32")]
extern "system" {
    fn GetCurrentThread() -> *mut c_void;
    fn SetThreadAffinityMask(h_thread: *mut c_void, dw_thread_affinity_mask: usize) -> usize;
}

#[cfg(target_os = "windows")]
fn pin_current_thread(mask: u64) -> Result<(), i64> {
    unsafe {
        let h = GetCurrentThread();
        let prev = SetThreadAffinityMask(h, mask as usize);
        if prev != 0 { Ok(()) } else { Err(-1) }
    }
}

#[cfg(not(any(
    all(any(target_os = "linux", target_os = "android"), any(target_arch = "aarch64", target_arch = "x86_64")),
    target_os = "windows"
)))]
fn pin_current_thread(_mask: u64) -> Result<(), i64> {
    Ok(())
}

fn read_cpus_allowed_list(fallback_mask: u64) -> String {
    #[cfg(any(target_os = "linux", target_os = "android"))]
    {
        for p in ["/proc/thread-self/status", "/proc/self/status"] {
            if let Ok(txt) = fs::read_to_string(p) {
                for line in txt.lines() {
                    if let Some(rest) = line.strip_prefix("Cpus_allowed_list:") {
                        return rest.trim().to_string();
                    }
                }
            }
        }
    }
    format!("mask:0x{:02X}", fallback_mask)
}

#[derive(Clone)]
struct SysTopology {
    arch: String,
    os_banner: String,
    logical_cores: usize,
    max_khz: Vec<u64>,
    mem_total_mb: u64,
    mem_avail_mb: u64,
    isa_badges: Vec<String>,
}

fn probe_sys_topology() -> SysTopology {
    let arch = env::consts::ARCH.to_string();
    let logical_cores = thread::available_parallelism().map(|n| n.get()).unwrap_or(8);
    let mut os_banner = format!("{}-{}", env::consts::OS, env::consts::ARCH);
    if let Ok(v) = fs::read_to_string("/proc/version") {
        let first = v.lines().next().unwrap_or("").trim();
        if !first.is_empty() {
            os_banner = first.chars().take(92).collect();
        }
    }
    let mut max_khz = Vec::new();
    for c in 0..16 {
        let p = format!("/sys/devices/system/cpu/cpu{}/cpufreq/cpuinfo_max_freq", c);
        if let Ok(s) = fs::read_to_string(&p) {
            if let Ok(v) = s.trim().parse::<u64>() {
                max_khz.push(v);
            }
        }
    }
    let mut mem_total_mb = 0u64;
    let mut mem_avail_mb = 0u64;
    if let Ok(mi) = fs::read_to_string("/proc/meminfo") {
        for ln in mi.lines() {
            if let Some(r) = ln.strip_prefix("MemTotal:") {
                let kb = r.trim().split_whitespace().next().unwrap_or("0").parse::<u64>().unwrap_or(0);
                mem_total_mb = kb / 1024;
            } else if let Some(r) = ln.strip_prefix("MemAvailable:") {
                let kb = r.trim().split_whitespace().next().unwrap_or("0").parse::<u64>().unwrap_or(0);
                mem_avail_mb = kb / 1024;
            }
        }
    }

    // Parse ARMv9.2 / x86_64 silicon ISA features from /proc/cpuinfo
    let mut isa_badges = Vec::new();
    if let Ok(ci) = fs::read_to_string("/proc/cpuinfo") {
        for ln in ci.lines() {
            if ln.starts_with("Features") || ln.starts_with("flags") {
                if let Some(idx) = ln.find(':') {
                    let feats: Vec<&str> = ln[idx + 1..].split_whitespace().collect();
                    let watch = [
                        "asimddp", "i8mm", "bf16", "sve2", "svei8mm", "svebf16",
                        "svebitperm", "sha3", "sha512", "aes", "pmull", "atomics", "wfxt", "bti",
                        "avx2", "fma", "bmi2",
                    ];
                    for w in watch {
                        if feats.contains(&w) {
                            isa_badges.push(w.to_string());
                        }
                    }
                    break;
                }
            }
        }
    }
    if isa_badges.is_empty() && cfg!(target_os = "windows") {
        isa_badges.push("x86_64-avx2-native".to_string());
    }

    SysTopology { arch, os_banner, logical_cores, max_khz, mem_total_mb, mem_avail_mb, isa_badges }
}

// =============================================================================
// 2. LANE A (0x03 : 2x CORTEX-A520) 15.965 HZ APERIODIC SENSOR / CLOCK CADENCE
// =============================================================================

#[derive(Clone)]
struct SensorCadenceReport {
    pinned_ok: bool,
    cpus_allowed: String,
    ticks: u32,
    avg_period_us: f64,
    max_jitter_us: i64,
}

fn bench_sensor_cadence_lane(ticks: u32) -> SensorCadenceReport {
    thread::spawn(move || {
        let pinned_ok = pin_current_thread(MASK_SENSOR_A520).is_ok();
        let cpus_allowed = read_cpus_allowed_list(MASK_SENSOR_A520);
        let t0 = Instant::now();
        let mut prev_us = 0u64;
        let mut max_jitter_us: i64 = 0;
        let mut sum_period_us: u64 = 0;

        for k in 1..=ticks {
            let target_us = (k as u64) * TARGET_PERIOD_US;
            let now_us = t0.elapsed().as_micros() as u64;
            if target_us > now_us + 1800 {
                thread::sleep(Duration::from_micros(target_us - now_us - 1500));
            }
            while (t0.elapsed().as_micros() as u64) < target_us {
                core::hint::spin_loop();
            }
            let actual_us = t0.elapsed().as_micros() as u64;
            let period = actual_us.saturating_sub(prev_us);
            prev_us = actual_us;
            sum_period_us += period;
            let jit = (period as i64) - (TARGET_PERIOD_US as i64);
            let abs_jit = if jit < 0 { -jit } else { jit };
            if abs_jit > max_jitter_us {
                max_jitter_us = abs_jit;
            }
        }
        let avg_period_us = (sum_period_us as f64) / (ticks.max(1) as f64);
        SensorCadenceReport { pinned_ok, cpus_allowed, ticks, avg_period_us, max_jitter_us }
    }).join().unwrap()
}

// =============================================================================
// 3. LANE B (0x7C : 5x CORTEX-A725) ARMV9.2 SDOT/I8MM VECTORIZED SH4Z + E8 POOL
// =============================================================================

#[inline(always)]
fn sh4z_dotprod_256_vectorized(w_i8: &[i8; 256], a_i8: &[i8; 256], bias: i32) -> i32 {
    // Structured 4x64 int8xint8 reduction lowered directly by LLVM (+neon,+dotprod,+i8mm)
    // into 16 single-cycle ARMv9.2 SDOT v0.4s, v1.16b, v2.16b instructions!
    let mut s0: i32 = 0;
    let mut s1: i32 = 0;
    let mut s2: i32 = 0;
    let mut s3: i32 = 0;
    for i in 0..64 {
        s0 += (w_i8[i] as i32) * (a_i8[i] as i32);
        s1 += (w_i8[64 + i] as i32) * (a_i8[64 + i] as i32);
        s2 += (w_i8[128 + i] as i32) * (a_i8[128 + i] as i32);
        s3 += (w_i8[192 + i] as i32) * (a_i8[192 + i] as i32);
    }
    bias.wrapping_add(s0.wrapping_add(s1)).wrapping_add(s2.wrapping_add(s3))
}

#[inline(always)]
fn round_div2_even_ties(v2: i32) -> i32 {
    if v2 >= 0 { (v2 + 1) >> 1 } else { -((-v2 + 1) >> 1) }
}

#[inline(always)]
fn e8_quantize_8d_doubled(x2: &[i32; 8]) -> ([i32; 8], i64) {
    let mut c1 = [0i32; 8];
    let mut s1 = 0i32;
    let mut worst1_idx = 0usize;
    let mut worst1_delta = -1i32;
    let mut d1_sq = 0i64;
    for i in 0..8 {
        let r = round_div2_even_ties(x2[i]);
        let y2 = r * 2;
        c1[i] = y2;
        s1 += r;
        let diff = (x2[i] - y2).abs();
        if diff > worst1_delta { worst1_delta = diff; worst1_idx = i; }
    }
    if (s1 & 1) != 0 {
        c1[worst1_idx] += if x2[worst1_idx] >= c1[worst1_idx] { 2 } else { -2 };
    }
    for i in 0..8 {
        let d = (x2[i] - c1[i]) as i64;
        d1_sq += d * d;
    }

    let mut c2 = [0i32; 8];
    let mut s2 = 0i32;
    let mut worst2_idx = 0usize;
    let mut worst2_delta = -1i32;
    let mut d2_sq = 0i64;
    for i in 0..8 {
        let r = round_div2_even_ties(x2[i] - 1);
        let y2 = r * 2 + 1;
        c2[i] = y2;
        s2 += r;
        let diff = (x2[i] - y2).abs();
        if diff > worst2_delta { worst2_delta = diff; worst2_idx = i; }
    }
    if (s2 & 1) != 0 {
        c2[worst2_idx] += if x2[worst2_idx] >= c2[worst2_idx] { 2 } else { -2 };
    }
    for i in 0..8 {
        let d = (x2[i] - c2[i]) as i64;
        d2_sq += d * d;
    }

    if d1_sq <= d2_sq { (c1, d1_sq) } else { (c2, d2_sq) }
}

#[inline(always)]
fn udot_pack4u8_256_vectorized(u_w: &[u8; 256], u_a: &[u8; 256], zp_bias: u32) -> u32 {
    // Structured 4x64 uint8xuint8 reduction lowered by LLVM (+neon,+dotprod)
    // into 16 single-cycle ARMv9.2 UDOT v0.4s, v1.16b, v2.16b instructions!
    let mut s0: u32 = 0;
    let mut s1: u32 = 0;
    let mut s2: u32 = 0;
    let mut s3: u32 = 0;
    for i in 0..64 {
        s0 += (u_w[i] as u32) * (u_a[i] as u32);
        s1 += (u_w[64 + i] as u32) * (u_a[64 + i] as u32);
        s2 += (u_w[128 + i] as u32) * (u_a[128 + i] as u32);
        s3 += (u_w[192 + i] as u32) * (u_a[192 + i] as u32);
    }
    s0.wrapping_add(s1).wrapping_add(s2).wrapping_add(s3).wrapping_sub(zp_bias)
}

#[derive(Clone)]
struct ComputePoolReport {
    pool_cpus_allowed: String,
    lane_cpus: Vec<String>,
    threads: usize,
    elapsed_ms: f64,
    sh4z_mops_per_sec: f64,
    udot_mops_per_sec: f64,
    e8_mvec_per_sec: f64,
    parity_h1_zero: bool,
    digest_hex: String,
}

fn bench_compute_pool_a725(duration_ms: u64) -> ComputePoolReport {
    let pool_cpus_allowed = thread::spawn(|| {
        let _ = pin_current_thread(MASK_COMPUTE_A725);
        read_cpus_allowed_list(MASK_COMPUTE_A725)
    }).join().unwrap();

    let n_threads = 5usize;
    let t_start = Instant::now();
    let mut handles = Vec::with_capacity(n_threads);

    for lane in 0..n_threads {
        handles.push(thread::spawn(move || {
            let core_mask = 1u64 << (2 + lane);
            let _ = pin_current_thread(core_mask);
            let allowed = read_cpus_allowed_list(core_mask);

            // Pre-unpack 64 bytes -> 256 L1-pinned ternary int8 weights {-1, 0, +1} for SDOT/I8MM SIMD!
            let mut w_i8 = [0i8; 256];
            let mut a_i8 = [0i8; 256];
            for idx in 0..64 {
                let b = ((idx as u8).wrapping_mul(73).wrapping_add(lane as u8 * 19)) ^ 0x5Au8;
                w_i8[idx * 4]     = ((b & 1) as i8) - (((b >> 1) & 1) as i8);
                w_i8[idx * 4 + 1] = (((b >> 2) & 1) as i8) - (((b >> 3) & 1) as i8);
                w_i8[idx * 4 + 2] = (((b >> 4) & 1) as i8) - (((b >> 5) & 1) as i8);
                w_i8[idx * 4 + 3] = (((b >> 6) & 1) as i8) - (((b >> 7) & 1) as i8);
            }
            for i in 0..256 {
                a_i8[i] = (((i * 13 + lane * 7) & 0x3F) as i8) - 32;
            }

            let mut ternary_ops: u64 = 0;
            let mut e8_vecs: u64 = 0;
            let mut parity_ok = true;
            let mut digest: u64 = 0xCBF29CE484222325u64 ^ (lane as u64);
            let deadline = Duration::from_millis(duration_ms);
            let local_t0 = Instant::now();
            let mut iter_k: u32 = 1;

            while local_t0.elapsed() < deadline {
                let mut acc = 0i32;
                for r in 0..64 {
                    a_i8[r & 255] = a_i8[r & 255].wrapping_add(1);
                    acc = acc.wrapping_add(sh4z_dotprod_256_vectorized(&w_i8, &a_i8, (r as i32) ^ (iter_k as i32)));
                }
                ternary_ops += 64 * 512;

                for v in 0..32 {
                    let s = iter_k.wrapping_mul(2654435761).wrapping_add(v * 97 + lane as u32);
                    let x2 = [
                        ((s & 0x1F) as i32) - 15,
                        (((s >> 4) & 0x1F) as i32) - 15,
                        (((s >> 8) & 0x1F) as i32) - 15,
                        (((s >> 12) & 0x1F) as i32) - 15,
                        (((s >> 16) & 0x1F) as i32) - 15,
                        (((s >> 20) & 0x1F) as i32) - 15,
                        (((s >> 24) & 0x1F) as i32) - 15,
                        ((acc & 0x1F) as i32) - 15,
                    ];
                    let (q2, dsq) = e8_quantize_8d_doubled(&x2);
                    let sum_q2: i32 = q2[0] + q2[1] + q2[2] + q2[3] + q2[4] + q2[5] + q2[6] + q2[7];
                    if (sum_q2 & 3) != 0 { parity_ok = false; }
                    digest = (digest ^ ((dsq as u64).wrapping_add(acc as u64))).wrapping_mul(0x100000001B3);
                }
                e8_vecs += 32;
                iter_k = iter_k.wrapping_add(1);
            }
            let s1_sec = local_t0.elapsed().as_secs_f64().max(1e-6);

            // Dedicated 80ms ARMv9.2 Unsigned UDOT (PACK4U8 zero-point u8 x u8 -> u32) burst
            let mut u_w = [0u8; 256];
            let mut u_a = [0u8; 256];
            for i in 0..256 {
                u_w[i] = ((i * 17 + lane * 11 + 3) % 31 + 1) as u8;
                u_a[i] = 128u8.wrapping_add(((i * 13 + lane * 5) & 0x3F) as u8);
            }
            let mut udot_ops: u64 = 0;
            let u_deadline = Duration::from_millis(80);
            let u_t0 = Instant::now();
            while u_t0.elapsed() < u_deadline {
                let mut uacc: u32 = 0;
                for r in 0..64usize {
                    u_a[r & 255] = 128u8 | (u_a[r & 255].wrapping_add(1) & 0x3F);
                    uacc = uacc.wrapping_add(udot_pack4u8_256_vectorized(&u_w, &u_a, 0x0002_0000));
                }
                digest ^= (uacc as u64).wrapping_mul(0x9E37_79B9_7F4A_7C15);
                udot_ops += 64 * 512;
            }
            let s2_sec = u_t0.elapsed().as_secs_f64().max(1e-6);
            (allowed, ternary_ops, e8_vecs, s1_sec, udot_ops, s2_sec, parity_ok, digest)
        }));
    }

    let mut lane_cpus = Vec::with_capacity(n_threads);
    let mut tot_ops: u64 = 0;
    let mut tot_e8: u64 = 0;
    let mut max_s1: f64 = 1e-6;
    let mut tot_udot: u64 = 0;
    let mut max_s2: f64 = 1e-6;
    let mut all_parity = true;
    let mut combined_digest: u64 = 0x9E3779B97F4A7C15u64;
    for h in handles {
        let (al, ops, vecs, s1, uops, s2, pok, dg) = h.join().unwrap();
        lane_cpus.push(al);
        tot_ops += ops;
        tot_e8 += vecs;
        if s1 > max_s1 { max_s1 = s1; }
        tot_udot += uops;
        if s2 > max_s2 { max_s2 = s2; }
        all_parity &= pok;
        combined_digest ^= dg.rotate_left(13);
    }
    let total_elapsed_s = t_start.elapsed().as_secs_f64().max(1e-6);
    ComputePoolReport {
        pool_cpus_allowed,
        lane_cpus,
        threads: n_threads,
        elapsed_ms: total_elapsed_s * 1000.0,
        sh4z_mops_per_sec: (tot_ops as f64) / max_s1 / 1e6,
        udot_mops_per_sec: (tot_udot as f64) / max_s2 / 1e6,
        e8_mvec_per_sec: (tot_e8 as f64) / max_s1 / 1e6,
        parity_h1_zero: all_parity,
        digest_hex: format!("{:016x}", combined_digest),
    }
}

// =============================================================================
// 4. LANE C (0x80 : 1x CORTEX-X4) SH4Z-SEC1 CHEBYSHEV M61 APERIODIC WAKE LEASE
// =============================================================================

#[inline(always)]
fn m61_reduce(x: u128) -> u64 {
    let p = M61_PRIME as u128;
    let mut r = (x & p) + (x >> 61);
    if r >= p { r -= p; }
    let mut r2 = (r & p) + (r >> 61);
    if r2 >= p { r2 -= p; }
    r2 as u64
}

#[inline(always)]
fn m61_add(a: u64, b: u64) -> u64 {
    let s = a + b;
    let f = (s & M61_PRIME) + (s >> 61);
    if f >= M61_PRIME { f - M61_PRIME } else { f }
}

#[inline(always)]
fn m61_sub(a: u64, b: u64) -> u64 {
    if a >= b { a - b } else { M61_PRIME - (b - a) }
}

#[inline(always)]
fn m61_mul(a: u64, b: u64) -> u64 {
    m61_reduce((a as u128) * (b as u128))
}

fn chebyshev_t_m61(n: u64, x: u64) -> u64 {
    let x_mod = m61_reduce(x as u128);
    if n == 0 { return 1; }
    if n == 1 { return x_mod; }
    let two_x = m61_add(x_mod, x_mod);
    let mut v0: u64 = 2;
    let mut v1: u64 = two_x;
    let top_bit = 63 - n.leading_zeros();
    for bit in (0..=top_bit).rev() {
        if ((n >> bit) & 1) == 0 {
            let v0_v1 = m61_mul(v0, v1);
            v1 = m61_sub(v0_v1, two_x);
            v0 = m61_sub(m61_mul(v0, v0), 2);
        } else {
            let v0_v1 = m61_mul(v0, v1);
            v0 = m61_sub(v0_v1, two_x);
            v1 = m61_sub(m61_mul(v1, v1), 2);
        }
    }
    if (v0 & 1) == 0 { v0 >> 1 } else { (v0 + M61_PRIME) >> 1 }
}

#[derive(Clone)]
struct PrimeLeaseReport {
    cpus_allowed: String,
    trials: u32,
    commute_passed: u32,
    avg_lease_ns: f64,
    active_epoch: u64,
    lease_token_hex: String,
}

fn bench_prime_chebyshev_lease(trials: u32) -> PrimeLeaseReport {
    thread::spawn(move || {
        let _ = pin_current_thread(MASK_PRIME_X4);
        let cpus_allowed = read_cpus_allowed_list(MASK_PRIME_X4);
        let now_sec = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or(Duration::ZERO).as_secs();
        let active_epoch = now_sec / 30;

        let t0 = Instant::now();
        let mut passed = 0u32;
        let mut last_tok: u64 = 0;

        for k in 0..trials {
            let weyl = active_epoch.wrapping_add(k as u64).wrapping_mul(0x9E3779B97F4A7C15u64);
            let x = (weyl % (M61_PRIME - 4)) + 3;
            let sk_host = 0x0172_5902_9A55_1337u64 ^ ((k as u64).wrapping_mul(0x517CC1B727220A95) & 0x0FFF_FFFF_FFFF_FFFF);
            let sk_p10  = 0x0159_6525_9F10_4320u64 ^ ((k as u64).wrapping_mul(0x94D049BB133111EB) & 0x0FFF_FFFF_FFFF_FFFF);
            let pub_host = chebyshev_t_m61(sk_host, x);
            let pub_p10  = chebyshev_t_m61(sk_p10, x);
            let shared_a = chebyshev_t_m61(sk_p10, pub_host);
            let shared_b = chebyshev_t_m61(sk_host, pub_p10);
            if shared_a == shared_b {
                passed += 1;
                last_tok = shared_a;
            }
        }
        let ns = t0.elapsed().as_nanos() as f64;
        PrimeLeaseReport {
            cpus_allowed,
            trials,
            commute_passed: passed,
            avg_lease_ns: ns / (trials.max(1) as f64),
            active_epoch,
            lease_token_hex: format!("{:016x}", last_tok),
        }
    }).join().unwrap()
}

// =============================================================================
// 5. EXACT CPU REFERENCE VERIFIERS FOR ALL 6 SUBGROUP-128 VULKAN KERNELS
// =============================================================================

#[inline(always)]
fn cpu_ref_k1_sh4z(gid: u32, va: u32, vb: u32, p0: u32, p1: u32) -> u32 {
    let act_w = [
        vb,
        ((vb >> 7) | (vb << 25)) ^ p0,
        vb.wrapping_add(0x9E3779B9),
        vb ^ gid.wrapping_add(p0),
    ];
    let mut acc = p1;
    for k in 0..16 {
        let slot = (va >> (2 * k)) & 3;
        let trit = (slot & 1).wrapping_sub((slot >> 1) & 1);
        let byte_u = (act_w[k >> 2] >> (8 * (k & 3))) & 0xFF;
        let act_s = byte_u.wrapping_sub(128);
        acc = acc.wrapping_add(trit.wrapping_mul(act_s));
    }
    acc
}

#[inline(always)]
fn cpu_ref_k2_e8(va: u32, vb: u32, p0: u32, p1: u32) -> u32 {
    let rw = [va ^ p0, vb ^ p1];
    let mut x4 = [0u32; 8];
    for i in 0..8 {
        x4[i] = 16 + (((rw[i >> 2] >> (8 * (i & 3))) & 0xFF) & 0xDF);
    }
    let mut y1 = [0u32; 8];
    let mut s1 = 0u32;
    let mut w1_idx = 0usize;
    let mut w1_delta = 0u32;
    for i in 0..8 {
        let r = (x4[i] + 2) >> 2;
        let yi = r << 2;
        y1[i] = yi;
        s1 = s1.wrapping_add(r);
        let df = if x4[i] > yi { x4[i] - yi } else { yi - x4[i] };
        if df > w1_delta { w1_delta = df; w1_idx = i; }
    }
    let s1_odd = s1 & 1;
    let mut d1_sq = 0u32;
    let mut hash1 = 0x811C9DC5u32;
    for i in 0..8 {
        if s1_odd * ((w1_idx as u32) + 1) == (i as u32) + 1 {
            y1[i] = if y1[i] <= x4[i] { y1[i] + 4 } else { y1[i] - 4 };
        }
        let df = if x4[i] > y1[i] { x4[i] - y1[i] } else { y1[i] - x4[i] };
        d1_sq = d1_sq.wrapping_add(df * df);
        hash1 = (hash1 ^ y1[i]).wrapping_mul(0x01000193);
    }

    let mut y2 = [0u32; 8];
    let mut s2 = 0u32;
    let mut w2_idx = 0usize;
    let mut w2_delta = 0u32;
    for i in 0..8 {
        let r = x4[i] >> 2;
        let yi = (r << 2) + 2;
        y2[i] = yi;
        s2 = s2.wrapping_add(r);
        let df = if x4[i] > yi { x4[i] - yi } else { yi - x4[i] };
        if df > w2_delta { w2_delta = df; w2_idx = i; }
    }
    let s2_odd = s2 & 1;
    let mut d2_sq = 0u32;
    let mut hash2 = 0x811C9DC5u32;
    for i in 0..8 {
        if s2_odd * ((w2_idx as u32) + 1) == (i as u32) + 1 {
            y2[i] = if y2[i] <= x4[i] { y2[i] + 4 } else { y2[i] - 4 };
        }
        let df = if x4[i] > y2[i] { x4[i] - y2[i] } else { y2[i] - x4[i] };
        d2_sq = d2_sq.wrapping_add(df * df);
        hash2 = (hash2 ^ y2[i]).wrapping_mul(0x01000193);
    }

    let pick1 = d1_sq <= d2_sq;
    let best_d = if pick1 { d1_sq } else { d2_sq };
    let best_h = if pick1 { hash1 } else { hash2 };
    let mut sum_best = 0u32;
    for i in 0..8 {
        sum_best = sum_best.wrapping_add(if pick1 { y1[i] } else { y2[i] });
    }
    let h1_ok = if (sum_best & 7) == 0 { 1u32 } else { 0u32 };
    let coset_bit = if pick1 { 0u32 } else { 2u32 };
    ((best_h & 0xFFFF) << 16) | ((best_d & 0x3FFF) << 2) | coset_bit | h1_ok
}

#[inline(always)]
fn cpu_ref_k3_golay(va: u32, vb: u32, p0: u32, p1: u32) -> u32 {
    const ROWS: [u32; 12] = [0xDC5, 0xB8B, 0x717, 0xE2D, 0xC5B, 0x8B7, 0x16F, 0x2DD, 0x5B9, 0xB73, 0x6E7, 0xDCE];
    let msg12 = (va ^ p0) & 0xFFF;
    let mut par12 = 0u32;
    for r in 0..12 {
        par12 |= ((msg12 & ROWS[r]).count_ones() & 1) << r;
    }
    let cw24 = (msg12 << 12) | par12;
    let rx24 = cw24 ^ (vb & p1);
    let rx_msg = (rx24 >> 12) & 0xFFF;
    let rx_par = rx24 & 0xFFF;
    let mut re_par = 0u32;
    for r in 0..12 {
        re_par |= ((rx_msg & ROWS[r]).count_ones() & 1) << r;
    }
    let syn12 = rx_par ^ re_par;
    let healed = if syn12.count_ones() <= 3 { rx_msg } else { msg12 };
    let cw_wt = cw24.count_ones() & 0xFF;
    (syn12 << 20) | (healed << 8) | cw_wt
}

#[inline(always)]
fn cpu_ref_k4_24cell(gid: u32, va: u32, vb: u32, p0: u32, p1: u32) -> u32 {
    let mut w0 = va & 0xFFFF;
    let mut w1 = (va >> 16) & 0xFFFF;
    let mut w2 = vb & 0xFFFF;
    let mut w3 = (vb >> 16) & 0xFFFF;
    let mut rk = p0 ^ gid.wrapping_mul(0x9E3779B9);
    for rnd in 0..4u32 {
        let s = (w0.wrapping_add(w1).wrapping_add(w2.wrapping_add(w3))) >> 1;
        let k0 = rk & 0xFFFF;
        let k1 = (rk >> 16) & 0xFFFF;
        let n0 = (s.wrapping_sub(w0) ^ k0) & 0xFFFF;
        let n1 = (s.wrapping_sub(w1) ^ k1) & 0xFFFF;
        let n2 = (s.wrapping_sub(w2) ^ (k0 ^ 0x5A5A)) & 0xFFFF;
        let n3 = (s.wrapping_sub(w3) ^ (k1 ^ 0xA5A5)) & 0xFFFF;
        w0 = n1; w1 = n2; w2 = n3; w3 = n0;
        rk = ((rk << 13) | (rk >> 19)).wrapping_add(p1 ^ 0x85EBCA6Bu32.wrapping_add(rnd));
    }
    (((w1 ^ w3) & 0xFFFF) << 16) | ((w0 ^ w2) & 0xFFFF)
}

#[inline(always)]
fn cpu_ref_k5_sheaf(va: u32, vb: u32, p0: u32, p1: u32) -> u32 {
    let sh = (p0 & 3) << 3;
    let inv_sh = 32u32.wrapping_sub(sh) & 31;
    let twisted = if sh == 0 { va } else { (va >> sh) | (va << inv_sh) };
    let transp = twisted ^ p1;
    let mut esq = 0u32;
    for f in 0..4 {
        let uf = (transp >> (8 * f)) & 0xFF;
        let vf = (vb >> (8 * f)) & 0xFF;
        let df = if uf > vf { uf - vf } else { vf - uf };
        esq = esq.wrapping_add(df * df);
    }
    let h1z = if esq == 0 { 1u32 } else { 0u32 };
    let dig = (transp ^ vb) & 0x7FFF;
    let ce = if esq <= 0xFFFF { esq } else { 0xFFFF };
    (ce << 16) | (dig << 1) | h1z
}

