fn cpu_ref_k7_intdot(va: u32, vb: u32, p0: u32, p1: u32) -> u32 {
    let mut w_packs = [0u32; 16];
    let mut k = 0usize;
    while k < 16 {
        let b0 = (((k * 5 + 1) % 15) as i32 + 1) as i8;
        let b1 = (((k * 3 + 4) % 15) as i32 - 7) as i8;
        let b2 = (((k * 7 + 2) % 15) as i32 - 7) as i8;
        let b3 = (((k * 11 + 6) % 15) as i32 - 7) as i8;
        w_packs[k] = (b0 as u8 as u32)
            | ((b1 as u8 as u32) << 8)
            | ((b2 as u8 as u32) << 16)
            | ((b3 as u8 as u32) << 24);
        k += 1;
    }
    let mut acur = va ^ p0;
    let mut bcur = vb ^ p1;
    let mut acc: i32 = 0;
    for _ in 0..8 {
        let xa = (acur & 0x3F3F_3F3F) ^ 0x2020_2020;
        let x0 = (xa & 0xFF) as u8 as i8 as i32;
        let x1 = ((xa >> 8) & 0xFF) as u8 as i8 as i32;
        let x2 = ((xa >> 16) & 0xFF) as u8 as i8 as i32;
        let x3 = ((xa >> 24) & 0xFF) as u8 as i8 as i32;
        for wp in w_packs {
            let wk = (bcur ^ wp) & 0x0F0F_0F0F;
            let w0 = (wk & 0xFF) as u8 as i8 as i32;
            let w1 = ((wk >> 8) & 0xFF) as u8 as i8 as i32;
            let w2 = ((wk >> 16) & 0xFF) as u8 as i8 as i32;
            let w3 = ((wk >> 24) & 0xFF) as u8 as i8 as i32;
            acc = acc.saturating_add(x0 * w0 + x1 * w1 + x2 * w2 + x3 * w3);
        }
        acur = acur.wrapping_add(0x9E37_79B9).rotate_left(7);
        bcur = bcur.wrapping_add(0x85EB_CA6B).rotate_left(11);
    }
    acc as u32
}

