struct DynVulkanLib { handle: *mut c_void }

#[cfg(target_os = "windows")]
#[link(name = "kernel32")]
extern "system" {
    fn LoadLibraryA(lp_lib_file_name: *const u8) -> *mut c_void;
    fn GetProcAddress(h_module: *mut c_void, lp_proc_name: *const u8) -> *mut c_void;
    fn FreeLibrary(h_lib_module: *mut c_void) -> i32;
}

#[cfg(all(any(target_os = "android", target_os = "linux"), not(target_env = "musl")))]
#[link(name = "dl")]
extern "C" {
    fn dlopen(filename: *const u8, flags: i32) -> *mut c_void;
    fn dlsym(handle: *mut c_void, symbol: *const u8) -> *mut c_void;
    fn dlerror() -> *const u8;
}

static CACHED_VULKAN_HANDLE: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
static CACHED_NNAPI_HANDLE: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
static CACHED_LIBC_HANDLE: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
static CACHED_ANDROID_HANDLE: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

impl DynVulkanLib {
    fn open() -> Result<Self, String> {
        let cached = CACHED_VULKAN_HANDLE.load(Ordering::Acquire);
        if cached != 0 {
            return Ok(Self { handle: cached as *mut c_void });
        }
        #[cfg(target_os = "windows")]
        unsafe {
            let h = LoadLibraryA(b"vulkan-1.dll\0".as_ptr());
            if !h.is_null() {
                CACHED_VULKAN_HANDLE.store(h as usize, Ordering::Release);
                return Ok(Self { handle: h });
            }
            return Err("vulkan-1.dll not found".to_string());
        }
        #[cfg(all(any(target_os = "android", target_os = "linux"), not(target_env = "musl")))]
        unsafe {
            let candidates: [&[u8]; 3] = [b"libvulkan.so\0", b"/system/lib64/libvulkan.so\0", b"libvulkan.so.1\0"];
            for c in candidates {
                let h = dlopen(c.as_ptr(), 2 | 256); // RTLD_NOW | RTLD_GLOBAL (immortal TLS-safe)
                if !h.is_null() {
                    CACHED_VULKAN_HANDLE.store(h as usize, Ordering::Release);
                    return Ok(Self { handle: h });
                }
                let h2 = dlopen(c.as_ptr(), 2);
                if !h2.is_null() {
                    CACHED_VULKAN_HANDLE.store(h2 as usize, Ordering::Release);
                    return Ok(Self { handle: h2 });
                }
            }
            if cfg!(all(target_os = "linux", target_arch = "aarch64")) { return Err("AVF crosvm guest CPU mode (host PowerVR Vulkan 1.4 active on :19788)".to_string()); }
            return Err("libvulkan.so not available in current namespace".to_string());
        }
        #[cfg(not(any(
            target_os = "windows",
            all(any(target_os = "android", target_os = "linux"), not(target_env = "musl"))
        )))]
        {
            Err("static-musl build (install Android NDK for Bionic libvulkan.so)".to_string())
        }
    }

    unsafe fn sym(&self, name_nul: &[u8]) -> *mut c_void {
        #[cfg(target_os = "windows")]
        { return GetProcAddress(self.handle, name_nul.as_ptr()); }
        #[cfg(all(any(target_os = "android", target_os = "linux"), not(target_env = "musl")))]
        { return dlsym(self.handle, name_nul.as_ptr()); }
        #[cfg(not(any(
            target_os = "windows",
            all(any(target_os = "android", target_os = "linux"), not(target_env = "musl"))
        )))]
        { let _ = name_nul; null_mut() }
    }
}

impl Drop for DynVulkanLib {
    fn drop(&mut self) {
        // Intentionally keep Vulkan loader/ICD handle resident for process lifetime:
        // prevents Bionic/glibc pthread TLS destructor SIGSEGV & crosvm gfxstream teardown crashes!
        let _ = self.handle;
    }
}

