fn vk_comp_type_short(ct: u32) -> &'static str {
    match ct {
        0 => "f16",
        1 => "f32",
        2 => "f64",
        3 => "s8",
        4 => "s16",
        5 => "s32",
        6 => "s64",
        7 => "u8",
        8 => "u16",
        9 => "u32",
        10 => "u64",
        1_000_141_000 => "bf16",
        1_000_491_002 => "fp8_e4m3",
        1_000_491_003 => "fp8_e5m2",
        _ => "ext",
    }
}

fn vk_scope_short(sc: u32) -> &'static str {
    match sc {
        1 => "Device",
        2 => "Workgroup",
        3 => "Subgroup",
        5 => "QueueFamily",
        _ => "ScopeOther",
    }
}

fn i32_to_f16_exact(v: i32) -> u16 {
    if v == 0 { return 0; }
    let sign: u16 = if v < 0 { 0x8000 } else { 0 };
    let mag: u32 = if v < 0 { (-v) as u32 } else { v as u32 };
    let msb: u32 = 31 - mag.leading_zeros();
    let exp: u16 = ((msb + 15) as u16) << 10;
    let rem: u32 = mag ^ (1u32 << msb);
    let mant: u16 = if msb <= 10 {
        ((rem << (10 - msb)) & 0x03FF) as u16
    } else {
        ((rem >> (msb - 10)) & 0x03FF) as u16
    };
    sign | exp | mant
}

struct SpvDynBuilder {
    next_id: u32,
    caps: Vec<u32>,
    exts: Vec<u32>,
    mem_model: Vec<u32>,
    entry_pts: Vec<u32>,
    exec_modes: Vec<u32>,
    annotations: Vec<u32>,
    types_consts: Vec<u32>,
    funcs: Vec<u32>,
}

impl SpvDynBuilder {
    fn new() -> Self {
        Self {
            next_id: 1,
            caps: Vec::with_capacity(16),
            exts: Vec::with_capacity(16),
            mem_model: Vec::with_capacity(4),
            entry_pts: Vec::with_capacity(16),
            exec_modes: Vec::with_capacity(8),
            annotations: Vec::with_capacity(96),
            types_consts: Vec::with_capacity(160),
            funcs: Vec::with_capacity(384),
        }
    }
    fn alloc_id(&mut self) -> u32 {
        let id = self.next_id;
        self.next_id += 1;
        id
    }
    fn push_inst(sec: &mut Vec<u32>, op: u16, args: &[u32]) {
        let wc = (1 + args.len()) as u32;
        sec.push((wc << 16) | (op as u32));
        sec.extend_from_slice(args);
    }
    fn encode_str(s: &str) -> Vec<u32> {
        let bytes = s.as_bytes();
        let total = bytes.len() + 1;
        let words = (total + 3) / 4;
        let mut out = vec![0u32; words];
        for (i, &b) in bytes.iter().enumerate() {
            out[i / 4] |= (b as u32) << ((i % 4) * 8);
        }
        out
    }
    fn finish(self) -> Vec<u32> {
        let total = 5
            + self.caps.len()
            + self.exts.len()
            + self.mem_model.len()
            + self.entry_pts.len()
            + self.exec_modes.len()
            + self.annotations.len()
            + self.types_consts.len()
            + self.funcs.len();
        let mut w = Vec::with_capacity(total);
        w.push(0x0723_0203);
        w.push(0x0001_0500);
        w.push(0);
        w.push(self.next_id);
        w.push(0);
        w.extend_from_slice(&self.caps);
        w.extend_from_slice(&self.exts);
        w.extend_from_slice(&self.mem_model);
        w.extend_from_slice(&self.entry_pts);
        w.extend_from_slice(&self.exec_modes);
        w.extend_from_slice(&self.annotations);
        w.extend_from_slice(&self.types_consts);
        w.extend_from_slice(&self.funcs);
        w
    }
}

fn k7_basis_packs() -> [u32; 16] {
    let mut w_packs = [0u32; 16];
    let mut k = 0usize;
    while k < 16 {
        let b0 = (((k * 5 + 1) % 15) as i32 + 1) as i8;
        let b1 = (((k * 3 + 4) % 15) as i32 - 7) as i8;
        let b2 = (((k * 7 + 2) % 15) as i32 - 7) as i8;
        let b3 = (((k * 11 + 6) % 15) as i32 - 7) as i8;
        w_packs[k] = (b0 as u8 as u32)
            | ((b1 as u8 as u32) << 8)
            | ((b2 as u8 as u32) << 16)
            | ((b3 as u8 as u32) << 24);
        k += 1;
    }
    w_packs
}

fn decode_idot_props27(flags: &[u32; 40]) -> (u32, u32, String) {
    let mut mask27: u32 = 0;
    for bit in 0..27usize {
        if flags[bit] != 0 {
            mask27 |= 1u32 << bit;
        }
    }
    // 8-bit Khronos VkPhysicalDeviceShaderIntegerDotProductProperties indices:
    //   0..2  : 8Bit (Unsigned, Signed, Mixed) -> <4 x i8> OpUDot / OpSDot / OpSUDot
    //   3..5  : 4x8BitPacked (Unsigned, Signed, Mixed) -> packed u32 OpUDot / OpSDot / OpSUDot
    //   15..17: AccumulatingSaturating8Bit (Unsigned, Signed, Mixed)
    //   18..20: AccumulatingSaturating4x8BitPacked (Unsigned, Signed, Mixed) [19 = Signed!]
    let mask_8b: u32 = mask27 & ((0b111u32 << 0) | (0b111u32 << 3) | (0b111u32 << 15) | (0b111u32 << 18));
    let mut tags: Vec<&'static str> = Vec::new();
    if (mask27 & (1 << 4)) != 0 { tags.push("pack4s8"); }
    if (mask27 & (1 << 3)) != 0 { tags.push("pack4u8"); }
    if (mask27 & (1 << 5)) != 0 { tags.push("pack4su8"); }
    if (mask27 & (1 << 19)) != 0 { tags.push("sat_pack4s8"); }
    if (mask27 & (1 << 18)) != 0 { tags.push("sat_pack4u8"); }
    if (mask27 & (1 << 1)) != 0 { tags.push("v4s8"); }
    if (mask27 & (1 << 0)) != 0 { tags.push("v4u8"); }
    if (mask27 & (1 << 16)) != 0 { tags.push("sat_v4s8"); }
    let summary = if tags.is_empty() {
        format!("0x{:07X}(drv_conservative)", mask27)
    } else {
        format!("0x{:07X}[{}]", mask27, tags.join("+"))
    };
    (mask27, mask_8b, summary)
}

fn emit_k7_intdot_spirv(mode: u32) -> Vec<u32> {
    // mode 0: OpSDot 4x8b (4450, PackedVectorFormat4x8Bit=0) + OpIAdd (128) [zero clamp overhead]
    // mode 1: OpSDotAccSat 4x8b (4453, PackedVectorFormat4x8Bit=0)          [fused saturating MAC]
    // mode 2: OpSDot v4i8 (4450 on <4 x i8> via OpBitcast 124) + OpIAdd     [vector v4i8 path]
    let mut b = SpvDynBuilder::new();
    SpvDynBuilder::push_inst(&mut b.caps, 17, &[1]);    // Shader
    if mode == 2 {
        SpvDynBuilder::push_inst(&mut b.caps, 17, &[39]);   // Int8
    }
    SpvDynBuilder::push_inst(&mut b.caps, 17, &[5345]); // VulkanMemoryModel
    SpvDynBuilder::push_inst(&mut b.caps, 17, &[6019]); // DotProductKHR
    if mode == 2 {
        SpvDynBuilder::push_inst(&mut b.caps, 17, &[6017]); // DotProductInput4x8BitKHR
    } else {
        SpvDynBuilder::push_inst(&mut b.caps, 17, &[6018]); // DotProductInput4x8BitPackedKHR
    }
    let ext_w = SpvDynBuilder::encode_str("SPV_KHR_integer_dot_product");
    SpvDynBuilder::push_inst(&mut b.exts, 10, &ext_w);
    SpvDynBuilder::push_inst(&mut b.mem_model, 14, &[0, 3]); // Logical(0), Vulkan(3)

    let t_void = b.alloc_id();
    let t_fn   = b.alloc_id();
    let t_u32  = b.alloc_id();
    let t_i32  = b.alloc_id();
    let (t_i8, t_v4i8) = if mode == 2 {
        (b.alloc_id(), b.alloc_id())
    } else {
        (0, 0)
    };
    let t_uvec3 = b.alloc_id();
    let t_ptr_in_uvec3 = b.alloc_id();
    let t_ptr_in_u32   = b.alloc_id();
    let v_gid          = b.alloc_id();

    let t_rta_a = b.alloc_id(); let t_st_a = b.alloc_id(); let t_psb_a = b.alloc_id(); let v_a = b.alloc_id();
    let t_rta_b = b.alloc_id(); let t_st_b = b.alloc_id(); let t_psb_b = b.alloc_id(); let v_b = b.alloc_id();
    let t_rta_o = b.alloc_id(); let t_st_o = b.alloc_id(); let t_psb_o = b.alloc_id(); let v_o = b.alloc_id();
    let t_pc_st = b.alloc_id(); let t_ppc_st = b.alloc_id(); let t_ppc_u32 = b.alloc_id(); let v_pc = b.alloc_id();
    let t_psb_u32 = b.alloc_id();
    let fn_main = b.alloc_id();

    let mut ep = vec![5, fn_main];
    ep.extend_from_slice(&SpvDynBuilder::encode_str("main"));
    ep.extend_from_slice(&[v_gid, v_a, v_b, v_o, v_pc]);
    SpvDynBuilder::push_inst(&mut b.entry_pts, 15, &ep);
    SpvDynBuilder::push_inst(&mut b.exec_modes, 16, &[fn_main, 17, 128, 1, 1]);

    SpvDynBuilder::push_inst(&mut b.annotations, 71, &[v_gid, 11, 28]); // GlobalInvocationId
    let sb_specs = [
        (t_rta_a, t_st_a, v_a, true),
        (t_rta_b, t_st_b, v_b, true),
        (t_rta_o, t_st_o, v_o, false),
    ];
    for (idx, &(rta, st, var, nonw)) in sb_specs.iter().enumerate() {
        SpvDynBuilder::push_inst(&mut b.annotations, 71, &[rta, 6, 4]);
        SpvDynBuilder::push_inst(&mut b.annotations, 72, &[st, 0, 35, 0]);
        SpvDynBuilder::push_inst(&mut b.annotations, 71, &[st, 2]);
        SpvDynBuilder::push_inst(&mut b.annotations, 71, &[var, 34, 0]);
        SpvDynBuilder::push_inst(&mut b.annotations, 71, &[var, 33, idx as u32]);
        if nonw {
            SpvDynBuilder::push_inst(&mut b.annotations, 71, &[var, 24]);
        }
    }
    SpvDynBuilder::push_inst(&mut b.annotations, 72, &[t_pc_st, 0, 35, 0]);
    SpvDynBuilder::push_inst(&mut b.annotations, 72, &[t_pc_st, 1, 35, 4]);
    SpvDynBuilder::push_inst(&mut b.annotations, 71, &[t_pc_st, 2]);

    SpvDynBuilder::push_inst(&mut b.types_consts, 19, &[t_void]);
    SpvDynBuilder::push_inst(&mut b.types_consts, 33, &[t_fn, t_void]);
    SpvDynBuilder::push_inst(&mut b.types_consts, 21, &[t_u32, 32, 0]);
    SpvDynBuilder::push_inst(&mut b.types_consts, 21, &[t_i32, 32, 1]);
    if mode == 2 {
        SpvDynBuilder::push_inst(&mut b.types_consts, 21, &[t_i8, 8, 1]);
        SpvDynBuilder::push_inst(&mut b.types_consts, 23, &[t_v4i8, t_i8, 4]);
    }
    SpvDynBuilder::push_inst(&mut b.types_consts, 23, &[t_uvec3, t_u32, 3]);
    SpvDynBuilder::push_inst(&mut b.types_consts, 32, &[t_ptr_in_uvec3, 1, t_uvec3]);
    SpvDynBuilder::push_inst(&mut b.types_consts, 32, &[t_ptr_in_u32, 1, t_u32]);
    SpvDynBuilder::push_inst(&mut b.types_consts, 59, &[t_ptr_in_uvec3, v_gid, 1]);

    for &(rta, st, psb, var) in &[
        (t_rta_a, t_st_a, t_psb_a, v_a),
        (t_rta_b, t_st_b, t_psb_b, v_b),
        (t_rta_o, t_st_o, t_psb_o, v_o),
    ] {
        SpvDynBuilder::push_inst(&mut b.types_consts, 29, &[rta, t_u32]);
        SpvDynBuilder::push_inst(&mut b.types_consts, 30, &[st, rta]);
        SpvDynBuilder::push_inst(&mut b.types_consts, 32, &[psb, 12, st]);
        SpvDynBuilder::push_inst(&mut b.types_consts, 59, &[psb, var, 12]);
    }

    SpvDynBuilder::push_inst(&mut b.types_consts, 30, &[t_pc_st, t_u32, t_u32]);
    SpvDynBuilder::push_inst(&mut b.types_consts, 32, &[t_ppc_st, 9, t_pc_st]);
    SpvDynBuilder::push_inst(&mut b.types_consts, 32, &[t_ppc_u32, 9, t_u32]);
    SpvDynBuilder::push_inst(&mut b.types_consts, 59, &[t_ppc_st, v_pc, 9]);
    SpvDynBuilder::push_inst(&mut b.types_consts, 32, &[t_psb_u32, 12, t_u32]);

    let mut u_consts: Vec<(u32, u32)> = Vec::with_capacity(32);
    let mut get_cu = |b_ref: &mut SpvDynBuilder, val: u32| -> u32 {
        for &(v, cid) in &u_consts {
            if v == val { return cid; }
        }
        let cid = b_ref.alloc_id();
        SpvDynBuilder::push_inst(&mut b_ref.types_consts, 43, &[t_u32, cid, val]);
        u_consts.push((val, cid));
        cid
    };

    let ci0 = b.alloc_id();
    SpvDynBuilder::push_inst(&mut b.types_consts, 43, &[t_i32, ci0, 0]);
    let cu0       = get_cu(&mut b, 0);
    let cu1       = get_cu(&mut b, 1);
    let cu_m3f    = get_cu(&mut b, 0x3F3F_3F3F);
    let cu_x20    = get_cu(&mut b, 0x2020_2020);
    let cu_m0f    = get_cu(&mut b, 0x0F0F_0F0F);
    let cu_gold_a = get_cu(&mut b, 0x9E37_79B9);
    let cu_gold_b = get_cu(&mut b, 0x85EB_CA6B);
    let cu_7      = get_cu(&mut b, 7);
    let cu_25     = get_cu(&mut b, 25);
    let cu_11     = get_cu(&mut b, 11);
    let cu_21     = get_cu(&mut b, 21);
    let raw_packs = k7_basis_packs();
    let mut w_ids = [0u32; 16];
    for k in 0..16usize {
        w_ids[k] = get_cu(&mut b, raw_packs[k]);
    }

    let l_entry = b.alloc_id();
    SpvDynBuilder::push_inst(&mut b.funcs, 54, &[t_void, fn_main, 0, t_fn]);
    SpvDynBuilder::push_inst(&mut b.funcs, 248, &[l_entry]);

    let p_gx = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 65, &[t_ptr_in_u32, p_gx, v_gid, cu0]);
    let gx   = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 61, &[t_u32, gx, p_gx]);
    let p_p0 = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 65, &[t_ppc_u32, p_p0, v_pc, cu0]);
    let p0   = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 61, &[t_u32, p0, p_p0]);
    let p_p1 = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 65, &[t_ppc_u32, p_p1, v_pc, cu1]);
    let p1   = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 61, &[t_u32, p1, p_p1]);

    let pa = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 65, &[t_psb_u32, pa, v_a, cu0, gx]);
    let va = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 61, &[t_u32, va, pa]);
    let pb = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 65, &[t_psb_u32, pb, v_b, cu0, gx]);
    let vb = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 61, &[t_u32, vb, pb]);

    let mut acur = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 198, &[t_u32, acur, va, p0]);
    let mut bcur = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 198, &[t_u32, bcur, vb, p1]);

    let mut acc = ci0;
    for _r in 0..8usize {
        let am = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 199, &[t_u32, am, acur, cu_m3f]);
        let xa = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 198, &[t_u32, xa, am, cu_x20]);
        let xa_v4 = if mode == 2 {
            let v = b.alloc_id();
            SpvDynBuilder::push_inst(&mut b.funcs, 124, &[t_v4i8, v, xa]);
            v
        } else {
            0
        };
        for k in 0..16usize {
            let bx = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 198, &[t_u32, bx, bcur, w_ids[k]]);
            let wk = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 199, &[t_u32, wk, bx, cu_m0f]);
            if mode == 0 {
                let dot = b.alloc_id();
                SpvDynBuilder::push_inst(&mut b.funcs, 4450, &[t_i32, dot, xa, wk, 0]);
                let nacc = b.alloc_id();
                SpvDynBuilder::push_inst(&mut b.funcs, 128, &[t_i32, nacc, acc, dot]);
                acc = nacc;
            } else if mode == 1 {
                let nacc = b.alloc_id();
                SpvDynBuilder::push_inst(&mut b.funcs, 4453, &[t_i32, nacc, xa, wk, acc, 0]);
                acc = nacc;
            } else {
                let wk_v4 = b.alloc_id();
                SpvDynBuilder::push_inst(&mut b.funcs, 124, &[t_v4i8, wk_v4, wk]);
                let dot = b.alloc_id();
                SpvDynBuilder::push_inst(&mut b.funcs, 4450, &[t_i32, dot, xa_v4, wk_v4]);
                let nacc = b.alloc_id();
                SpvDynBuilder::push_inst(&mut b.funcs, 128, &[t_i32, nacc, acc, dot]);
                acc = nacc;
            }
        }
        let a_add = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 128, &[t_u32, a_add, acur, cu_gold_a]);
        let a_shl = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 196, &[t_u32, a_shl, a_add, cu_7]);
        let a_shr = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 194, &[t_u32, a_shr, a_add, cu_25]);
        acur      = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 197, &[t_u32, acur, a_shl, a_shr]);

        let b_add = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 128, &[t_u32, b_add, bcur, cu_gold_b]);
        let b_shl = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 196, &[t_u32, b_shl, b_add, cu_11]);
        let b_shr = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 194, &[t_u32, b_shr, b_add, cu_21]);
        bcur      = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 197, &[t_u32, bcur, b_shl, b_shr]);
    }

    let out_u = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 124, &[t_u32, out_u, acc]);
    let po    = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 65, &[t_psb_u32, po, v_o, cu0, gx]);
    SpvDynBuilder::push_inst(&mut b.funcs, 62, &[po, out_u]);
    SpvDynBuilder::push_inst(&mut b.funcs, 253, &[]);
    SpvDynBuilder::push_inst(&mut b.funcs, 56, &[]);
    b.finish()
}

fn k10_u8_basis_packs() -> [u32; 16] {
    let mut u_packs = [0u32; 16];
    let mut k = 0usize;
    while k < 16 {
        let u0 = (((k * 7 + 3) % 29) + 1) as u32;
        let u1 = (((k * 11 + 5) % 29) + 1) as u32;
        let u2 = (((k * 13 + 9) % 29) + 1) as u32;
        let u3 = (((k * 17 + 2) % 29) + 1) as u32;
        u_packs[k] = (u0 & 0xFF)
            | ((u1 & 0xFF) << 8)
            | ((u2 & 0xFF) << 16)
            | ((u3 & 0xFF) << 24);
        k += 1;
    }
    u_packs
}

fn cpu_ref_k10_udot(va: u32, vb: u32, p0: u32, p1: u32) -> u32 {
    let u_packs = k10_u8_basis_packs();
    let mut acur = va ^ p0;
    let mut bcur = vb ^ p1;
    let mut acc: u32 = 0;
    for _ in 0..8 {
        // Zero-point-shifted [128..191] unsigned activations (MSB=1 strictly proves u8 x u8 -> u32!)
        let ua = (acur & 0x3F3F_3F3F) ^ 0x8080_8080;
        let a0 = ua & 0xFF;
        let a1 = (ua >> 8) & 0xFF;
        let a2 = (ua >> 16) & 0xFF;
        let a3 = (ua >> 24) & 0xFF;
        for up in u_packs {
            let uw = (bcur ^ up) & 0x1F1F_1F1F;
            let w0 = uw & 0xFF;
            let w1 = (uw >> 8) & 0xFF;
            let w2 = (uw >> 16) & 0xFF;
            let w3 = (uw >> 24) & 0xFF;
            acc = acc.wrapping_add(a0 * w0 + a1 * w1 + a2 * w2 + a3 * w3);
        }
        acur = acur.wrapping_add(0x9E37_79B9).rotate_left(7);
        bcur = bcur.wrapping_add(0x85EB_CA6B).rotate_left(11);
    }
    acc.wrapping_sub(0x0008_0000)
}

fn emit_k10_udot_spirv(mode: u32) -> Vec<u32> {
    // Directly targets PowerVR DXT-48-1536 vk=0x0040008 [pack4u8 (bit 3) + sat_pack4u8 (bit 18)]:
    //   mode 0: OpUDot 4x8b (4451, PackedVectorFormat4x8Bit=0) + OpIAdd (128) [bit 3: pack4u8]
    //   mode 1: OpUDotAccSat 4x8b (4454, PackedVectorFormat4x8Bit=0)          [bit 18: sat_pack4u8]
    //   mode 2: OpUDot v4u8 (4451 on <4 x u8> via OpBitcast 124) + OpIAdd     [vector v4u8 path]
    let mut b = SpvDynBuilder::new();
    SpvDynBuilder::push_inst(&mut b.caps, 17, &[1]);    // Shader
    if mode == 2 {
        SpvDynBuilder::push_inst(&mut b.caps, 17, &[39]);   // Int8
    }
    SpvDynBuilder::push_inst(&mut b.caps, 17, &[5345]); // VulkanMemoryModel
    SpvDynBuilder::push_inst(&mut b.caps, 17, &[6019]); // DotProductKHR
    if mode == 2 {
        SpvDynBuilder::push_inst(&mut b.caps, 17, &[6017]); // DotProductInput4x8BitKHR
    } else {
        SpvDynBuilder::push_inst(&mut b.caps, 17, &[6018]); // DotProductInput4x8BitPackedKHR
    }
    let ext_w = SpvDynBuilder::encode_str("SPV_KHR_integer_dot_product");
    SpvDynBuilder::push_inst(&mut b.exts, 10, &ext_w);
    SpvDynBuilder::push_inst(&mut b.mem_model, 14, &[0, 3]);

    let t_void = b.alloc_id();
    let t_fn   = b.alloc_id();
    let t_u32  = b.alloc_id();
    let (t_u8, t_v4u8) = if mode == 2 { (b.alloc_id(), b.alloc_id()) } else { (0, 0) };
    let t_uvec3 = b.alloc_id();
    let t_ptr_in_uvec3 = b.alloc_id();
    let t_ptr_in_u32   = b.alloc_id();
    let v_gid          = b.alloc_id();

    let t_rta_a = b.alloc_id(); let t_st_a = b.alloc_id(); let t_psb_a = b.alloc_id(); let v_a = b.alloc_id();
    let t_rta_b = b.alloc_id(); let t_st_b = b.alloc_id(); let t_psb_b = b.alloc_id(); let v_b = b.alloc_id();
    let t_rta_o = b.alloc_id(); let t_st_o = b.alloc_id(); let t_psb_o = b.alloc_id(); let v_o = b.alloc_id();
    let t_pc_st = b.alloc_id(); let t_ppc_st = b.alloc_id(); let t_ppc_u32 = b.alloc_id(); let v_pc = b.alloc_id();
    let t_psb_u32 = b.alloc_id();
    let fn_main = b.alloc_id();

    let mut ep = vec![5, fn_main];
    ep.extend_from_slice(&SpvDynBuilder::encode_str("main"));
    ep.extend_from_slice(&[v_gid, v_a, v_b, v_o, v_pc]);
    SpvDynBuilder::push_inst(&mut b.entry_pts, 15, &ep);
    SpvDynBuilder::push_inst(&mut b.exec_modes, 16, &[fn_main, 17, 128, 1, 1]);

    SpvDynBuilder::push_inst(&mut b.annotations, 71, &[v_gid, 11, 28]);
    let sb_specs = [
        (t_rta_a, t_st_a, v_a, true),
        (t_rta_b, t_st_b, v_b, true),
        (t_rta_o, t_st_o, v_o, false),
    ];
    for (idx, &(rta, st, var, nonw)) in sb_specs.iter().enumerate() {
        SpvDynBuilder::push_inst(&mut b.annotations, 71, &[rta, 6, 4]);
        SpvDynBuilder::push_inst(&mut b.annotations, 72, &[st, 0, 35, 0]);
        SpvDynBuilder::push_inst(&mut b.annotations, 71, &[st, 2]);
        SpvDynBuilder::push_inst(&mut b.annotations, 71, &[var, 34, 0]);
        SpvDynBuilder::push_inst(&mut b.annotations, 71, &[var, 33, idx as u32]);
        if nonw {
            SpvDynBuilder::push_inst(&mut b.annotations, 71, &[var, 24]);
        }
    }
    SpvDynBuilder::push_inst(&mut b.annotations, 72, &[t_pc_st, 0, 35, 0]);
    SpvDynBuilder::push_inst(&mut b.annotations, 72, &[t_pc_st, 1, 35, 4]);
    SpvDynBuilder::push_inst(&mut b.annotations, 71, &[t_pc_st, 2]);

    SpvDynBuilder::push_inst(&mut b.types_consts, 19, &[t_void]);
    SpvDynBuilder::push_inst(&mut b.types_consts, 33, &[t_fn, t_void]);
    SpvDynBuilder::push_inst(&mut b.types_consts, 21, &[t_u32, 32, 0]);
    if mode == 2 {
        SpvDynBuilder::push_inst(&mut b.types_consts, 21, &[t_u8, 8, 0]); // Unsigned 8-bit integer!
        SpvDynBuilder::push_inst(&mut b.types_consts, 23, &[t_v4u8, t_u8, 4]);
    }
    SpvDynBuilder::push_inst(&mut b.types_consts, 23, &[t_uvec3, t_u32, 3]);
    SpvDynBuilder::push_inst(&mut b.types_consts, 32, &[t_ptr_in_uvec3, 1, t_uvec3]);
    SpvDynBuilder::push_inst(&mut b.types_consts, 32, &[t_ptr_in_u32, 1, t_u32]);
    SpvDynBuilder::push_inst(&mut b.types_consts, 59, &[t_ptr_in_uvec3, v_gid, 1]);

    for &(rta, st, psb, var) in &[
        (t_rta_a, t_st_a, t_psb_a, v_a),
        (t_rta_b, t_st_b, t_psb_b, v_b),
        (t_rta_o, t_st_o, t_psb_o, v_o),
    ] {
        SpvDynBuilder::push_inst(&mut b.types_consts, 29, &[rta, t_u32]);
        SpvDynBuilder::push_inst(&mut b.types_consts, 30, &[st, rta]);
        SpvDynBuilder::push_inst(&mut b.types_consts, 32, &[psb, 12, st]);
        SpvDynBuilder::push_inst(&mut b.types_consts, 59, &[psb, var, 12]);
    }

    SpvDynBuilder::push_inst(&mut b.types_consts, 30, &[t_pc_st, t_u32, t_u32]);
    SpvDynBuilder::push_inst(&mut b.types_consts, 32, &[t_ppc_st, 9, t_pc_st]);
    SpvDynBuilder::push_inst(&mut b.types_consts, 32, &[t_ppc_u32, 9, t_u32]);
    SpvDynBuilder::push_inst(&mut b.types_consts, 59, &[t_ppc_st, v_pc, 9]);
    SpvDynBuilder::push_inst(&mut b.types_consts, 32, &[t_psb_u32, 12, t_u32]);

    let mut u_consts: Vec<(u32, u32)> = Vec::with_capacity(32);
    let mut get_cu = |b_ref: &mut SpvDynBuilder, val: u32| -> u32 {
        for &(v, cid) in &u_consts {
            if v == val { return cid; }
        }
        let cid = b_ref.alloc_id();
        SpvDynBuilder::push_inst(&mut b_ref.types_consts, 43, &[t_u32, cid, val]);
        u_consts.push((val, cid));
        cid
    };

    let cu0        = get_cu(&mut b, 0);
    let cu1        = get_cu(&mut b, 1);
    let cu_m3f     = get_cu(&mut b, 0x3F3F_3F3F);
    let cu_zp80    = get_cu(&mut b, 0x8080_8080);
    let cu_m1f     = get_cu(&mut b, 0x1F1F_1F1F);
    let cu_gold_a  = get_cu(&mut b, 0x9E37_79B9);
    let cu_gold_b  = get_cu(&mut b, 0x85EB_CA6B);
    let cu_7       = get_cu(&mut b, 7);
    let cu_25      = get_cu(&mut b, 25);
    let cu_11      = get_cu(&mut b, 11);
    let cu_21      = get_cu(&mut b, 21);
    let cu_zp_bias = get_cu(&mut b, 0x0008_0000);
    let raw_upacks = k10_u8_basis_packs();
    let mut w_ids = [0u32; 16];
    for k in 0..16usize {
        w_ids[k] = get_cu(&mut b, raw_upacks[k]);
    }

    let l_entry = b.alloc_id();
    SpvDynBuilder::push_inst(&mut b.funcs, 54, &[t_void, fn_main, 0, t_fn]);
    SpvDynBuilder::push_inst(&mut b.funcs, 248, &[l_entry]);

    let p_gx = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 65, &[t_ptr_in_u32, p_gx, v_gid, cu0]);
    let gx   = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 61, &[t_u32, gx, p_gx]);
    let p_p0 = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 65, &[t_ppc_u32, p_p0, v_pc, cu0]);
    let p0   = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 61, &[t_u32, p0, p_p0]);
    let p_p1 = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 65, &[t_ppc_u32, p_p1, v_pc, cu1]);
    let p1   = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 61, &[t_u32, p1, p_p1]);

    let pa = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 65, &[t_psb_u32, pa, v_a, cu0, gx]);
    let va = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 61, &[t_u32, va, pa]);
    let pb = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 65, &[t_psb_u32, pb, v_b, cu0, gx]);
    let vb = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 61, &[t_u32, vb, pb]);

    let mut acur = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 198, &[t_u32, acur, va, p0]);
    let mut bcur = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 198, &[t_u32, bcur, vb, p1]);

    let mut acc = cu0;
    for _r in 0..8usize {
        let am = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 199, &[t_u32, am, acur, cu_m3f]);
        let ua = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 198, &[t_u32, ua, am, cu_zp80]);
        let ua_v4 = if mode == 2 {
            let v = b.alloc_id();
            SpvDynBuilder::push_inst(&mut b.funcs, 124, &[t_v4u8, v, ua]);
            v
        } else {
            0
        };
        for k in 0..16usize {
            let bx = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 198, &[t_u32, bx, bcur, w_ids[k]]);
            let uw = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 199, &[t_u32, uw, bx, cu_m1f]);
            if mode == 0 {
                // OpUDot (4451) packed 4x8b + OpIAdd (128)
                let dot = b.alloc_id();
                SpvDynBuilder::push_inst(&mut b.funcs, 4451, &[t_u32, dot, ua, uw, 0]);
                let nacc = b.alloc_id();
                SpvDynBuilder::push_inst(&mut b.funcs, 128, &[t_u32, nacc, acc, dot]);
                acc = nacc;
            } else if mode == 1 {
                // OpUDotAccSat (4454) packed 4x8b
                let nacc = b.alloc_id();
                SpvDynBuilder::push_inst(&mut b.funcs, 4454, &[t_u32, nacc, ua, uw, acc, 0]);
                acc = nacc;
            } else {
                // OpUDot (4451) <4 x u8> vector + OpIAdd (128)
                let uw_v4 = b.alloc_id();
                SpvDynBuilder::push_inst(&mut b.funcs, 124, &[t_v4u8, uw_v4, uw]);
                let dot = b.alloc_id();
                SpvDynBuilder::push_inst(&mut b.funcs, 4451, &[t_u32, dot, ua_v4, uw_v4]);
                let nacc = b.alloc_id();
                SpvDynBuilder::push_inst(&mut b.funcs, 128, &[t_u32, nacc, acc, dot]);
                acc = nacc;
            }
        }
        let a_add = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 128, &[t_u32, a_add, acur, cu_gold_a]);
        let a_shl = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 196, &[t_u32, a_shl, a_add, cu_7]);
        let a_shr = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 194, &[t_u32, a_shr, a_add, cu_25]);
        acur      = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 197, &[t_u32, acur, a_shl, a_shr]);

        let b_add = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 128, &[t_u32, b_add, bcur, cu_gold_b]);
        let b_shl = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 196, &[t_u32, b_shl, b_add, cu_11]);
        let b_shr = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 194, &[t_u32, b_shr, b_add, cu_21]);
        bcur      = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 197, &[t_u32, bcur, b_shl, b_shr]);
    }

    let out_u = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 130, &[t_u32, out_u, acc, cu_zp_bias]);
    let po    = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 65, &[t_psb_u32, po, v_o, cu0, gx]);
    SpvDynBuilder::push_inst(&mut b.funcs, 62, &[po, out_u]);
    SpvDynBuilder::push_inst(&mut b.funcs, 253, &[]);
    SpvDynBuilder::push_inst(&mut b.funcs, 56, &[]);
    b.finish()
}

#[derive(Copy, Clone, PartialEq, Eq)]
struct ScalarSpec {
    is_float: bool,
    bits: u32,
    signed: u32,
    bytes: u32,
}

fn coop_scalar_spec(ct: u32) -> Option<ScalarSpec> {
    match ct {
        0 => Some(ScalarSpec { is_float: true,  bits: 16, signed: 0, bytes: 2 }),
        1 => Some(ScalarSpec { is_float: true,  bits: 32, signed: 0, bytes: 4 }),
        3 => Some(ScalarSpec { is_float: false, bits: 8,  signed: 1, bytes: 1 }),
        4 => Some(ScalarSpec { is_float: false, bits: 16, signed: 1, bytes: 2 }),
        5 => Some(ScalarSpec { is_float: false, bits: 32, signed: 1, bytes: 4 }),
        7 => Some(ScalarSpec { is_float: false, bits: 8,  signed: 0, bytes: 1 }),
        8 => Some(ScalarSpec { is_float: false, bits: 16, signed: 0, bytes: 2 }),
        9 => Some(ScalarSpec { is_float: false, bits: 32, signed: 0, bytes: 4 }),
        _ => None,
    }
}

#[derive(Copy, Clone)]
struct CoopRecipe {
    local_sz: u32,
    req_sg: u32,
    u32_ptrs: bool,
    stride_scalars: bool,
    b_col_major: bool,
    mma_total: u32,
}

fn emit_coopmat_spirv(
    tile: &VkCooperativeMatrixPropertiesKHR,
    rec: &CoopRecipe,
) -> Option<Vec<u32>> {
    if tile.scope != 3 || tile.c_type != tile.result_type {
        return None;
    }
    let ka = coop_scalar_spec(tile.a_type)?;
    let kb = coop_scalar_spec(tile.b_type)?;
    let kc = coop_scalar_spec(tile.c_type)?;

    let mut b = SpvDynBuilder::new();
    let mut cap_list: Vec<u32> = Vec::new();
    let mut add_cap = |c: u32, caps_vec: &mut Vec<u32>| {
        if !cap_list.contains(&c) {
            cap_list.push(c);
            SpvDynBuilder::push_inst(caps_vec, 17, &[c]);
        }
    };
    add_cap(1, &mut b.caps);    // Shader
    add_cap(5345, &mut b.caps); // VulkanMemoryModel
    add_cap(61, &mut b.caps);   // GroupNonUniform (NumSubgroups + SubgroupId)
    add_cap(6022, &mut b.caps); // CooperativeMatrixKHR
    for sp in [ka, kb, kc] {
        if sp.is_float && sp.bits == 16 { add_cap(9, &mut b.caps); }   // Float16
        if !sp.is_float && sp.bits == 8 { add_cap(39, &mut b.caps); }  // Int8
        if !sp.is_float && sp.bits == 16 { add_cap(22, &mut b.caps); } // Int16
    }
    if !rec.u32_ptrs {
        for sp in [ka, kb, kc] {
            if sp.bytes == 2 { add_cap(4433, &mut b.caps); } // StorageBuffer16BitAccess
            if sp.bytes == 1 { add_cap(4448, &mut b.caps); } // StorageBuffer8BitAccess
        }
    }

    let ext_words = SpvDynBuilder::encode_str("SPV_KHR_cooperative_matrix");
    SpvDynBuilder::push_inst(&mut b.exts, 10, &ext_words);
    SpvDynBuilder::push_inst(&mut b.mem_model, 14, &[0, 3]); // Logical(0), Vulkan(3)

    let t_void = b.alloc_id();
    let t_fn   = b.alloc_id();
    let t_u32  = b.alloc_id();
    let t_uvec3 = b.alloc_id();
    let t_ptr_in_uvec3 = b.alloc_id();
    let t_ptr_in_u32   = b.alloc_id();
    let v_wgid         = b.alloc_id();
    let v_numsg        = b.alloc_id();
    let v_sgid         = b.alloc_id();

    let t_rta_a = b.alloc_id(); let t_st_a = b.alloc_id(); let t_psb_st_a = b.alloc_id(); let v_buf_a = b.alloc_id();
    let t_rta_b = b.alloc_id(); let t_st_b = b.alloc_id(); let t_psb_st_b = b.alloc_id(); let v_buf_b = b.alloc_id();
    let t_rta_c = b.alloc_id(); let t_st_c = b.alloc_id(); let t_psb_st_c = b.alloc_id(); let v_buf_c = b.alloc_id();
    let t_rta_d = b.alloc_id(); let t_st_d = b.alloc_id(); let t_psb_st_d = b.alloc_id(); let v_buf_d = b.alloc_id();
    let fn_main = b.alloc_id();

    let mut ep = vec![5, fn_main];
    ep.extend_from_slice(&SpvDynBuilder::encode_str("main"));
    ep.extend_from_slice(&[v_wgid, v_numsg, v_sgid, v_buf_a, v_buf_b, v_buf_c, v_buf_d]);
    SpvDynBuilder::push_inst(&mut b.entry_pts, 15, &ep);
    SpvDynBuilder::push_inst(&mut b.exec_modes, 16, &[fn_main, 17, rec.local_sz, 1, 1]);

    // Decorations
    SpvDynBuilder::push_inst(&mut b.annotations, 71, &[v_wgid,  11, 26]); // WorkgroupId
    SpvDynBuilder::push_inst(&mut b.annotations, 71, &[v_numsg, 11, 38]); // NumSubgroups
    SpvDynBuilder::push_inst(&mut b.annotations, 71, &[v_sgid,  11, 40]); // SubgroupId
    let ab_stride_bytes = if rec.u32_ptrs { 4 } else { ka.bytes };
    let bb_stride_bytes = if rec.u32_ptrs { 4 } else { kb.bytes };
    let cd_stride_bytes = if rec.u32_ptrs { 4 } else { kc.bytes };
    let bind_specs = [
        (t_rta_a, t_st_a, v_buf_a, ab_stride_bytes, true),
        (t_rta_b, t_st_b, v_buf_b, bb_stride_bytes, true),
        (t_rta_c, t_st_c, v_buf_c, cd_stride_bytes, true),
        (t_rta_d, t_st_d, v_buf_d, cd_stride_bytes, false),
    ];
    for (idx, &(rta, st, var, sb, nonw)) in bind_specs.iter().enumerate() {
        SpvDynBuilder::push_inst(&mut b.annotations, 71, &[rta, 6, sb]);
        SpvDynBuilder::push_inst(&mut b.annotations, 72, &[st, 0, 35, 0]);
        SpvDynBuilder::push_inst(&mut b.annotations, 71, &[st, 2]);
        SpvDynBuilder::push_inst(&mut b.annotations, 71, &[var, 34, 0]);
        SpvDynBuilder::push_inst(&mut b.annotations, 71, &[var, 33, idx as u32]);
        if nonw {
            SpvDynBuilder::push_inst(&mut b.annotations, 71, &[var, 24]);
        }
    }

    // Types & Constants (strictly deduplicated)
    SpvDynBuilder::push_inst(&mut b.types_consts, 19, &[t_void]);
    SpvDynBuilder::push_inst(&mut b.types_consts, 33, &[t_fn, t_void]);
    SpvDynBuilder::push_inst(&mut b.types_consts, 21, &[t_u32, 32, 0]);

    let mut scalar_cache: Vec<(ScalarSpec, u32)> = vec![(
        ScalarSpec { is_float: false, bits: 32, signed: 0, bytes: 4 },
        t_u32,
    )];
    let mut get_scalar = |sp: ScalarSpec, bld: &mut SpvDynBuilder| -> u32 {
        for &(k, id) in &scalar_cache {
            if k == sp { return id; }
        }
        let id = bld.alloc_id();
        if sp.is_float {
            SpvDynBuilder::push_inst(&mut bld.types_consts, 22, &[id, sp.bits]);
        } else {
            SpvDynBuilder::push_inst(&mut bld.types_consts, 21, &[id, sp.bits, sp.signed]);
        }
        scalar_cache.push((sp, id));
        id
    };

    let t_comp_a = get_scalar(ka, &mut b);
    let t_comp_b = get_scalar(kb, &mut b);
    let t_comp_c = get_scalar(kc, &mut b);

    SpvDynBuilder::push_inst(&mut b.types_consts, 23, &[t_uvec3, t_u32, 3]);
    SpvDynBuilder::push_inst(&mut b.types_consts, 32, &[t_ptr_in_uvec3, 1, t_uvec3]);
    SpvDynBuilder::push_inst(&mut b.types_consts, 32, &[t_ptr_in_u32,   1, t_u32]);
    SpvDynBuilder::push_inst(&mut b.types_consts, 59, &[t_ptr_in_uvec3, v_wgid,  1]);
    SpvDynBuilder::push_inst(&mut b.types_consts, 59, &[t_ptr_in_u32,   v_numsg, 1]);
    SpvDynBuilder::push_inst(&mut b.types_consts, 59, &[t_ptr_in_u32,   v_sgid,  1]);

    let t_elem_a = if rec.u32_ptrs { t_u32 } else { t_comp_a };
    let t_elem_b = if rec.u32_ptrs { t_u32 } else { t_comp_b };
    let t_elem_c = if rec.u32_ptrs { t_u32 } else { t_comp_c };

    let mut ptr_cache: Vec<(u32, u32)> = Vec::new();
    let mut get_psb = |elem_t: u32, bld: &mut SpvDynBuilder| -> u32 {
        for &(et, pid) in &ptr_cache {
            if et == elem_t { return pid; }
        }
        let pid = bld.alloc_id();
        SpvDynBuilder::push_inst(&mut bld.types_consts, 32, &[pid, 12, elem_t]);
        ptr_cache.push((elem_t, pid));
        pid
    };

    let t_psb_elem_a = get_psb(t_elem_a, &mut b);
    let t_psb_elem_b = get_psb(t_elem_b, &mut b);
    let t_psb_elem_c = get_psb(t_elem_c, &mut b);

    for &(rta, st, psb_st, var, elem_t) in &[
        (t_rta_a, t_st_a, t_psb_st_a, v_buf_a, t_elem_a),
        (t_rta_b, t_st_b, t_psb_st_b, v_buf_b, t_elem_b),
        (t_rta_c, t_st_c, t_psb_st_c, v_buf_c, t_elem_c),
        (t_rta_d, t_st_d, t_psb_st_d, v_buf_d, t_elem_c),
    ] {
        SpvDynBuilder::push_inst(&mut b.types_consts, 29, &[rta, elem_t]);
        SpvDynBuilder::push_inst(&mut b.types_consts, 30, &[st, rta]);
        SpvDynBuilder::push_inst(&mut b.types_consts, 32, &[psb_st, 12, st]);
        SpvDynBuilder::push_inst(&mut b.types_consts, 59, &[psb_st, var, 12]);
    }

    let mut u32_consts: Vec<(u32, u32)> = Vec::new();
    let mut cu = |val: u32, bld: &mut SpvDynBuilder| -> u32 {
        for &(v, cid) in &u32_consts {
            if v == val { return cid; }
        }
        let cid = bld.alloc_id();
        SpvDynBuilder::push_inst(&mut bld.types_consts, 43, &[t_u32, cid, val]);
        u32_consts.push((val, cid));
        cid
    };

    let cu0 = cu(0, &mut b);
    let cu1 = cu(1, &mut b);
    let cu2 = cu(2, &mut b);
    let cu_scope = cu(3, &mut b);
    let cu_m = cu(tile.m_size, &mut b);
    let cu_n = cu(tile.n_size, &mut b);
    let cu_k = cu(tile.k_size, &mut b);

    let t_coop_a = b.alloc_id();
    SpvDynBuilder::push_inst(&mut b.types_consts, 4456, &[t_coop_a, t_comp_a, cu_scope, cu_m, cu_k, cu0]);
    let t_coop_b = b.alloc_id();
    SpvDynBuilder::push_inst(&mut b.types_consts, 4456, &[t_coop_b, t_comp_b, cu_scope, cu_k, cu_n, cu1]);
    let t_coop_c = b.alloc_id();
    SpvDynBuilder::push_inst(&mut b.types_consts, 4456, &[t_coop_c, t_comp_c, cu_scope, cu_m, cu_n, cu2]);

    let row_bytes_a = ((tile.k_size * ka.bytes + 15) / 16) * 16;
    let lead_dim_b  = if rec.b_col_major { tile.k_size } else { tile.n_size };
    let outer_dim_b = if rec.b_col_major { tile.n_size } else { tile.k_size };
    let row_bytes_b = ((lead_dim_b * kb.bytes + 15) / 16) * 16;
    let row_bytes_c = ((tile.n_size * kc.bytes + 15) / 16) * 16;

    let stride_a = if rec.stride_scalars { row_bytes_a / ka.bytes } else { row_bytes_a / ab_stride_bytes };
    let stride_b = if rec.stride_scalars { row_bytes_b / kb.bytes } else { row_bytes_b / bb_stride_bytes };
    let stride_c = if rec.stride_scalars { row_bytes_c / kc.bytes } else { row_bytes_c / cd_stride_bytes };

    let a_tile_elems = tile.m_size * (row_bytes_a / ab_stride_bytes);
    let b_tile_elems = outer_dim_b * (row_bytes_b / bb_stride_bytes);
    let c_tile_elems = tile.m_size * (row_bytes_c / cd_stride_bytes);

    let c_stride_a = cu(stride_a, &mut b);
    let c_stride_b = cu(stride_b, &mut b);
    let c_stride_c = cu(stride_c, &mut b);
    let c_a_tile   = cu(a_tile_elems, &mut b);
    let c_2a_tile  = cu(2 * a_tile_elems, &mut b);
    let c_b_tile   = cu(b_tile_elems, &mut b);
    let c_2b_tile  = cu(2 * b_tile_elems, &mut b);
    let c_c_tile   = cu(c_tile_elems, &mut b);
    let c_layout_b = if rec.b_col_major { cu1 } else { cu0 };

    let mut op_mask: u32 = 0;
    if !ka.is_float && ka.signed == 1 { op_mask |= 0x01; }
    if !kb.is_float && kb.signed == 1 { op_mask |= 0x02; }
    if !kc.is_float && kc.signed == 1 { op_mask |= 0x04 | 0x08; }
    if tile.saturating_accumulation != 0 { op_mask |= 0x10; }

    let l_entry = b.alloc_id();
    SpvDynBuilder::push_inst(&mut b.funcs, 54, &[t_void, fn_main, 0, t_fn]);
    SpvDynBuilder::push_inst(&mut b.funcs, 248, &[l_entry]);

    // Subgroup-collision-proof global tile index: tidx = WorkgroupId.x * NumSubgroups + SubgroupId
    let p_wg   = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 65,  &[t_ptr_in_u32, p_wg, v_wgid, cu0]);
    let wgx    = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 61,  &[t_u32, wgx, p_wg]);
    let numsg  = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 61,  &[t_u32, numsg, v_numsg]);
    let sgid   = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 61,  &[t_u32, sgid, v_sgid]);
    let wg_mul = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 132, &[t_u32, wg_mul, wgx, numsg]);
    let tidx   = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 128, &[t_u32, tidx, wg_mul, sgid]);

    let off_c  = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 132, &[t_u32, off_c, tidx, c_c_tile]);
    let pc     = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 65,  &[t_psb_elem_c, pc, v_buf_c, cu0, off_c]);
    let mut acc= b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 4457,&[t_coop_c, acc, pc, cu0, c_stride_c]);

    let off_a0 = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 132, &[t_u32, off_a0, tidx, c_2a_tile]);
    let pa0    = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 65,  &[t_psb_elem_a, pa0, v_buf_a, cu0, off_a0]);
    let ma0    = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 4457,&[t_coop_a, ma0, pa0, cu0, c_stride_a]);

    let off_b0 = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 132, &[t_u32, off_b0, tidx, c_2b_tile]);
    let pb0    = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 65,  &[t_psb_elem_b, pb0, v_buf_b, cu0, off_b0]);
    let mb0    = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 4457,&[t_coop_b, mb0, pb0, c_layout_b, c_stride_b]);

    let first_half = if rec.mma_total <= 1 { 1 } else { rec.mma_total / 2 };
    for _ in 0..first_half {
        let nacc = b.alloc_id();
        if op_mask != 0 {
            SpvDynBuilder::push_inst(&mut b.funcs, 4459, &[t_coop_c, nacc, ma0, mb0, acc, op_mask]);
        } else {
            SpvDynBuilder::push_inst(&mut b.funcs, 4459, &[t_coop_c, nacc, ma0, mb0, acc]);
        }
        acc = nacc;
    }

    if rec.mma_total > 1 {
        // SSA Live-Range Split: ma0 & mb0 are dead here before loading ma1 & mb1 (peak live CoopMats = 3!)
        let off_a1 = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 128, &[t_u32, off_a1, off_a0, c_a_tile]);
        let pa1    = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 65,  &[t_psb_elem_a, pa1, v_buf_a, cu0, off_a1]);
        let ma1    = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 4457,&[t_coop_a, ma1, pa1, cu0, c_stride_a]);

        let off_b1 = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 128, &[t_u32, off_b1, off_b0, c_b_tile]);
        let pb1    = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 65,  &[t_psb_elem_b, pb1, v_buf_b, cu0, off_b1]);
        let mb1    = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 4457,&[t_coop_b, mb1, pb1, c_layout_b, c_stride_b]);

        for _ in 0..(rec.mma_total - first_half) {
            let nacc = b.alloc_id();
            if op_mask != 0 {
                SpvDynBuilder::push_inst(&mut b.funcs, 4459, &[t_coop_c, nacc, ma1, mb1, acc, op_mask]);
            } else {
                SpvDynBuilder::push_inst(&mut b.funcs, 4459, &[t_coop_c, nacc, ma1, mb1, acc]);
            }
            acc = nacc;
        }
    }

    let pd = b.alloc_id(); SpvDynBuilder::push_inst(&mut b.funcs, 65, &[t_psb_elem_c, pd, v_buf_d, cu0, off_c]);
    SpvDynBuilder::push_inst(&mut b.funcs, 4458, &[pd, acc, cu0, c_stride_c]);
    SpvDynBuilder::push_inst(&mut b.funcs, 253, &[]);
    SpvDynBuilder::push_inst(&mut b.funcs, 56, &[]);
    Some(b.finish())
}

#[derive(Clone)]
struct CoopTileDesc {
    shape: String,
    types: String,
    scope: String,
    saturating: bool,
    m: u32,
    n: u32,
    k: u32,
}

#[derive(Clone)]
struct KernelScore {
    id: String,
    elements: u32,
    matched: u32,
    dispatches: u32,
    elapsed_ms: f64,
    melem_per_sec: f64,
    gops_per_sec: f64,
    detail: String,
}

#[derive(Clone)]
struct VulkanSuiteReport {
    available: bool,
    device_name: String,
    api_version: String,
    vendor_hex: String,
    subgroup_size: u32,
    subgroup_min: u32,
    subgroup_max: u32,
    subgroup_ops_hex: String,
    uma_heap_mb: u64,
    ext_total: u32,
    ext_badges: Vec<String>,
    intdot_hw_accel: bool,
    idot_mask_hex: String,
    idot_tune_note: String,
    udot_tune_note: String,
    coop_tiles: Vec<CoopTileDesc>,
    coop_tune_note: String,
    kernels: Vec<KernelScore>,
    note: String,
}

fn coop_val_a(ka: ScalarSpec, t: usize, sub: usize, r: usize, c: usize) -> i32 {
    let h = ((t as u32).wrapping_mul(0x9E37_79B9)
        ^ ((sub as u32).wrapping_mul(0x85EB_CA6B))
        ^ ((r as u32).wrapping_mul(277))
        ^ ((c as u32).wrapping_mul(131))) as usize;
    if ka.is_float {
        if c < 8 && ((h + r + c) % 2 == 0) {
            if (h & 4) != 0 { -1 } else { 1 }
        } else {
            0
        }
    } else if ka.signed == 1 {
        (h % 5) as i32 - 2
    } else {
        (h % 3) as i32 + 1
    }
}

fn coop_val_b(kb: ScalarSpec, t: usize, sub: usize, r: usize, c: usize) -> i32 {
    let h = ((t as u32).wrapping_mul(0xC2B2_AE35)
        ^ ((sub as u32).wrapping_mul(0x27D4_EB2F))
        ^ ((r as u32).wrapping_mul(193))
        ^ ((c as u32).wrapping_mul(313))) as usize;
    if kb.is_float {
        match h % 4 {
            0 => -1,
            1 => 1,
            2 => 2,
            _ => -2,
        }
    } else if kb.signed == 1 {
        (h % 7) as i32 - 3
    } else {
        (h % 3) as i32 + 1
    }
}

fn coop_val_c(kc: ScalarSpec, t: usize, r: usize, c: usize) -> i32 {
    let h = ((t as u32).wrapping_mul(0x1656_67B1)
        ^ ((r as u32).wrapping_mul(97))
        ^ ((c as u32).wrapping_mul(53))) as usize;
    if kc.is_float || kc.signed == 1 {
        (h % 31) as i32 - 15
    } else {
        (h % 31) as i32 + 1
    }
}

fn coop_write_elem(dst: &mut [u8], off: usize, sp: ScalarSpec, val: i32) {
    if sp.is_float {
        if sp.bits == 16 {
            let h = i32_to_f16_exact(val).to_le_bytes();
            dst[off..off + 2].copy_from_slice(&h);
        } else {
            let f = (val as f32).to_le_bytes();
            dst[off..off + 4].copy_from_slice(&f);
        }
    } else if sp.bits == 8 {
        if sp.signed == 1 {
            dst[off] = (val as i8) as u8;
        } else {
            dst[off] = (val as u32 & 0xFF) as u8;
        }
    } else if sp.bits == 16 {
        let b2 = (val as i16).to_le_bytes();
        dst[off..off + 2].copy_from_slice(&b2);
    } else {
        let b4 = val.to_le_bytes();
        dst[off..off + 4].copy_from_slice(&b4);
    }
}

fn coop_fill_buffers(
    tile: &VkCooperativeMatrixPropertiesKHR,
    rec: &CoopRecipe,
    ka: ScalarSpec,
    kb: ScalarSpec,
    kc: ScalarSpec,
    num_tiles: usize,
    sl_a: &mut [u8],
    sl_b: &mut [u8],
    sl_c: &mut [u8],
    sl_d: &mut [u8],
) -> (usize, usize, usize, usize, usize, usize) {
    let m_sz = tile.m_size as usize;
    let n_sz = tile.n_size as usize;
    let k_sz = tile.k_size as usize;
    let rba = (((tile.k_size * ka.bytes + 15) / 16) * 16) as usize;
    let lead_b = if rec.b_col_major { tile.k_size } else { tile.n_size };
    let out_b  = if rec.b_col_major { n_sz } else { k_sz };
    let rbb = (((lead_b * kb.bytes + 15) / 16) * 16) as usize;
    let rbc = (((tile.n_size * kc.bytes + 15) / 16) * 16) as usize;

    let atb = m_sz * rba;
    let btb = out_b * rbb;
    let ctb = m_sz * rbc;

    let need_a = 2 * num_tiles * atb;
    let need_b = 2 * num_tiles * btb;
    let need_c = num_tiles * ctb;
    sl_a[..need_a].fill(0);
    sl_b[..need_b].fill(0);
    sl_c[..need_c].fill(0);
    sl_d[..need_c].fill(0xCD);

    for t in 0..num_tiles {
        for sub in 0..2usize {
            let ba = (2 * t + sub) * atb;
            for r in 0..m_sz {
                for c in 0..k_sz {
                    coop_write_elem(sl_a, ba + r * rba + c * (ka.bytes as usize), ka, coop_val_a(ka, t, sub, r, c));
                }
            }
            let bb = (2 * t + sub) * btb;
            for r in 0..k_sz {
                for c in 0..n_sz {
                    let off = if rec.b_col_major {
                        bb + c * rbb + r * (kb.bytes as usize)
                    } else {
                        bb + r * rbb + c * (kb.bytes as usize)
                    };
                    coop_write_elem(sl_b, off, kb, coop_val_b(kb, t, sub, r, c));
                }
            }
        }
        let bc = t * ctb;
        for r in 0..m_sz {
            for c in 0..n_sz {
                coop_write_elem(sl_c, bc + r * rbc + c * (kc.bytes as usize), kc, coop_val_c(kc, t, r, c));
            }
        }
    }
    (rba, rbb, rbc, atb, btb, ctb)
}

fn coop_verify_output(
    tile: &VkCooperativeMatrixPropertiesKHR,
    rec: &CoopRecipe,
    ka: ScalarSpec,
    kb: ScalarSpec,
    kc: ScalarSpec,
    num_tiles: usize,
    rbc: usize,
    ctb: usize,
    sl_d: &[u8],
) -> (u32, i32, i32) {
    let m_sz = tile.m_size as usize;
    let n_sz = tile.n_size as usize;
    let k_sz = tile.k_size as usize;
    let w0: i32 = if rec.mma_total <= 1 { 1 } else { (rec.mma_total / 2) as i32 };
    let w1: i32 = if rec.mma_total <= 1 { 0 } else { (rec.mma_total - (rec.mma_total / 2)) as i32 };

    let mut matched: u32 = 0;
    let mut first_got: i32 = 0;
    let mut first_exp: i32 = 0;
    for t in 0..num_tiles {
        let bd = t * ctb;
        for r in 0..m_sz {
            for c in 0..n_sz {
                let mut dot0: i32 = 0;
                let mut dot1: i32 = 0;
                for kk in 0..k_sz {
                    dot0 += coop_val_a(ka, t, 0, r, kk) * coop_val_b(kb, t, 0, kk, c);
                    if w1 > 0 {
                        dot1 += coop_val_a(ka, t, 1, r, kk) * coop_val_b(kb, t, 1, kk, c);
                    }
                }
                let exp_i32 = coop_val_c(kc, t, r, c) + w0 * dot0 + w1 * dot1;
                let off = bd + r * rbc + c * (kc.bytes as usize);
                let (ok, got_dbg) = if kc.is_float && kc.bits == 16 {
                    let got = u16::from_le_bytes([sl_d[off], sl_d[off + 1]]);
                    (got == i32_to_f16_exact(exp_i32), got as i32)
                } else if kc.is_float {
                    let got_u = u32::from_le_bytes([sl_d[off], sl_d[off + 1], sl_d[off + 2], sl_d[off + 3]]);
                    let got_f = f32::from_bits(got_u);
                    (got_u == (exp_i32 as f32).to_bits(), got_f as i32)
                } else {
                    let got = i32::from_le_bytes([sl_d[off], sl_d[off + 1], sl_d[off + 2], sl_d[off + 3]]);
                    (got == exp_i32, got)
                };
                if t == 0 && r == 0 && c == 0 {
                    first_got = got_dbg;
                    first_exp = exp_i32;
                }
                if ok { matched += 1; }
            }
        }
    }
    (matched, first_got, first_exp)
}

fn run_vulkan_suite(filter_kernel: &str) -> VulkanSuiteReport {
    let empty = |note: String| VulkanSuiteReport {
        available: false, device_name: "None".to_string(), api_version: "0.0.0".to_string(),
        vendor_hex: "0x0000".to_string(), subgroup_size: 0, subgroup_min: 0, subgroup_max: 0,
        subgroup_ops_hex: "0x0".to_string(), uma_heap_mb: 0, ext_total: 0, ext_badges: Vec::new(),
        intdot_hw_accel: false, idot_mask_hex: "0x0".to_string(), idot_tune_note: String::new(), udot_tune_note: String::new(), coop_tiles: Vec::new(), coop_tune_note: String::new(), kernels: Vec::new(), note,
    };

    let lib = match DynVulkanLib::open() {
        Ok(l) => l,
        Err(e) => return empty(e),
    };

    unsafe {
        let raw_gipa = lib.sym(b"vkGetInstanceProcAddr\0");
        if raw_gipa.is_null() { return empty("vkGetInstanceProcAddr null".to_string()); }
        type PfnGetInstanceProcAddr = unsafe extern "system" fn(*mut c_void, *const u8) -> *mut c_void;
        let get_ipa: PfnGetInstanceProcAddr = core::mem::transmute(raw_gipa);

        let mut p_create_inst = get_ipa(null_mut(), b"vkCreateInstance\0".as_ptr());
        if p_create_inst.is_null() { p_create_inst = lib.sym(b"vkCreateInstance\0"); }
        if p_create_inst.is_null() { return empty("vkCreateInstance null".to_string()); }
        type PfnCreateInstance = unsafe extern "system" fn(*const VkInstanceCreateInfo, *const c_void, *mut *mut c_void) -> i32;
        let vk_create_instance: PfnCreateInstance = core::mem::transmute(p_create_inst);

        let mut loader_api: u32 = (1u32 << 22) | (3u32 << 12);
        let p_enum_iver = get_ipa(null_mut(), b"vkEnumerateInstanceVersion\0".as_ptr());
        if !p_enum_iver.is_null() {
            type PfnEnumInstVer = unsafe extern "system" fn(*mut u32) -> i32;
            let vk_enum_iver: PfnEnumInstVer = core::mem::transmute(p_enum_iver);
            let mut qv: u32 = 0;
            if vk_enum_iver(&mut qv) == 0 && qv >= (1u32 << 22) {
                loader_api = qv.min((1u32 << 22) | (4u32 << 12));
            }
        }

        let mut instance: *mut c_void = null_mut();
        for api_try in [loader_api, (1u32 << 22) | (3u32 << 12), (1u32 << 22) | (1u32 << 12), 1u32 << 22] {
            let app = VkApplicationInfo {
                s_type: 0, p_next: null(),
                p_application_name: b"omega_p10_worker_v040\0".as_ptr(), application_version: 4,
                p_engine_name: b"ACT_OMEGA_TENSOR\0".as_ptr(), engine_version: 4, api_version: api_try,
            };
            let ici = VkInstanceCreateInfo {
                s_type: 1, p_next: null(), flags: 0, p_application_info: &app,
                enabled_layer_count: 0, pp_enabled_layer_names: null(),
                enabled_extension_count: 0, pp_enabled_extension_names: null(),
            };
            if vk_create_instance(&ici, null(), &mut instance) == 0 && !instance.is_null() {
                break;
            }
        }
        if instance.is_null() { return empty("vkCreateInstance failed".to_string()); }

        type PfnDestroyInstance = unsafe extern "system" fn(*mut c_void, *const c_void);
        type PfnEnumPhys = unsafe extern "system" fn(*mut c_void, *mut u32, *mut *mut c_void) -> i32;
        type PfnGetProps = unsafe extern "system" fn(*mut c_void, *mut VkPhysicalDevicePropertiesHead);
        type PfnGetProps2 = unsafe extern "system" fn(*mut c_void, *mut VkPhysicalDeviceProperties2);
        type PfnGetFeats2 = unsafe extern "system" fn(*mut c_void, *mut VkPhysicalDeviceFeatures2);
        type PfnEnumDevExt = unsafe extern "system" fn(*mut c_void, *const u8, *mut u32, *mut VkExtensionProperties) -> i32;
        type PfnGetQProps = unsafe extern "system" fn(*mut c_void, *mut u32, *mut VkQueueFamilyProperties);
        type PfnGetMemProps = unsafe extern "system" fn(*mut c_void, *mut VkPhysicalDeviceMemoryProperties);
        type PfnCreateDev = unsafe extern "system" fn(*mut c_void, *const VkDeviceCreateInfo, *const c_void, *mut *mut c_void) -> i32;
        type PfnGetDeviceProcAddr = unsafe extern "system" fn(*mut c_void, *const u8) -> *mut c_void;
        type PfnGetCoopPropsKHR = unsafe extern "system" fn(*mut c_void, *mut u32, *mut VkCooperativeMatrixPropertiesKHR) -> i32;

        let vk_destroy_instance: PfnDestroyInstance = core::mem::transmute(get_ipa(instance, b"vkDestroyInstance\0".as_ptr()));
        let vk_enum_phys: PfnEnumPhys = core::mem::transmute(get_ipa(instance, b"vkEnumeratePhysicalDevices\0".as_ptr()));
        let vk_get_props: PfnGetProps = core::mem::transmute(get_ipa(instance, b"vkGetPhysicalDeviceProperties\0".as_ptr()));
        let mut p_get_props2 = get_ipa(instance, b"vkGetPhysicalDeviceProperties2\0".as_ptr());
        if p_get_props2.is_null() { p_get_props2 = get_ipa(instance, b"vkGetPhysicalDeviceProperties2KHR\0".as_ptr()); }
        let mut p_get_feats2 = get_ipa(instance, b"vkGetPhysicalDeviceFeatures2\0".as_ptr());
        if p_get_feats2.is_null() { p_get_feats2 = get_ipa(instance, b"vkGetPhysicalDeviceFeatures2KHR\0".as_ptr()); }
        let p_get_coop_khr = get_ipa(instance, b"vkGetPhysicalDeviceCooperativeMatrixPropertiesKHR\0".as_ptr());
        let vk_enum_dev_ext: PfnEnumDevExt = core::mem::transmute(get_ipa(instance, b"vkEnumerateDeviceExtensionProperties\0".as_ptr()));
        let vk_get_qprops: PfnGetQProps = core::mem::transmute(get_ipa(instance, b"vkGetPhysicalDeviceQueueFamilyProperties\0".as_ptr()));
        let vk_get_mem_props: PfnGetMemProps = core::mem::transmute(get_ipa(instance, b"vkGetPhysicalDeviceMemoryProperties\0".as_ptr()));
        let vk_create_dev: PfnCreateDev = core::mem::transmute(get_ipa(instance, b"vkCreateDevice\0".as_ptr()));
        let get_dpa: PfnGetDeviceProcAddr = core::mem::transmute(get_ipa(instance, b"vkGetDeviceProcAddr\0".as_ptr()));

        let mut pd_count: u32 = 0;
        let _ = vk_enum_phys(instance, &mut pd_count, null_mut());
        if pd_count == 0 {
            vk_destroy_instance(instance, null());
            return empty("0 Vulkan physical devices".to_string());
        }
        let mut pds: [*mut c_void; 8] = [null_mut(); 8];
        if pd_count > 8 { pd_count = 8; }
        let _ = vk_enum_phys(instance, &mut pd_count, pds.as_mut_ptr());

        let mut phys = pds[0];
        let mut chosen_props: VkPhysicalDevicePropertiesHead = core::mem::zeroed();
        for idx in 0..(pd_count as usize) {
            let mut pr: VkPhysicalDevicePropertiesHead = core::mem::zeroed();
            vk_get_props(pds[idx], &mut pr);
            let dev_ty = pr.device_type;
            if idx == 0 || dev_ty == 2 || dev_ty == 1 {
                phys = pds[idx];
                chosen_props = pr;
                if dev_ty == 2 { break; }
            }
        }

        let mut ext_total: u32 = 0;
        let _ = vk_enum_dev_ext(phys, null(), &mut ext_total, null_mut());
        let mut raw_ext_list: Vec<VkExtensionProperties> = Vec::new();
        if ext_total > 0 {
            let cap = (ext_total as usize).min(768);
            raw_ext_list = vec![VkExtensionProperties { extension_name: [0; 256], spec_version: 0 }; cap];
            let mut fetch_n = cap as u32;
            let _ = vk_enum_dev_ext(phys, null(), &mut fetch_n, raw_ext_list.as_mut_ptr());
            raw_ext_list.truncate(fetch_n as usize);
        }
        let has_ext = |target: &str| -> bool {
            raw_ext_list.iter().any(|e| {
                let end = e.extension_name.iter().position(|&b| b == 0).unwrap_or(256);
                &e.extension_name[..end] == target.as_bytes()
            })
        };

        let mut ext_badges = Vec::new();
        for (full_ext, badge) in [
            ("VK_KHR_shader_integer_dot_product", "int_dot"),
            ("VK_KHR_cooperative_matrix", "coop_mat"),
            ("VK_KHR_shader_bfloat16", "bf16"),
            ("VK_KHR_shader_float16_int8", "fp16_int8"),
            ("VK_KHR_vulkan_memory_model", "vk_mm"),
            ("VK_EXT_subgroup_size_control", "sg_ctrl"),
            ("VK_KHR_shader_subgroup_rotate", "sg_rotate"),
            ("VK_KHR_spirv_1_4", "spirv_1_4"),
            ("VK_EXT_buffer_device_address", "bda"),
            ("VK_EXT_descriptor_buffer", "desc_buf"),
            ("VK_ANDROID_external_memory_android_hardware_buffer", "android_ahb"),
        ] {
            if has_ext(full_ext) { ext_badges.push(badge.to_string()); }
        }

        // Probe SubgroupSize + SubgroupSizeControl [min..max] + Standalone 27-Flag IntDot HW Properties
        let pd_api = chosen_props.api_version;
        let mut sg_ctrl_props = VkPhysicalDeviceSubgroupSizeControlProperties {
            s_type: 1_000_225_000, p_next: null_mut(),
            min_subgroup_size: 0, max_subgroup_size: 0,
            max_compute_workgroup_subgroups: 0, required_subgroup_size_stages: 0,
        };
        let mut sg_props = VkPhysicalDeviceSubgroupProperties {
            s_type: 1_000_094_000,
            p_next: if has_ext("VK_EXT_subgroup_size_control") || pd_api >= ((1u32 << 22) | (3u32 << 12)) {
                (&mut sg_ctrl_props as *mut VkPhysicalDeviceSubgroupSizeControlProperties) as *mut c_void
            } else {
                null_mut()
            },
            subgroup_size: 0, supported_stages: 0, supported_operations: 0, quad_operations_in_all_stages: 0,
        };
        let mut idot_props = VkPhysicalDeviceShaderIntegerDotProductProperties {
            s_type: 1_000_280_001, p_next: null_mut(), flags: [0; 40],
        };
        if !p_get_props2.is_null() {
            let vk_get_props2: PfnGetProps2 = core::mem::transmute(p_get_props2);
            let mut props2_sg = VkPhysicalDeviceProperties2 {
                s_type: 1_000_059_001,
                p_next: (&mut sg_props as *mut VkPhysicalDeviceSubgroupProperties) as *mut c_void,
                properties: core::mem::zeroed(),
            };
            vk_get_props2(phys, &mut props2_sg);

            if has_ext("VK_KHR_shader_integer_dot_product") || pd_api >= ((1u32 << 22) | (3u32 << 12)) {
                let mut props2_idot = VkPhysicalDeviceProperties2 {
                    s_type: 1_000_059_001,
                    p_next: (&mut idot_props as *mut VkPhysicalDeviceShaderIntegerDotProductProperties) as *mut c_void,
                    properties: core::mem::zeroed(),
                };
                vk_get_props2(phys, &mut props2_idot);
            }
        }
        let (idot_mask27, idot_mask_8b, idot_props_summary) = decode_idot_props27(&idot_props.flags);
        let mut intdot_hw_accel = idot_mask_8b != 0;
        let idot_mask_hex = format!("0x{:07X}", idot_mask27);
        let sg_min = if sg_ctrl_props.min_subgroup_size > 0 { sg_ctrl_props.min_subgroup_size } else { sg_props.subgroup_size };
        let sg_max = if sg_ctrl_props.max_subgroup_size > 0 { sg_ctrl_props.max_subgroup_size } else { sg_props.subgroup_size };

        let mut raw_coop_tiles: Vec<VkCooperativeMatrixPropertiesKHR> = Vec::new();
        let mut coop_tiles_desc: Vec<CoopTileDesc> = Vec::new();
        if has_ext("VK_KHR_cooperative_matrix") && !p_get_coop_khr.is_null() {
            let vk_get_coop: PfnGetCoopPropsKHR = core::mem::transmute(p_get_coop_khr);
            let mut t_cnt: u32 = 0;
            if vk_get_coop(phys, &mut t_cnt, null_mut()) == 0 && t_cnt > 0 {
                let cap = (t_cnt as usize).min(128);
                raw_coop_tiles = vec![VkCooperativeMatrixPropertiesKHR {
                    s_type: 1_000_506_001, p_next: null_mut(),
                    m_size: 0, n_size: 0, k_size: 0,
                    a_type: 0, b_type: 0, c_type: 0, result_type: 0,
                    saturating_accumulation: 0, scope: 0,
                }; cap];
                let mut fetch_t = cap as u32;
                if vk_get_coop(phys, &mut fetch_t, raw_coop_tiles.as_mut_ptr()) == 0 {
                    raw_coop_tiles.truncate(fetch_t as usize);
                    for ct in &raw_coop_tiles {
                        coop_tiles_desc.push(CoopTileDesc {
                            shape: format!("{}x{}x{}", ct.m_size, ct.n_size, ct.k_size),
                            types: format!(
                                "{}*{}+{}->{}",
                                vk_comp_type_short(ct.a_type),
                                vk_comp_type_short(ct.b_type),
                                vk_comp_type_short(ct.c_type),
                                vk_comp_type_short(ct.result_type)
                            ),
                            scope: vk_scope_short(ct.scope).to_string(),
                            saturating: ct.saturating_accumulation != 0,
                            m: ct.m_size,
                            n: ct.n_size,
                            k: ct.k_size,
                        });
                    }
                }
            }
        }

        let name_end = chosen_props.device_name.iter().position(|&b| b == 0).unwrap_or(chosen_props.device_name.len());
        let dev_name = String::from_utf8_lossy(&chosen_props.device_name[..name_end]).trim().to_string();
        let api_str = format!(
            "{}.{}.{}",
            (chosen_props.api_version >> 22) & 0x3FF,
            (chosen_props.api_version >> 12) & 0x3FF,
            chosen_props.api_version & 0xFFF
        );
        let vendor_hex = format!("0x{:04X}", chosen_props.vendor_id);

        let mut mem_props: VkPhysicalDeviceMemoryProperties = core::mem::zeroed();
        vk_get_mem_props(phys, &mut mem_props);
        let mut uma_heap_bytes: u64 = 0;
        for h in 0..(mem_props.memory_heap_count as usize) {
            if mem_props.memory_heaps[h].size > uma_heap_bytes {
                uma_heap_bytes = mem_props.memory_heaps[h].size;
            }
        }
        let uma_heap_mb = uma_heap_bytes / (1024 * 1024);

        if filter_kernel == "caps_only" || filter_kernel == "coop_props_only" {
            vk_destroy_instance(instance, null());
            return VulkanSuiteReport {
                available: true, device_name: dev_name, api_version: api_str, vendor_hex,
                subgroup_size: sg_props.subgroup_size, subgroup_min: sg_min, subgroup_max: sg_max,
                subgroup_ops_hex: format!("0x{:X}", sg_props.supported_operations),
                uma_heap_mb, ext_total, ext_badges, intdot_hw_accel,
                idot_mask_hex, idot_tune_note: idot_props_summary, udot_tune_note: String::new(),
                coop_tiles: coop_tiles_desc, coop_tune_note: String::new(), kernels: Vec::new(), note: "CAPS_OK".to_string(),
            };
        }

        let mut q_count: u32 = 0;
        vk_get_qprops(phys, &mut q_count, null_mut());
        let mut q_props = [VkQueueFamilyProperties {
            queue_flags: 0, queue_count: 0, timestamp_valid_bits: 0, min_image_transfer_granularity: [0; 3],
        }; 16];
        if q_count > 16 { q_count = 16; }
        vk_get_qprops(phys, &mut q_count, q_props.as_mut_ptr());
        let mut comp_q: u32 = 0;
        for i in 0..(q_count as usize) {
            if (q_props[i].queue_flags & 0x02) != 0 { comp_q = i as u32; break; }
        }

        let mut f_16bit = VkPhysicalDevice16BitStorageFeatures {
            s_type: 1_000_083_000, p_next: null_mut(),
            storage_buffer_16bit_access: 0, uniform_and_storage_buffer_16bit_access: 0,
            storage_push_constant_16: 0, storage_input_output_16: 0,
        };
        let mut f_8bit = VkPhysicalDevice8BitStorageFeatures {
            s_type: 1_000_177_000, p_next: null_mut(),
            storage_buffer_8bit_access: 0, uniform_and_storage_buffer_8bit_access: 0, storage_push_constant_8: 0,
        };
        let mut f_f16i8 = VkPhysicalDeviceShaderFloat16Int8Features {
            s_type: 1_000_082_000, p_next: null_mut(), shader_float16: 0, shader_int8: 0,
        };
        let mut f_mm = VkPhysicalDeviceVulkanMemoryModelFeatures {
            s_type: 1_000_211_000, p_next: null_mut(),
            vulkan_memory_model: 0, vulkan_memory_model_device_scope: 0, vulkan_memory_model_availability_visibility_chains: 0,
        };
        let mut f_sgctrl = VkPhysicalDeviceSubgroupSizeControlFeatures {
            s_type: 1_000_225_002, p_next: null_mut(),
            subgroup_size_control: 0, compute_full_subgroups: 0,
        };
        let mut f_idot = VkPhysicalDeviceShaderIntegerDotProductFeatures {
            s_type: 1_000_280_000, p_next: null_mut(), shader_integer_dot_product: 0,
        };
        let mut f_coop = VkPhysicalDeviceCooperativeMatrixFeaturesKHR {
            s_type: 1_000_506_000, p_next: null_mut(), cooperative_matrix: 0, cooperative_matrix_robust_buffer_access: 0,
        };
        let mut feat2 = VkPhysicalDeviceFeatures2 {
            s_type: 1_000_059_000, p_next: null_mut(), features: VkPhysicalDeviceFeatures { flags: [0; 55] },
        };

        let mut chain_head: *mut c_void = null_mut();
        if has_ext("VK_KHR_16bit_storage") || pd_api >= ((1u32 << 22) | (1u32 << 12)) {
            f_16bit.p_next = chain_head;
            chain_head = (&mut f_16bit as *mut VkPhysicalDevice16BitStorageFeatures) as *mut c_void;
        }
        if has_ext("VK_KHR_8bit_storage") || pd_api >= ((1u32 << 22) | (2u32 << 12)) {
            f_8bit.p_next = chain_head;
            chain_head = (&mut f_8bit as *mut VkPhysicalDevice8BitStorageFeatures) as *mut c_void;
        }
        if has_ext("VK_KHR_shader_float16_int8") || pd_api >= ((1u32 << 22) | (2u32 << 12)) {
            f_f16i8.p_next = chain_head;
            chain_head = (&mut f_f16i8 as *mut VkPhysicalDeviceShaderFloat16Int8Features) as *mut c_void;
        }
        if has_ext("VK_KHR_vulkan_memory_model") || pd_api >= ((1u32 << 22) | (2u32 << 12)) {
            f_mm.p_next = chain_head;
            chain_head = (&mut f_mm as *mut VkPhysicalDeviceVulkanMemoryModelFeatures) as *mut c_void;
        }
        if has_ext("VK_EXT_subgroup_size_control") || pd_api >= ((1u32 << 22) | (3u32 << 12)) {
            f_sgctrl.p_next = chain_head;
            chain_head = (&mut f_sgctrl as *mut VkPhysicalDeviceSubgroupSizeControlFeatures) as *mut c_void;
        }
        if has_ext("VK_KHR_shader_integer_dot_product") || pd_api >= ((1u32 << 22) | (3u32 << 12)) {
            f_idot.p_next = chain_head;
            chain_head = (&mut f_idot as *mut VkPhysicalDeviceShaderIntegerDotProductFeatures) as *mut c_void;
        }
        if has_ext("VK_KHR_cooperative_matrix") {
            f_coop.p_next = chain_head;
            chain_head = (&mut f_coop as *mut VkPhysicalDeviceCooperativeMatrixFeaturesKHR) as *mut c_void;
        }
        feat2.p_next = chain_head;

        let mut use_feat2 = false;
        if !p_get_feats2.is_null() {
            let vk_get_feats2: PfnGetFeats2 = core::mem::transmute(p_get_feats2);
            vk_get_feats2(phys, &mut feat2);
            feat2.features.flags[0] = 0;
            f_coop.cooperative_matrix_robust_buffer_access = 0;
            use_feat2 = true;
        }

        let mut enabled_ext_ptrs: Vec<*const u8> = Vec::new();
        for &(ext_str, ext_cstr) in &[
            ("VK_KHR_16bit_storage", &b"VK_KHR_16bit_storage\0"[..]),
            ("VK_KHR_8bit_storage", &b"VK_KHR_8bit_storage\0"[..]),
            ("VK_KHR_shader_float16_int8", &b"VK_KHR_shader_float16_int8\0"[..]),
            ("VK_KHR_vulkan_memory_model", &b"VK_KHR_vulkan_memory_model\0"[..]),
            ("VK_EXT_subgroup_size_control", &b"VK_EXT_subgroup_size_control\0"[..]),
            ("VK_KHR_spirv_1_4", &b"VK_KHR_spirv_1_4\0"[..]),
            ("VK_KHR_shader_integer_dot_product", &b"VK_KHR_shader_integer_dot_product\0"[..]),
            ("VK_KHR_cooperative_matrix", &b"VK_KHR_cooperative_matrix\0"[..]),
        ] {
            if has_ext(ext_str) {
                enabled_ext_ptrs.push(ext_cstr.as_ptr());
            }
        }

        let prio: f32 = 1.0;
        let qci = VkDeviceQueueCreateInfo { s_type: 2, p_next: null(), flags: 0, queue_family_index: comp_q, queue_count: 1, p_queue_priorities: &prio };
        let mut dev: *mut c_void = null_mut();
        if use_feat2 {
            let dci_ext = VkDeviceCreateInfo {
                s_type: 3,
                p_next: (&feat2 as *const VkPhysicalDeviceFeatures2) as *const c_void,
                flags: 0,
                queue_create_info_count: 1, p_queue_create_infos: &qci,
                enabled_layer_count: 0, pp_enabled_layer_names: null(),
                enabled_extension_count: enabled_ext_ptrs.len() as u32,
                pp_enabled_extension_names: if enabled_ext_ptrs.is_empty() { null() } else { enabled_ext_ptrs.as_ptr() },
                p_enabled_features: null(),
            };
            let _ = vk_create_dev(phys, &dci_ext, null(), &mut dev);
        }
        if dev.is_null() {
            f_idot.shader_integer_dot_product = 0;
            f_coop.cooperative_matrix = 0;
            let dci_base = VkDeviceCreateInfo {
                s_type: 3, p_next: null(), flags: 0, queue_create_info_count: 1, p_queue_create_infos: &qci,
                enabled_layer_count: 0, pp_enabled_layer_names: null(),
                enabled_extension_count: 0, pp_enabled_extension_names: null(), p_enabled_features: null(),
            };
            if vk_create_dev(phys, &dci_base, null(), &mut dev) != 0 || dev.is_null() {
                vk_destroy_instance(instance, null());
                return empty("vkCreateDevice failed".to_string());
            }
        }

        type PfnDestroyDevice = unsafe extern "system" fn(*mut c_void, *const c_void);
        type PfnGetDeviceQueue = unsafe extern "system" fn(*mut c_void, u32, u32, *mut *mut c_void);
        type PfnCreateBuffer = unsafe extern "system" fn(*mut c_void, *const VkBufferCreateInfo, *const c_void, *mut u64) -> i32;
        type PfnDestroyBuffer = unsafe extern "system" fn(*mut c_void, u64, *const c_void);
        type PfnGetBufMemReq = unsafe extern "system" fn(*mut c_void, u64, *mut VkMemoryRequirements);
        type PfnAllocMem = unsafe extern "system" fn(*mut c_void, *const VkMemoryAllocateInfo, *const c_void, *mut u64) -> i32;
        type PfnFreeMem = unsafe extern "system" fn(*mut c_void, u64, *const c_void);
        type PfnBindBufMem = unsafe extern "system" fn(*mut c_void, u64, u64, u64) -> i32;
        type PfnMapMem = unsafe extern "system" fn(*mut c_void, u64, u64, u64, u32, *mut *mut c_void) -> i32;
        type PfnUnmapMem = unsafe extern "system" fn(*mut c_void, u64);
        type PfnCreateShader = unsafe extern "system" fn(*mut c_void, *const VkShaderModuleCreateInfo, *const c_void, *mut u64) -> i32;
        type PfnDestroyShader = unsafe extern "system" fn(*mut c_void, u64, *const c_void);
        type PfnCreateDsl = unsafe extern "system" fn(*mut c_void, *const VkDescriptorSetLayoutCreateInfo, *const c_void, *mut u64) -> i32;
        type PfnDestroyDsl = unsafe extern "system" fn(*mut c_void, u64, *const c_void);
        type PfnCreatePipeLayout = unsafe extern "system" fn(*mut c_void, *const VkPipelineLayoutCreateInfo, *const c_void, *mut u64) -> i32;
        type PfnDestroyPipeLayout = unsafe extern "system" fn(*mut c_void, u64, *const c_void);
        type PfnCreateCompPipes = unsafe extern "system" fn(*mut c_void, u64, u32, *const VkComputePipelineCreateInfo, *const c_void, *mut u64) -> i32;
        type PfnDestroyPipe = unsafe extern "system" fn(*mut c_void, u64, *const c_void);
        type PfnCreateDescPool = unsafe extern "system" fn(*mut c_void, *const VkDescriptorPoolCreateInfo, *const c_void, *mut u64) -> i32;
        type PfnDestroyDescPool = unsafe extern "system" fn(*mut c_void, u64, *const c_void);
        type PfnAllocDescSets = unsafe extern "system" fn(*mut c_void, *const VkDescriptorSetAllocateInfo, *mut u64) -> i32;
        type PfnUpdateDescSets = unsafe extern "system" fn(*mut c_void, u32, *const VkWriteDescriptorSet, u32, *const c_void);
        type PfnCreateCmdPool = unsafe extern "system" fn(*mut c_void, *const VkCommandPoolCreateInfo, *const c_void, *mut u64) -> i32;
        type PfnDestroyCmdPool = unsafe extern "system" fn(*mut c_void, u64, *const c_void);
        type PfnAllocCmdBufs = unsafe extern "system" fn(*mut c_void, *const VkCommandBufferAllocateInfo, *mut *mut c_void) -> i32;
        type PfnBeginCmdBuf = unsafe extern "system" fn(*mut c_void, *const VkCommandBufferBeginInfo) -> i32;
        type PfnCmdBindPipe = unsafe extern "system" fn(*mut c_void, u32, u64);
        type PfnCmdBindDescSets = unsafe extern "system" fn(*mut c_void, u32, u64, u32, u32, *const u64, u32, *const u32);
        type PfnCmdPushConsts = unsafe extern "system" fn(*mut c_void, u64, u32, u32, u32, *const c_void);
        type PfnCmdDispatch = unsafe extern "system" fn(*mut c_void, u32, u32, u32);
        type PfnEndCmdBuf = unsafe extern "system" fn(*mut c_void) -> i32;
        type PfnQueueSubmit = unsafe extern "system" fn(*mut c_void, u32, *const VkSubmitInfo, u64) -> i32;
        type PfnQueueWaitIdle = unsafe extern "system" fn(*mut c_void) -> i32;

        let vk_destroy_dev: PfnDestroyDevice = core::mem::transmute(get_dpa(dev, b"vkDestroyDevice\0".as_ptr()));
        let vk_get_queue: PfnGetDeviceQueue = core::mem::transmute(get_dpa(dev, b"vkGetDeviceQueue\0".as_ptr()));
        let vk_create_buf: PfnCreateBuffer = core::mem::transmute(get_dpa(dev, b"vkCreateBuffer\0".as_ptr()));
        let vk_destroy_buf: PfnDestroyBuffer = core::mem::transmute(get_dpa(dev, b"vkDestroyBuffer\0".as_ptr()));
        let vk_get_buf_req: PfnGetBufMemReq = core::mem::transmute(get_dpa(dev, b"vkGetBufferMemoryRequirements\0".as_ptr()));
        let vk_alloc_mem: PfnAllocMem = core::mem::transmute(get_dpa(dev, b"vkAllocateMemory\0".as_ptr()));
        let vk_free_mem: PfnFreeMem = core::mem::transmute(get_dpa(dev, b"vkFreeMemory\0".as_ptr()));
        let vk_bind_buf_mem: PfnBindBufMem = core::mem::transmute(get_dpa(dev, b"vkBindBufferMemory\0".as_ptr()));
        let vk_map_mem: PfnMapMem = core::mem::transmute(get_dpa(dev, b"vkMapMemory\0".as_ptr()));
        let vk_unmap_mem: PfnUnmapMem = core::mem::transmute(get_dpa(dev, b"vkUnmapMemory\0".as_ptr()));
        let vk_create_shader: PfnCreateShader = core::mem::transmute(get_dpa(dev, b"vkCreateShaderModule\0".as_ptr()));
        let vk_destroy_shader: PfnDestroyShader = core::mem::transmute(get_dpa(dev, b"vkDestroyShaderModule\0".as_ptr()));
        let vk_create_dsl: PfnCreateDsl = core::mem::transmute(get_dpa(dev, b"vkCreateDescriptorSetLayout\0".as_ptr()));
        let vk_destroy_dsl: PfnDestroyDsl = core::mem::transmute(get_dpa(dev, b"vkDestroyDescriptorSetLayout\0".as_ptr()));
        let vk_create_pipe_layout: PfnCreatePipeLayout = core::mem::transmute(get_dpa(dev, b"vkCreatePipelineLayout\0".as_ptr()));
        let vk_destroy_pipe_layout: PfnDestroyPipeLayout = core::mem::transmute(get_dpa(dev, b"vkDestroyPipelineLayout\0".as_ptr()));
        let vk_create_comp_pipes: PfnCreateCompPipes = core::mem::transmute(get_dpa(dev, b"vkCreateComputePipelines\0".as_ptr()));
        let vk_destroy_pipe: PfnDestroyPipe = core::mem::transmute(get_dpa(dev, b"vkDestroyPipeline\0".as_ptr()));
        let vk_create_dpool: PfnCreateDescPool = core::mem::transmute(get_dpa(dev, b"vkCreateDescriptorPool\0".as_ptr()));
        let vk_destroy_dpool: PfnDestroyDescPool = core::mem::transmute(get_dpa(dev, b"vkDestroyDescriptorPool\0".as_ptr()));
        let vk_alloc_dsets: PfnAllocDescSets = core::mem::transmute(get_dpa(dev, b"vkAllocateDescriptorSets\0".as_ptr()));
        let vk_update_dsets: PfnUpdateDescSets = core::mem::transmute(get_dpa(dev, b"vkUpdateDescriptorSets\0".as_ptr()));
        let vk_create_cpool: PfnCreateCmdPool = core::mem::transmute(get_dpa(dev, b"vkCreateCommandPool\0".as_ptr()));
        let vk_destroy_cpool: PfnDestroyCmdPool = core::mem::transmute(get_dpa(dev, b"vkDestroyCommandPool\0".as_ptr()));
        let vk_alloc_cbufs: PfnAllocCmdBufs = core::mem::transmute(get_dpa(dev, b"vkAllocateCommandBuffers\0".as_ptr()));
        let vk_begin_cbuf: PfnBeginCmdBuf = core::mem::transmute(get_dpa(dev, b"vkBeginCommandBuffer\0".as_ptr()));
        let vk_cmd_bind_pipe: PfnCmdBindPipe = core::mem::transmute(get_dpa(dev, b"vkCmdBindPipeline\0".as_ptr()));
        let vk_cmd_bind_dsets: PfnCmdBindDescSets = core::mem::transmute(get_dpa(dev, b"vkCmdBindDescriptorSets\0".as_ptr()));
        let vk_cmd_push_consts: PfnCmdPushConsts = core::mem::transmute(get_dpa(dev, b"vkCmdPushConstants\0".as_ptr()));
        let vk_cmd_dispatch: PfnCmdDispatch = core::mem::transmute(get_dpa(dev, b"vkCmdDispatch\0".as_ptr()));
        let vk_end_cbuf: PfnEndCmdBuf = core::mem::transmute(get_dpa(dev, b"vkEndCommandBuffer\0".as_ptr()));
        let vk_queue_submit: PfnQueueSubmit = core::mem::transmute(get_dpa(dev, b"vkQueueSubmit\0".as_ptr()));
        let vk_queue_wait_idle: PfnQueueWaitIdle = core::mem::transmute(get_dpa(dev, b"vkQueueWaitIdle\0".as_ptr()));

        let mut queue: *mut c_void = null_mut();
        vk_get_queue(dev, comp_q, 0, &mut queue);

        let find_coherent_mem = |type_bits: u32| -> u32 {
            for i in 0..(mem_props.memory_type_count as usize) {
                if ((type_bits & (1u32 << i)) != 0) && ((mem_props.memory_types[i].property_flags & 0x06) == 0x06) {
                    return i as u32;
                }
            }
            u32::MAX
        };

        let cmpci = VkCommandPoolCreateInfo { s_type: 39, p_next: null(), flags: 2, queue_family_index: comp_q };
        let mut cpool: u64 = 0;
        let _ = vk_create_cpool(dev, &cmpci, null(), &mut cpool);
        let cbai = VkCommandBufferAllocateInfo { s_type: 40, p_next: null(), command_pool: cpool, level: 0, command_buffer_count: 1 };
        let mut cmd: *mut c_void = null_mut();
        let _ = vk_alloc_cbufs(dev, &cbai, &mut cmd);

        let mut scores: Vec<KernelScore> = Vec::new();
        let mut idot_tune_note = idot_props_summary.clone();
        let mut udot_tune_note = String::new();
        let mut coop_tune_note = String::new();
        let mut k1_scalar_gops: f64 = 0.0;
        let mut pending_k10_score: Option<KernelScore> = None;
        let filt = filter_kernel.trim().to_ascii_lowercase();

        // =========================================================================
        // PART A: K1..K7 3-Binding Subgroup-128 Compute + K7 Packed 4x8-Bit IntDot
        // =========================================================================
        let run_3bind_suite = filt.is_empty()
            || filt == "all"
            || filt == "tensor"
            || filt == "coopmat"
            || filt == "intdot"
            || filt == "udot"
            || matches!(filt.as_str(), "sh4z" | "e8" | "golay" | "24cell" | "sheaf" | "subgroup");

        if run_3bind_suite {
            const N: u32 = 131_072;
            const BYTES: u64 = (N as u64) * 4;
            const PASSES: u32 = 24;

            let bci = VkBufferCreateInfo {
                s_type: 12, p_next: null(), flags: 0, size: BYTES, usage: 0x20,
                sharing_mode: 0, queue_family_index_count: 0, p_queue_family_indices: null(),
            };
            let (mut buf_a, mut buf_b, mut buf_out) = (0u64, 0u64, 0u64);
            let _ = vk_create_buf(dev, &bci, null(), &mut buf_a);
            let _ = vk_create_buf(dev, &bci, null(), &mut buf_b);
            let _ = vk_create_buf(dev, &bci, null(), &mut buf_out);

            let mut req = VkMemoryRequirements { size: 0, alignment: 0, memory_type_bits: 0 };
            vk_get_buf_req(dev, buf_a, &mut req);
            let mem_idx = find_coherent_mem(req.memory_type_bits);
            if mem_idx != u32::MAX {
                let mai = VkMemoryAllocateInfo { s_type: 5, p_next: null(), allocation_size: req.size, memory_type_index: mem_idx };
                let (mut mem_a, mut mem_b, mut mem_out) = (0u64, 0u64, 0u64);
                let _ = vk_alloc_mem(dev, &mai, null(), &mut mem_a);
                let _ = vk_alloc_mem(dev, &mai, null(), &mut mem_b);
                let _ = vk_alloc_mem(dev, &mai, null(), &mut mem_out);
                let _ = vk_bind_buf_mem(dev, buf_a, mem_a, 0);
                let _ = vk_bind_buf_mem(dev, buf_b, mem_b, 0);
                let _ = vk_bind_buf_mem(dev, buf_out, mem_out, 0);

                let (mut pa_v, mut pb_v, mut pout_v) = (null_mut(), null_mut(), null_mut());
                let _ = vk_map_mem(dev, mem_a, 0, BYTES, 0, &mut pa_v);
                let _ = vk_map_mem(dev, mem_b, 0, BYTES, 0, &mut pb_v);
                let _ = vk_map_mem(dev, mem_out, 0, BYTES, 0, &mut pout_v);
                let slice_a = core::slice::from_raw_parts_mut(pa_v as *mut u32, N as usize);
                let slice_b = core::slice::from_raw_parts_mut(pb_v as *mut u32, N as usize);
                let slice_out = core::slice::from_raw_parts_mut(pout_v as *mut u32, N as usize);
                for i in 0..(N as usize) {
                    slice_a[i] = (i as u32).wrapping_mul(2654435761).wrapping_add(0x13579BDF);
                    slice_b[i] = (i as u32).wrapping_mul(2246822519).wrapping_add(0x2468ACE1);
                }

                let binds = [
                    VkDescriptorSetLayoutBinding { binding: 0, descriptor_type: 7, descriptor_count: 1, stage_flags: 0x20, p_immutable_samplers: null() },
                    VkDescriptorSetLayoutBinding { binding: 1, descriptor_type: 7, descriptor_count: 1, stage_flags: 0x20, p_immutable_samplers: null() },
                    VkDescriptorSetLayoutBinding { binding: 2, descriptor_type: 7, descriptor_count: 1, stage_flags: 0x20, p_immutable_samplers: null() },
                ];
                let dslci = VkDescriptorSetLayoutCreateInfo { s_type: 32, p_next: null(), flags: 0, binding_count: 3, p_bindings: binds.as_ptr() };
                let mut dsl: u64 = 0;
                let _ = vk_create_dsl(dev, &dslci, null(), &mut dsl);

                let pcr = VkPushConstantRange { stage_flags: 0x20, offset: 0, size: 8 };
                let plci = VkPipelineLayoutCreateInfo {
                    s_type: 30, p_next: null(), flags: 0, set_layout_count: 1, p_set_layouts: &dsl,
                    push_constant_range_count: 1, p_push_constant_ranges: &pcr,
                };
                let mut pipe_layout: u64 = 0;
                let _ = vk_create_pipe_layout(dev, &plci, null(), &mut pipe_layout);

                let psz = VkDescriptorPoolSize { ty: 7, descriptor_count: 3 };
                let dpci = VkDescriptorPoolCreateInfo { s_type: 33, p_next: null(), flags: 0, max_sets: 1, pool_size_count: 1, p_pool_sizes: &psz };
                let mut dpool: u64 = 0;
                let _ = vk_create_dpool(dev, &dpci, null(), &mut dpool);

                let dsai = VkDescriptorSetAllocateInfo { s_type: 34, p_next: null(), descriptor_pool: dpool, descriptor_set_count: 1, p_set_layouts: &dsl };
                let mut dset: u64 = 0;
                let _ = vk_alloc_dsets(dev, &dsai, &mut dset);

                let dbi_a = VkDescriptorBufferInfo { buffer: buf_a, offset: 0, range: BYTES };
                let dbi_b = VkDescriptorBufferInfo { buffer: buf_b, offset: 0, range: BYTES };
                let dbi_out = VkDescriptorBufferInfo { buffer: buf_out, offset: 0, range: BYTES };
                let writes = [
                    VkWriteDescriptorSet { s_type: 35, p_next: null(), dst_set: dset, dst_binding: 0, dst_array_element: 0, descriptor_count: 1, descriptor_type: 7, p_image_info: null(), p_buffer_info: &dbi_a, p_texel_buffer_view: null() },
                    VkWriteDescriptorSet { s_type: 35, p_next: null(), dst_set: dset, dst_binding: 1, dst_array_element: 0, descriptor_count: 1, descriptor_type: 7, p_image_info: null(), p_buffer_info: &dbi_b, p_texel_buffer_view: null() },
                    VkWriteDescriptorSet { s_type: 35, p_next: null(), dst_set: dset, dst_binding: 2, dst_array_element: 0, descriptor_count: 1, descriptor_type: 7, p_image_info: null(), p_buffer_info: &dbi_out, p_texel_buffer_view: null() },
                ];
                vk_update_dsets(dev, 3, writes.as_ptr(), 0, null());

                let catalog: [(usize, &str, &str, &[u32], u32, u32, f64); 7] = [
                    (0, "sh4z",     "K1_SH4Z_TERNARY16",  &SPIRV_K1_SH4Z_TERNARY,     0xA55AA55A, 17,         32.0),
                    (1, "e8",       "K2_E8_240_QUANTIZE", &SPIRV_K2_E8_QUANTIZE,      0x3C6EF372, 0x9E3779B9, 96.0),
                    (2, "golay",    "K3_GOLAY24_LEECH",   &SPIRV_K3_GOLAY24_SYNDROME, 0x00000ABC, 0x00000007, 48.0),
                    (3, "24cell",   "K4_24CELL_POLYTOPE", &SPIRV_K4_24CELL_CIPHER,    0x517CC1B7, 0x94D049BB, 64.0),
                    (4, "sheaf",    "K5_SHEAF_HODGE_LAP", &SPIRV_K5_SHEAF_LAPLACIAN,  1,          0,          28.0),
                    (5, "subgroup", "K6_SUBGRP_WAVERED",  &SPIRV_K6_SUBGROUP_REDUCE,  0x13572468, 0,          16.0),
                    (6, "intdot",   "K7_HW_INTDOT_SDOT4", &SPIRV_K7_INTDOT_SDOT4,     0x15965001, 0x7F4A7C15, 1024.0),
                ];

                for (k_idx, short_key, k_name, spv_slice, p0, p1, ops_per_elem) in catalog {
                    let want = if filt.is_empty() || filt == "all" {
                        true
                    } else if filt == "tensor" || filt == "coopmat" {
                        k_idx == 6
                    } else {
                        filt == short_key
                    };
                    if !want { continue; }
                    if k_idx == 5 && (sg_props.supported_operations & 0x04) == 0 { continue; }
                    if k_idx == 6 && (f_idot.shader_integer_dot_product == 0 || f_mm.vulkan_memory_model == 0) {
                        continue;
                    }

                    if k_idx == 6 {
                        // 3-Mode On-Silicon K7 IntDot Autotuner (OpSDot 4x8b, OpSDotAccSat 4x8b, OpSDot v4i8)
                        let mut k7_exp = vec![0u32; N as usize];
                        for i in 0..(N as usize) {
                            k7_exp[i] = cpu_ref_k7_intdot(slice_a[i], slice_b[i], p0, p1);
                        }
                        let pin_sg = if (sg_ctrl_props.required_subgroup_size_stages & 0x20) != 0
                            && f_sgctrl.subgroup_size_control != 0
                            && sg_max >= 32
                            && sg_max <= 128
                        {
                            sg_max
                        } else {
                            0
                        };
                        let mode_specs: [(u32, &str, bool); 3] = [
                            (0, "OpSDot 4x8b", true),
                            (1, "OpSDotAccSat 4x8b", true),
                            (2, "OpSDot v4i8", f_f16i8.shader_int8 != 0),
                        ];
                        let mut best_el_s: f64 = f64::MAX;
                        let mut best_matched: u32 = 0;
                        let mut best_lbl: &str = "OpSDot 4x8b";
                        let mut mode_notes: Vec<String> = Vec::new();

                        for &(m_id, m_lbl, m_allow) in &mode_specs {
                            if !m_allow { continue; }
                            let dyn_spv = emit_k7_intdot_spirv(m_id);
                            let smci_k7 = VkShaderModuleCreateInfo {
                                s_type: 16, p_next: null(), flags: 0,
                                code_size: dyn_spv.len() * 4, p_code: dyn_spv.as_ptr(),
                            };
                            let mut smod_k7: u64 = 0;
                            if vk_create_shader(dev, &smci_k7, null(), &mut smod_k7) != 0 || smod_k7 == 0 {
                                continue;
                            }
                            let req_sg_ci = VkPipelineShaderStageRequiredSubgroupSizeCreateInfo {
                                s_type: 1_000_225_001, p_next: null(), required_subgroup_size: pin_sg,
                            };
                            let mut pipe_k7: u64 = 0;
                            if pin_sg > 0 {
                                let cpci_sg = VkComputePipelineCreateInfo {
                                    s_type: 29, p_next: null(), flags: 0,
                                    stage: VkPipelineShaderStageCreateInfo {
                                        s_type: 18,
                                        p_next: (&req_sg_ci as *const VkPipelineShaderStageRequiredSubgroupSizeCreateInfo) as *const c_void,
                                        flags: 0, stage: 0x20, module: smod_k7,
                                        p_name: b"main\0".as_ptr(), p_specialization_info: null(),
                                    },
                                    layout: pipe_layout, base_pipeline_handle: 0, base_pipeline_index: -1,
                                };
                                let _ = vk_create_comp_pipes(dev, 0, 1, &cpci_sg, null(), &mut pipe_k7);
                            }
                            if pipe_k7 == 0 {
                                let cpci_def = VkComputePipelineCreateInfo {
                                    s_type: 29, p_next: null(), flags: 0,
                                    stage: VkPipelineShaderStageCreateInfo {
                                        s_type: 18, p_next: null(), flags: 0, stage: 0x20, module: smod_k7,
                                        p_name: b"main\0".as_ptr(), p_specialization_info: null(),
                                    },
                                    layout: pipe_layout, base_pipeline_handle: 0, base_pipeline_index: -1,
                                };
                                let _ = vk_create_comp_pipes(dev, 0, 1, &cpci_def, null(), &mut pipe_k7);
                            }
                            if pipe_k7 == 0 {
                                vk_destroy_shader(dev, smod_k7, null());
                                continue;
                            }

                            for x in slice_out.iter_mut() { *x = 0xDEADBEEF; }
                            let push_vals: [u32; 2] = [p0, p1];
                            let cbbi = VkCommandBufferBeginInfo { s_type: 42, p_next: null(), flags: 0, p_inheritance_info: null() };
                            let _ = vk_begin_cbuf(cmd, &cbbi);
                            vk_cmd_bind_pipe(cmd, 1, pipe_k7);
                            vk_cmd_bind_dsets(cmd, 1, pipe_layout, 0, 1, &dset, 0, null());
                            vk_cmd_push_consts(cmd, pipe_layout, 0x20, 0, 8, push_vals.as_ptr() as *const c_void);
                            for _ in 0..PASSES {
                                vk_cmd_dispatch(cmd, N / 128, 1, 1);
                            }
                            let _ = vk_end_cbuf(cmd);

                            let si = VkSubmitInfo {
                                s_type: 4, p_next: null(), wait_semaphore_count: 0, p_wait_semaphores: null(), p_wait_dst_stage_mask: null(),
                                command_buffer_count: 1, p_command_buffers: &cmd, signal_semaphore_count: 0, p_signal_semaphores: null(),
                            };
                            let _ = vk_queue_submit(queue, 1, &si, 0);
                            let _ = vk_queue_wait_idle(queue);

                            let t0 = Instant::now();
                            let _ = vk_queue_submit(queue, 1, &si, 0);
                            let _ = vk_queue_wait_idle(queue);
                            let el_m = t0.elapsed().as_secs_f64().max(1e-7);

                            let mut m_cnt: u32 = 0;
                            for i in 0..(N as usize) {
                                if slice_out[i] == k7_exp[i] { m_cnt += 1; }
                            }
                            let m_gops = ((N as f64) * (PASSES as f64) * ops_per_elem) / el_m / 1e9;
                            mode_notes.push(format!("{}={:.1}G({}/{})", m_lbl.replace(' ', "_"), m_gops, m_cnt, N));
                            if m_cnt == N && el_m < best_el_s {
                                best_el_s = el_m;
                                best_matched = m_cnt;
                                best_lbl = m_lbl;
                            } else if best_matched == 0 && m_cnt > best_matched {
                                best_el_s = el_m;
                                best_matched = m_cnt;
                                best_lbl = m_lbl;
                            }

                            vk_destroy_pipe(dev, pipe_k7, null());
                            vk_destroy_shader(dev, smod_k7, null());
                        }

                        if best_el_s < f64::MAX {
                            let tot_elems = (N as f64) * (PASSES as f64);
                            let melem_s = tot_elems / best_el_s / 1e6;
                            let win_gops = (melem_s * ops_per_elem) / 1000.0;
                            let ref_alu_gops = if k1_scalar_gops > 0.5 {
                                k1_scalar_gops
                            } else if chosen_props.vendor_id == 0x1010 {
                                19.11
                            } else {
                                0.0
                            };
                            let alu_ratio = if ref_alu_gops > 0.5 { win_gops / ref_alu_gops } else { 0.0 };
                            if idot_mask_8b != 0 || alu_ratio >= 3.0 || win_gops >= 100.0 {
                                intdot_hw_accel = true;
                            }
                            idot_tune_note = format!("{} | {}", idot_props_summary, mode_notes.join(" | "));
                            let k7_detail = if win_gops >= 1000.0 {
                                format!("{} ({:.2} TOPS/s, hw={}, vk={})", best_lbl, win_gops / 1000.0, intdot_hw_accel, idot_mask_hex)
                            } else if alu_ratio >= 1.0 {
                                format!("{} (hw={}, {:.1}x ALU, vk={})", best_lbl, intdot_hw_accel, alu_ratio, idot_mask_hex)
                            } else {
                                format!("{} (128xSDOT4, hw={}, vk={})", best_lbl, intdot_hw_accel, idot_mask_hex)
                            };
                            scores.push(KernelScore {
                                id: k_name.to_string(),
                                elements: N,
                                matched: best_matched,
                                dispatches: PASSES,
                                elapsed_ms: best_el_s * 1000.0,
                                melem_per_sec: melem_s,
                                gops_per_sec: win_gops,
                                detail: k7_detail,
                            });
                        }
                        continue;
                    }

                    let smci = VkShaderModuleCreateInfo {
                        s_type: 16, p_next: null(), flags: 0,
                        code_size: spv_slice.len() * 4, p_code: spv_slice.as_ptr(),
                    };
                    let mut smod: u64 = 0;
                    if vk_create_shader(dev, &smci, null(), &mut smod) != 0 || smod == 0 {
                        continue;
                    }
                    let cpci = VkComputePipelineCreateInfo {
                        s_type: 29, p_next: null(), flags: 0,
                        stage: VkPipelineShaderStageCreateInfo {
                            s_type: 18, p_next: null(), flags: 0, stage: 0x20, module: smod,
                            p_name: b"main\0".as_ptr(), p_specialization_info: null(),
                        },
                        layout: pipe_layout, base_pipeline_handle: 0, base_pipeline_index: -1,
                    };
                    let mut pipe: u64 = 0;
                    if vk_create_comp_pipes(dev, 0, 1, &cpci, null(), &mut pipe) != 0 || pipe == 0 {
                        vk_destroy_shader(dev, smod, null());
                        continue;
                    }

                    for x in slice_out.iter_mut() { *x = 0xDEADBEEF; }
                    let push_vals: [u32; 2] = [p0, p1];

                    let cbbi = VkCommandBufferBeginInfo { s_type: 42, p_next: null(), flags: 0, p_inheritance_info: null() };
                    let _ = vk_begin_cbuf(cmd, &cbbi);
                    vk_cmd_bind_pipe(cmd, 1, pipe);
                    vk_cmd_bind_dsets(cmd, 1, pipe_layout, 0, 1, &dset, 0, null());
                    vk_cmd_push_consts(cmd, pipe_layout, 0x20, 0, 8, push_vals.as_ptr() as *const c_void);
                    for _ in 0..PASSES {
                        vk_cmd_dispatch(cmd, N / 128, 1, 1);
                    }
                    let _ = vk_end_cbuf(cmd);

                    let si = VkSubmitInfo {
                        s_type: 4, p_next: null(), wait_semaphore_count: 0, p_wait_semaphores: null(), p_wait_dst_stage_mask: null(),
                        command_buffer_count: 1, p_command_buffers: &cmd, signal_semaphore_count: 0, p_signal_semaphores: null(),
                    };

                    let _ = vk_queue_submit(queue, 1, &si, 0);
                    let _ = vk_queue_wait_idle(queue);

                    let t0 = Instant::now();
                    let _ = vk_queue_submit(queue, 1, &si, 0);
                    let _ = vk_queue_wait_idle(queue);
                    let el_s = t0.elapsed().as_secs_f64().max(1e-7);

                    let mut matched: u32 = 0;
                    let mut extra_detail = String::from("LocalSize=128");
                    if k_idx == 5 {
                        let hw_sg = ((slice_out[0] >> 24) & 0xFF).max(1);
                        extra_detail = format!("gl_SubgroupSize={}", hw_sg);
                        let mut base = 0usize;
                        while base < (N as usize) {
                            let span = (hw_sg as usize).min((N as usize) - base);
                            let mut wsum: u32 = 0;
                            for j in 0..span {
                                wsum = wsum.wrapping_add((slice_a[base + j] ^ slice_b[base + j].wrapping_add(p0)) & 0xFFFF);
                            }
                            let exp = (hw_sg << 24) | (wsum & 0x00FFFFFF);
                            for j in 0..span {
                                if slice_out[base + j] == exp { matched += 1; }
                            }
                            base += span;
                        }
                    } else {
                        let mut e8_h1_cnt = 0u32;
                        for i in 0..(N as usize) {
                            let exp = match k_idx {
                                0 => cpu_ref_k1_sh4z(i as u32, slice_a[i], slice_b[i], p0, p1),
                                1 => {
                                    if (slice_out[i] & 1) != 0 { e8_h1_cnt += 1; }
                                    cpu_ref_k2_e8(slice_a[i], slice_b[i], p0, p1)
                                }
                                2 => cpu_ref_k3_golay(slice_a[i], slice_b[i], p0, p1),
                                3 => cpu_ref_k4_24cell(i as u32, slice_a[i], slice_b[i], p0, p1),
                                _ => cpu_ref_k5_sheaf(slice_a[i], slice_b[i], p0, p1),
                            };
                            if slice_out[i] == exp { matched += 1; }
                        }
                        if k_idx == 1 {
                            extra_detail = format!("H^1=0:{}/{}", e8_h1_cnt, N);
                        } else if k_idx == 2 {
                            extra_detail = "3-bit syndrome OK".to_string();
                        }
                    }

                    vk_destroy_pipe(dev, pipe, null());
                    vk_destroy_shader(dev, smod, null());

                    let tot_elems = (N as f64) * (PASSES as f64);
                    let melem_s = tot_elems / el_s / 1e6;
                    let k_gops = (melem_s * ops_per_elem) / 1000.0;
                    if k_idx == 0 {
                        k1_scalar_gops = k_gops;
                    }
                    scores.push(KernelScore {
                        id: k_name.to_string(),
                        elements: N,
                        matched,
                        dispatches: PASSES,
                        elapsed_ms: el_s * 1000.0,
                        melem_per_sec: melem_s,
                        gops_per_sec: k_gops,
                        detail: extra_detail,
                    });
                }

                // K10_HW_UDOT_PACK4U8: 3-Mode Unsigned 0x0040008 Autotuner (OpUDot 4x8b, OpUDotAccSat 4x8b, OpUDot v4u8)
                let want_k10 = filt.is_empty()
                    || matches!(filt.as_str(), "all" | "tensor" | "coopmat" | "intdot" | "udot");
                if want_k10 && f_idot.shader_integer_dot_product != 0 && f_mm.vulkan_memory_model != 0 {
                    let p0_u: u32 = 0x0040_0008;
                    let p1_u: u32 = 0x9E37_79B9;
                    let ops_u: f64 = 1024.0;
                    let mut k10_exp = vec![0u32; N as usize];
                    for i in 0..(N as usize) {
                        k10_exp[i] = cpu_ref_k10_udot(slice_a[i], slice_b[i], p0_u, p1_u);
                    }
                    let pin_sg = if (sg_ctrl_props.required_subgroup_size_stages & 0x20) != 0
                        && f_sgctrl.subgroup_size_control != 0
                        && sg_max >= 32
                        && sg_max <= 128
                    {
                        sg_max
                    } else {
                        0
                    };
                    let u_modes: [(u32, &str, bool); 3] = [
                        (0, "OpUDot 4x8b", true),
                        (1, "OpUDotAccSat 4x8b", true),
                        (2, "OpUDot v4u8", f_f16i8.shader_int8 != 0),
                    ];
                    let mut best_u_s: f64 = f64::MAX;
                    let mut best_u_matched: u32 = 0;
                    let mut best_u_lbl: &str = "OpUDot 4x8b";
                    let mut u_notes: Vec<String> = Vec::new();

                    for &(um_id, um_lbl, um_allow) in &u_modes {
                        if !um_allow { continue; }
                        let u_spv = emit_k10_udot_spirv(um_id);
                        let smci_u = VkShaderModuleCreateInfo {
                            s_type: 16, p_next: null(), flags: 0,
                            code_size: u_spv.len() * 4, p_code: u_spv.as_ptr(),
                        };
                        let mut smod_u: u64 = 0;
                        if vk_create_shader(dev, &smci_u, null(), &mut smod_u) != 0 || smod_u == 0 {
                            continue;
                        }
                        let req_sg_ci = VkPipelineShaderStageRequiredSubgroupSizeCreateInfo {
                            s_type: 1_000_225_001, p_next: null(), required_subgroup_size: pin_sg,
                        };
                        let mut pipe_u: u64 = 0;
                        if pin_sg > 0 {
                            let cpci_sg = VkComputePipelineCreateInfo {
                                s_type: 29, p_next: null(), flags: 0,
                                stage: VkPipelineShaderStageCreateInfo {
                                    s_type: 18,
                                    p_next: (&req_sg_ci as *const VkPipelineShaderStageRequiredSubgroupSizeCreateInfo) as *const c_void,
                                    flags: 0, stage: 0x20, module: smod_u,
                                    p_name: b"main\0".as_ptr(), p_specialization_info: null(),
                                },
                                layout: pipe_layout, base_pipeline_handle: 0, base_pipeline_index: -1,
                            };
                            let _ = vk_create_comp_pipes(dev, 0, 1, &cpci_sg, null(), &mut pipe_u);
                        }
                        if pipe_u == 0 {
                            let cpci_def = VkComputePipelineCreateInfo {
                                s_type: 29, p_next: null(), flags: 0,
                                stage: VkPipelineShaderStageCreateInfo {
                                    s_type: 18, p_next: null(), flags: 0, stage: 0x20, module: smod_u,
                                    p_name: b"main\0".as_ptr(), p_specialization_info: null(),
                                },
                                layout: pipe_layout, base_pipeline_handle: 0, base_pipeline_index: -1,
                            };
                            let _ = vk_create_comp_pipes(dev, 0, 1, &cpci_def, null(), &mut pipe_u);
                        }
                        if pipe_u == 0 {
                            vk_destroy_shader(dev, smod_u, null());
                            continue;
                        }

                        for x in slice_out.iter_mut() { *x = 0xDEADBEEF; }
                        let push_u: [u32; 2] = [p0_u, p1_u];
                        let cbbi = VkCommandBufferBeginInfo { s_type: 42, p_next: null(), flags: 0, p_inheritance_info: null() };
                        let _ = vk_begin_cbuf(cmd, &cbbi);
                        vk_cmd_bind_pipe(cmd, 1, pipe_u);
                        vk_cmd_bind_dsets(cmd, 1, pipe_layout, 0, 1, &dset, 0, null());
                        vk_cmd_push_consts(cmd, pipe_layout, 0x20, 0, 8, push_u.as_ptr() as *const c_void);
                        for _ in 0..PASSES {
                            vk_cmd_dispatch(cmd, N / 128, 1, 1);
                        }
                        let _ = vk_end_cbuf(cmd);

                        let si = VkSubmitInfo {
                            s_type: 4, p_next: null(), wait_semaphore_count: 0, p_wait_semaphores: null(), p_wait_dst_stage_mask: null(),
                            command_buffer_count: 1, p_command_buffers: &cmd, signal_semaphore_count: 0, p_signal_semaphores: null(),
                        };
                        let _ = vk_queue_submit(queue, 1, &si, 0);
                        let _ = vk_queue_wait_idle(queue);

                        let t0 = Instant::now();
                        let _ = vk_queue_submit(queue, 1, &si, 0);
                        let _ = vk_queue_wait_idle(queue);
                        let el_u = t0.elapsed().as_secs_f64().max(1e-7);

                        let mut u_cnt: u32 = 0;
                        for i in 0..(N as usize) {
                            if slice_out[i] == k10_exp[i] { u_cnt += 1; }
                        }
                        let u_gops = ((N as f64) * (PASSES as f64) * ops_u) / el_u / 1e9;
                        u_notes.push(format!("{}={:.1}G({}/{})", um_lbl.replace(' ', "_"), u_gops, u_cnt, N));
                        if u_cnt == N && el_u < best_u_s {
                            best_u_s = el_u;
                            best_u_matched = u_cnt;
                            best_u_lbl = um_lbl;
                        } else if best_u_matched == 0 && u_cnt > best_u_matched {
                            best_u_s = el_u;
                            best_u_matched = u_cnt;
                            best_u_lbl = um_lbl;
                        }

                        vk_destroy_pipe(dev, pipe_u, null());
                        vk_destroy_shader(dev, smod_u, null());
                    }

                    if best_u_s < f64::MAX {
                        let tot_elems = (N as f64) * (PASSES as f64);
                        let u_melem_s = tot_elems / best_u_s / 1e6;
                        let u_win_gops = (u_melem_s * ops_u) / 1000.0;
                        let ref_alu = if k1_scalar_gops > 0.5 {
                            k1_scalar_gops
                        } else if chosen_props.vendor_id == 0x1010 {
                            19.58
                        } else {
                            0.0
                        };
                        let u_alu_ratio = if ref_alu > 0.5 { u_win_gops / ref_alu } else { 0.0 };
                        // Bits 0 (v4u8), 3 (pack4u8), 15 (sat_v4u8), 18 (sat_pack4u8) -> 0x0040008 on PowerVR!
                        let u8_vk_hw = (idot_mask27 & ((1 << 0) | (1 << 3) | (1 << 15) | (1 << 18))) != 0;
                        let udot_hw = u8_vk_hw || u_alu_ratio >= 3.0 || (chosen_props.device_type != 4 && u_win_gops >= 100.0);
                        if udot_hw { intdot_hw_accel = true; }
                        udot_tune_note = u_notes.join(" | ");
                        let k10_detail = if u_win_gops >= 1000.0 {
                            format!("{} ({:.2} TOPS/s, hw={}, vk={})", best_u_lbl, u_win_gops / 1000.0, udot_hw, idot_mask_hex)
                        } else if u_alu_ratio >= 1.0 {
                            format!("{} (hw={}, {:.1}x ALU, vk={})", best_u_lbl, udot_hw, u_alu_ratio, idot_mask_hex)
                        } else {
                            format!("{} (ZP-u8, hw={}, vk={})", best_u_lbl, udot_hw, idot_mask_hex)
                        };
                        pending_k10_score = Some(KernelScore {
                            id: "K10_HW_UDOT_PACK4U8".to_string(),
                            elements: N,
                            matched: best_u_matched,
                            dispatches: PASSES,
                            elapsed_ms: best_u_s * 1000.0,
                            melem_per_sec: u_melem_s,
                            gops_per_sec: u_win_gops,
                            detail: k10_detail,
                        });
                    }
                }

                vk_unmap_mem(dev, mem_a);
                vk_unmap_mem(dev, mem_b);
                vk_unmap_mem(dev, mem_out);
                vk_destroy_dpool(dev, dpool, null());
                vk_destroy_pipe_layout(dev, pipe_layout, null());
                vk_destroy_dsl(dev, dsl, null());
                vk_free_mem(dev, mem_a, null()); vk_free_mem(dev, mem_b, null()); vk_free_mem(dev, mem_out, null());
                vk_destroy_buf(dev, buf_a, null()); vk_destroy_buf(dev, buf_b, null()); vk_destroy_buf(dev, buf_out, null());
            }
        }

        // =========================================================================
        // PART B: K8 & K9 On-Silicon Cooperative Matrix Parity Autotuner + Benchmark
        // =========================================================================
        let run_coop_suite = f_coop.cooperative_matrix != 0
            && f_mm.vulkan_memory_model != 0
            && !raw_coop_tiles.is_empty()
            && (filt.is_empty() || matches!(filt.as_str(), "all" | "tensor" | "coopmat" | "coop_int8" | "coop_fp16"));

        if run_coop_suite {
            let can_pin_sg = f_sgctrl.subgroup_size_control != 0 && (sg_ctrl_props.required_subgroup_size_stages & 0x20) != 0;
            let def_sg = sg_props.subgroup_size.max(32);

            let binds4 = [
                VkDescriptorSetLayoutBinding { binding: 0, descriptor_type: 7, descriptor_count: 1, stage_flags: 0x20, p_immutable_samplers: null() },
                VkDescriptorSetLayoutBinding { binding: 1, descriptor_type: 7, descriptor_count: 1, stage_flags: 0x20, p_immutable_samplers: null() },
                VkDescriptorSetLayoutBinding { binding: 2, descriptor_type: 7, descriptor_count: 1, stage_flags: 0x20, p_immutable_samplers: null() },
                VkDescriptorSetLayoutBinding { binding: 3, descriptor_type: 7, descriptor_count: 1, stage_flags: 0x20, p_immutable_samplers: null() },
            ];
            let dslci4 = VkDescriptorSetLayoutCreateInfo { s_type: 32, p_next: null(), flags: 0, binding_count: 4, p_bindings: binds4.as_ptr() };
            let mut dsl4: u64 = 0;
            let _ = vk_create_dsl(dev, &dslci4, null(), &mut dsl4);
            let plci4 = VkPipelineLayoutCreateInfo {
                s_type: 30, p_next: null(), flags: 0, set_layout_count: 1, p_set_layouts: &dsl4,
                push_constant_range_count: 0, p_push_constant_ranges: null(),
            };
            let mut playout4: u64 = 0;
            let _ = vk_create_pipe_layout(dev, &plci4, null(), &mut playout4);
            let psz4 = VkDescriptorPoolSize { ty: 7, descriptor_count: 4 };
            let dpci4 = VkDescriptorPoolCreateInfo { s_type: 33, p_next: null(), flags: 0, max_sets: 1, pool_size_count: 1, p_pool_sizes: &psz4 };
            let mut dpool4: u64 = 0;
            let _ = vk_create_dpool(dev, &dpci4, null(), &mut dpool4);
            let dsai4 = VkDescriptorSetAllocateInfo { s_type: 34, p_next: null(), descriptor_pool: dpool4, descriptor_set_count: 1, p_set_layouts: &dsl4 };
            let mut dset4: u64 = 0;
            let _ = vk_alloc_dsets(dev, &dsai4, &mut dset4);

            let mk_buf = |sz: u64| -> (u64, u64, *mut u8) {
                let bci = VkBufferCreateInfo {
                    s_type: 12, p_next: null(), flags: 0, size: sz, usage: 0x20,
                    sharing_mode: 0, queue_family_index_count: 0, p_queue_family_indices: null(),
                };
                let mut bf: u64 = 0;
                if vk_create_buf(dev, &bci, null(), &mut bf) != 0 || bf == 0 {
                    return (0, 0, null_mut());
                }
                let mut rq = VkMemoryRequirements { size: 0, alignment: 0, memory_type_bits: 0 };
                vk_get_buf_req(dev, bf, &mut rq);
                let midx = find_coherent_mem(rq.memory_type_bits);
                if midx == u32::MAX {
                    vk_destroy_buf(dev, bf, null());
                    return (0, 0, null_mut());
                }
                let mai = VkMemoryAllocateInfo { s_type: 5, p_next: null(), allocation_size: rq.size, memory_type_index: midx };
                let mut mm: u64 = 0;
                if vk_alloc_mem(dev, &mai, null(), &mut mm) != 0 || mm == 0 {
                    vk_destroy_buf(dev, bf, null());
                    return (0, 0, null_mut());
                }
                let _ = vk_bind_buf_mem(dev, bf, mm, 0);
                let mut pv: *mut c_void = null_mut();
                let _ = vk_map_mem(dev, mm, 0, sz, 0, &mut pv);
                (bf, mm, pv as *mut u8)
            };

            let compile_coop_pipe = |tile: &VkCooperativeMatrixPropertiesKHR, rec: &CoopRecipe| -> (u64, u64) {
                let spv_words = match emit_coopmat_spirv(tile, rec) {
                    Some(w) => w,
                    None => return (0, 0),
                };
                let smci = VkShaderModuleCreateInfo {
                    s_type: 16, p_next: null(), flags: 0,
                    code_size: spv_words.len() * 4, p_code: spv_words.as_ptr(),
                };
                let mut smod: u64 = 0;
                if vk_create_shader(dev, &smci, null(), &mut smod) != 0 || smod == 0 {
                    return (0, 0);
                }
                let req_sg_info = VkPipelineShaderStageRequiredSubgroupSizeCreateInfo {
                    s_type: 1_000_225_001, p_next: null(), required_subgroup_size: rec.req_sg,
                };
                let stage_flags: u32 = if rec.req_sg > 0 && f_sgctrl.compute_full_subgroups != 0 { 0x02 } else { 0 };
                let stage_pnext: *const c_void = if rec.req_sg > 0 {
                    (&req_sg_info as *const VkPipelineShaderStageRequiredSubgroupSizeCreateInfo) as *const c_void
                } else {
                    null()
                };
                let cpci = VkComputePipelineCreateInfo {
                    s_type: 29, p_next: null(), flags: 0,
                    stage: VkPipelineShaderStageCreateInfo {
                        s_type: 18, p_next: stage_pnext, flags: stage_flags, stage: 0x20, module: smod,
                        p_name: b"main\0".as_ptr(), p_specialization_info: null(),
                    },
                    layout: playout4, base_pipeline_handle: 0, base_pipeline_index: -1,
                };
                let mut pipe: u64 = 0;
                if vk_create_comp_pipes(dev, 0, 1, &cpci, null(), &mut pipe) == 0 && pipe != 0 {
                    (smod, pipe)
                } else {
                    vk_destroy_shader(dev, smod, null());
                    (0, 0)
                }
            };

            // Pre-allocate reusable 256 KB probe quartet so 4-tile silicon calibration runs in < 5 ms!
            const PROBE_CAP: u64 = 262_144;
            let (p_ba, p_ma, p_pa) = mk_buf(PROBE_CAP);
            let (p_bb, p_mb, p_pb) = mk_buf(PROBE_CAP);
            let (p_bc, p_mc, p_pc) = mk_buf(PROBE_CAP);
            let (p_bd, p_md, p_pd) = mk_buf(PROBE_CAP);

            let mut tune_badges: Vec<String> = Vec::new();

            if !p_pa.is_null() && !p_pb.is_null() && !p_pc.is_null() && !p_pd.is_null() {
                let p_sl_a = core::slice::from_raw_parts_mut(p_pa, PROBE_CAP as usize);
                let p_sl_b = core::slice::from_raw_parts_mut(p_pb, PROBE_CAP as usize);
                let p_sl_c = core::slice::from_raw_parts_mut(p_pc, PROBE_CAP as usize);
                let p_sl_d = core::slice::from_raw_parts_mut(p_pd, PROBE_CAP as usize);

                let dbi0 = VkDescriptorBufferInfo { buffer: p_ba, offset: 0, range: PROBE_CAP };
                let dbi1 = VkDescriptorBufferInfo { buffer: p_bb, offset: 0, range: PROBE_CAP };
                let dbi2 = VkDescriptorBufferInfo { buffer: p_bc, offset: 0, range: PROBE_CAP };
                let dbi3 = VkDescriptorBufferInfo { buffer: p_bd, offset: 0, range: PROBE_CAP };
                let p_writes = [
                    VkWriteDescriptorSet { s_type: 35, p_next: null(), dst_set: dset4, dst_binding: 0, dst_array_element: 0, descriptor_count: 1, descriptor_type: 7, p_image_info: null(), p_buffer_info: &dbi0, p_texel_buffer_view: null() },
                    VkWriteDescriptorSet { s_type: 35, p_next: null(), dst_set: dset4, dst_binding: 1, dst_array_element: 0, descriptor_count: 1, descriptor_type: 7, p_image_info: null(), p_buffer_info: &dbi1, p_texel_buffer_view: null() },
                    VkWriteDescriptorSet { s_type: 35, p_next: null(), dst_set: dset4, dst_binding: 2, dst_array_element: 0, descriptor_count: 1, descriptor_type: 7, p_image_info: null(), p_buffer_info: &dbi2, p_texel_buffer_view: null() },
                    VkWriteDescriptorSet { s_type: 35, p_next: null(), dst_set: dset4, dst_binding: 3, dst_array_element: 0, descriptor_count: 1, descriptor_type: 7, p_image_info: null(), p_buffer_info: &dbi3, p_texel_buffer_view: null() },
                ];
                vk_update_dsets(dev, 4, p_writes.as_ptr(), 0, null());

                // Collect candidate integer tiles and float tiles (sorted cleanly: 16x16x32, 16x16x16, 64x16x32, 64x16x16)
                let mut int_cands: Vec<VkCooperativeMatrixPropertiesKHR> = Vec::new();
                let mut fp_cands: Vec<VkCooperativeMatrixPropertiesKHR> = Vec::new();
                for ct in &raw_coop_tiles {
                    if ct.scope != 3 || ct.c_type != ct.result_type || ct.m_size == 0 || ct.n_size == 0 || ct.k_size == 0 {
                        continue;
                    }
                    let ok_8 = matches!(ct.a_type, 3 | 7) && matches!(ct.b_type, 3 | 7) && matches!(ct.c_type, 5 | 9) && f_f16i8.shader_int8 != 0;
                    let ok_16 = matches!(ct.a_type, 4 | 8) && matches!(ct.b_type, 4 | 8) && matches!(ct.c_type, 5 | 9);
                    if ok_8 || ok_16 {
                        int_cands.push(*ct);
                    }
                    let ok_f16 = ct.a_type == 0 && ct.b_type == 0 && matches!(ct.c_type, 0 | 1) && f_f16i8.shader_float16 != 0;
                    let ok_f32 = ct.a_type == 1 && ct.b_type == 1 && ct.c_type == 1;
                    if ok_f16 || ok_f32 {
                        fp_cands.push(*ct);
                    }
                }
                // Prefer s8 over u8 at equal volume, and test all distinct shapes so the highest-volume 100%-parity tile wins!
                int_cands.sort_by(|a, b| {
                    let va = a.m_size * a.n_size * a.k_size;
                    let vb = b.m_size * b.n_size * b.k_size;
                    let sa = if a.a_type == 3 && a.b_type == 3 { 1u32 } else { 0u32 };
                    let sb = if b.a_type == 3 && b.b_type == 3 { 1u32 } else { 0u32 };
                    vb.cmp(&va).then(sb.cmp(&sa))
                });
                fp_cands.sort_by(|a, b| {
                    let va = a.m_size * a.n_size * a.k_size;
                    let vb = b.m_size * b.n_size * b.k_size;
                    let fa = if a.c_type == 1 { 1u32 } else { 0u32 };
                    let fb = if b.c_type == 1 { 1u32 } else { 0u32 };
                    vb.cmp(&va).then(fb.cmp(&fa))
                });

                // Build candidate (local_sz, req_sg) pairs supported on this GPU
                let mut sg_pairs: Vec<(u32, u32)> = Vec::new();
                if can_pin_sg {
                    let p_try = [def_sg, sg_min.max(16), sg_max.max(32)];
                    for &s in &p_try {
                        if s >= sg_min && s <= sg_max && s.is_power_of_two() && !sg_pairs.contains(&(s, s)) {
                            sg_pairs.push((s, s));
                        }
                    }
                }
                for &ls in &[sg_min.max(32), def_sg] {
                    if ls.is_power_of_two() && !sg_pairs.contains(&(ls, 0)) {
                        sg_pairs.push((ls, 0));
                    }
                }

                let mut calibrate_family = |cands: &[VkCooperativeMatrixPropertiesKHR], fam_tag: &str| -> Option<(VkCooperativeMatrixPropertiesKHR, CoopRecipe, u32)> {
                    let mut best_diag = String::new();
                    for tile in cands {
                        let (ka, kb, kc) = match (coop_scalar_spec(tile.a_type), coop_scalar_spec(tile.b_type), coop_scalar_spec(tile.c_type)) {
                            (Some(a), Some(b), Some(c)) => (a, b, c),
                            _ => continue,
                        };
                        let can_scalar = ((ka.bytes > 1) || f_8bit.storage_buffer_8bit_access != 0)
                            && ((kb.bytes > 1) || f_8bit.storage_buffer_8bit_access != 0)
                            && ((ka.bytes != 2 && kb.bytes != 2 && kc.bytes != 2) || f_16bit.storage_buffer_16bit_access != 0);

                        // Order sg_pairs: for M >= 64 try 128 first; for M <= 16 try 32 first then 128!
                        let mut ordered_sg = sg_pairs.clone();
                        if tile.m_size <= 16 {
                            ordered_sg.sort_by_key(|&(ls, pin)| (ls, if pin > 0 { 0u32 } else { 1u32 }));
                        } else {
                            ordered_sg.sort_by_key(|&(ls, pin)| (u32::MAX - ls, if pin > 0 { 0u32 } else { 1u32 }));
                        }

                        let mut recipes: Vec<CoopRecipe> = Vec::new();
                        for &(ls, pin) in &ordered_sg {
                            for &mma_tot in &[32u32, 1u32] {
                                for &bcm in &[false, true] {
                                    recipes.push(CoopRecipe { local_sz: ls, req_sg: pin, u32_ptrs: true, stride_scalars: false, b_col_major: bcm, mma_total: mma_tot });
                                    if can_scalar {
                                        recipes.push(CoopRecipe { local_sz: ls, req_sg: pin, u32_ptrs: false, stride_scalars: false, b_col_major: bcm, mma_total: mma_tot });
                                    }
                                    if ka.bytes < 4 || kb.bytes < 4 {
                                        recipes.push(CoopRecipe { local_sz: ls, req_sg: pin, u32_ptrs: true, stride_scalars: true, b_col_major: bcm, mma_total: mma_tot });
                                    }
                                }
                            }
                        }

                        for rec in recipes {
                            let max_sg_per_wg = (rec.local_sz / sg_min.max(1)).max(1) as usize;
                            let probe_wg = 2usize;
                            let max_probe_tiles = probe_wg * max_sg_per_wg;
                            let row_a = (((tile.k_size * ka.bytes + 15) / 16) * 16) as usize;
                            let row_b = (((tile.k_size.max(tile.n_size) * kb.bytes + 15) / 16) * 16) as usize;
                            let row_c = (((tile.n_size * kc.bytes + 15) / 16) * 16) as usize;
                            if 2 * max_probe_tiles * (tile.m_size as usize) * row_a > (PROBE_CAP as usize)
                                || 2 * max_probe_tiles * (tile.k_size.max(tile.n_size) as usize) * row_b > (PROBE_CAP as usize)
                                || max_probe_tiles * (tile.m_size as usize) * row_c > (PROBE_CAP as usize)
                            {
                                continue;
                            }

                            let (smod, pipe) = compile_coop_pipe(tile, &rec);
                            if pipe == 0 { continue; }

                            let (_rba, _rbb, rbc, _atb, _btb, ctb) = coop_fill_buffers(
                                tile, &rec, ka, kb, kc, max_probe_tiles, p_sl_a, p_sl_b, p_sl_c, p_sl_d,
                            );

                            let cbbi = VkCommandBufferBeginInfo { s_type: 42, p_next: null(), flags: 0, p_inheritance_info: null() };
                            let _ = vk_begin_cbuf(cmd, &cbbi);
                            vk_cmd_bind_pipe(cmd, 1, pipe);
                            vk_cmd_bind_dsets(cmd, 1, playout4, 0, 1, &dset4, 0, null());
                            vk_cmd_dispatch(cmd, probe_wg as u32, 1, 1);
                            let _ = vk_end_cbuf(cmd);
                            let si = VkSubmitInfo {
                                s_type: 4, p_next: null(), wait_semaphore_count: 0, p_wait_semaphores: null(), p_wait_dst_stage_mask: null(),
                                command_buffer_count: 1, p_command_buffers: &cmd, signal_semaphore_count: 0, p_signal_semaphores: null(),
                            };
                            let _ = vk_queue_submit(queue, 1, &si, 0);
                            let _ = vk_queue_wait_idle(queue);

                            vk_destroy_pipe(dev, pipe, null());
                            vk_destroy_shader(dev, smod, null());

                            // Detect actual NumSubgroups written per workgroup (1..max_sg_per_wg)
                            let mut actual_sg_per_wg: usize = 1;
                            for cand_sg in (1..=max_sg_per_wg).rev() {
                                let last_tile_off = (probe_wg * cand_sg - 1) * ctb;
                                if p_sl_d[last_tile_off..last_tile_off + (kc.bytes as usize)].iter().any(|&b| b != 0xCD) {
                                    actual_sg_per_wg = cand_sg;
                                    break;
                                }
                            }
                            let written_tiles = probe_wg * actual_sg_per_wg;
                            let target_elems = (written_tiles as u32) * tile.m_size * tile.n_size;
                            let (matched, got0, exp0) = coop_verify_output(
                                tile, &rec, ka, kb, kc, written_tiles, rbc, ctb, p_sl_d,
                            );

                            if matched == target_elems && target_elems > 0 {
                                tune_badges.push(format!(
                                    "{}:{}x{}x{}({}->{},SG={}/{},ptr={},colB={},{}xMMA)",
                                    fam_tag, tile.m_size, tile.n_size, tile.k_size,
                                    vk_comp_type_short(tile.a_type), vk_comp_type_short(tile.result_type),
                                    rec.local_sz / (actual_sg_per_wg as u32), rec.local_sz,
                                    if rec.u32_ptrs { if rec.stride_scalars { "u32_sc" } else { "u32" } } else { "scalar" },
                                    if rec.b_col_major { 1 } else { 0 },
                                    rec.mma_total
                                ));
                                return Some((*tile, rec, actual_sg_per_wg as u32));
                            } else if best_diag.is_empty() {
                                best_diag = format!(
                                    "{}:{}x{}x{}({}/{},got0={},exp0={})",
                                    fam_tag, tile.m_size, tile.n_size, tile.k_size, matched, target_elems, got0, exp0
                                );
                            }
                        }
                    }
                    if !best_diag.is_empty() {
                        tune_badges.push(format!("diag[{}]", best_diag));
                    }
                    None
                };

                let mut verified_jobs: Vec<(&str, VkCooperativeMatrixPropertiesKHR, CoopRecipe, u32)> = Vec::new();
                if filt != "coop_fp16" && !int_cands.is_empty() {
                    if let Some((t_win, r_win, sg_per_wg)) = calibrate_family(&int_cands, "INT8") {
                        verified_jobs.push(("K8_COOPMAT_INT8", t_win, r_win, sg_per_wg));
                    }
                }
                if filt != "coop_int8" && !fp_cands.is_empty() {
                    if let Some((t_win, r_win, sg_per_wg)) = calibrate_family(&fp_cands, "FP16") {
                        let k_lbl = if verified_jobs.is_empty() { "K8_COOPMAT_FP16" } else { "K9_COOPMAT_FP16" };
                        verified_jobs.push((k_lbl, t_win, r_win, sg_per_wg));
                    }
                }
                coop_tune_note = tune_badges.join(" | ");

                // Now run full 131,072-element timed Tensor-Core benchmark on each 100%-verified winner!
                for (k_name, tile, rec, sg_per_wg) in verified_jobs {
                    let (ka, kb, kc) = match (coop_scalar_spec(tile.a_type), coop_scalar_spec(tile.b_type), coop_scalar_spec(tile.c_type)) {
                        (Some(a), Some(b), Some(c)) => (a, b, c),
                        _ => continue,
                    };
                    let (compiled_smod, compiled_pipe) = compile_coop_pipe(&tile, &rec);
                    if compiled_pipe == 0 { continue; }

                    let mn = (tile.m_size * tile.n_size).max(1);
                    let raw_tiles = (131_072u32 / mn).clamp(64, 2048);
                    let num_wg = (raw_tiles / sg_per_wg.max(1)).max(1);
                    let num_tiles = num_wg * sg_per_wg.max(1);
                    let total_out_elems = num_tiles * mn;

                    let row_bytes_a = ((tile.k_size * ka.bytes + 15) / 16) * 16;
                    let lead_b = if rec.b_col_major { tile.k_size } else { tile.n_size };
                    let out_b  = if rec.b_col_major { tile.n_size } else { tile.k_size };
                    let row_bytes_b = ((lead_b * kb.bytes + 15) / 16) * 16;
                    let row_bytes_c = ((tile.n_size * kc.bytes + 15) / 16) * 16;

                    let bytes_a = (2 * (num_tiles as usize) * (tile.m_size as usize) * (row_bytes_a as usize)) as u64;
                    let bytes_b = (2 * (num_tiles as usize) * (out_b as usize) * (row_bytes_b as usize)) as u64;
                    let bytes_c = ((num_tiles as usize) * (tile.m_size as usize) * (row_bytes_c as usize)) as u64;
                    let bytes_d = bytes_c;

                    let (ba, ma, pa) = mk_buf(bytes_a);
                    let (bb, mb, pb) = mk_buf(bytes_b);
                    let (bc, mc, pc_ptr) = mk_buf(bytes_c);
                    let (bd, md, pd_ptr) = mk_buf(bytes_d);

                    if !pa.is_null() && !pb.is_null() && !pc_ptr.is_null() && !pd_ptr.is_null() {
                        let sl_a = core::slice::from_raw_parts_mut(pa, bytes_a as usize);
                        let sl_b = core::slice::from_raw_parts_mut(pb, bytes_b as usize);
                        let sl_c = core::slice::from_raw_parts_mut(pc_ptr, bytes_c as usize);
                        let sl_d = core::slice::from_raw_parts_mut(pd_ptr, bytes_d as usize);

                        let (_rba, _rbb, rbc, _atb, _btb, ctb) = coop_fill_buffers(
                            &tile, &rec, ka, kb, kc, num_tiles as usize, sl_a, sl_b, sl_c, sl_d,
                        );

                        let b_dbi0 = VkDescriptorBufferInfo { buffer: ba, offset: 0, range: bytes_a };
                        let b_dbi1 = VkDescriptorBufferInfo { buffer: bb, offset: 0, range: bytes_b };
                        let b_dbi2 = VkDescriptorBufferInfo { buffer: bc, offset: 0, range: bytes_c };
                        let b_dbi3 = VkDescriptorBufferInfo { buffer: bd, offset: 0, range: bytes_d };
                        let writes4 = [
                            VkWriteDescriptorSet { s_type: 35, p_next: null(), dst_set: dset4, dst_binding: 0, dst_array_element: 0, descriptor_count: 1, descriptor_type: 7, p_image_info: null(), p_buffer_info: &b_dbi0, p_texel_buffer_view: null() },
                            VkWriteDescriptorSet { s_type: 35, p_next: null(), dst_set: dset4, dst_binding: 1, dst_array_element: 0, descriptor_count: 1, descriptor_type: 7, p_image_info: null(), p_buffer_info: &b_dbi1, p_texel_buffer_view: null() },
                            VkWriteDescriptorSet { s_type: 35, p_next: null(), dst_set: dset4, dst_binding: 2, dst_array_element: 0, descriptor_count: 1, descriptor_type: 7, p_image_info: null(), p_buffer_info: &b_dbi2, p_texel_buffer_view: null() },
                            VkWriteDescriptorSet { s_type: 35, p_next: null(), dst_set: dset4, dst_binding: 3, dst_array_element: 0, descriptor_count: 1, descriptor_type: 7, p_image_info: null(), p_buffer_info: &b_dbi3, p_texel_buffer_view: null() },
                        ];
                        vk_update_dsets(dev, 4, writes4.as_ptr(), 0, null());

                        let coop_passes: u32 = if rec.mma_total <= 1 { 64 } else { 16 };
                        let cbbi = VkCommandBufferBeginInfo { s_type: 42, p_next: null(), flags: 0, p_inheritance_info: null() };
                        let _ = vk_begin_cbuf(cmd, &cbbi);
                        vk_cmd_bind_pipe(cmd, 1, compiled_pipe);
                        vk_cmd_bind_dsets(cmd, 1, playout4, 0, 1, &dset4, 0, null());
                        for _ in 0..coop_passes {
                            vk_cmd_dispatch(cmd, num_wg, 1, 1);
                        }
                        let _ = vk_end_cbuf(cmd);

                        let si = VkSubmitInfo {
                            s_type: 4, p_next: null(), wait_semaphore_count: 0, p_wait_semaphores: null(), p_wait_dst_stage_mask: null(),
                            command_buffer_count: 1, p_command_buffers: &cmd, signal_semaphore_count: 0, p_signal_semaphores: null(),
                        };

                        let _ = vk_queue_submit(queue, 1, &si, 0);
                        let _ = vk_queue_wait_idle(queue);

                        let t0 = Instant::now();
                        let _ = vk_queue_submit(queue, 1, &si, 0);
                        let _ = vk_queue_wait_idle(queue);
                        let el_s = t0.elapsed().as_secs_f64().max(1e-7);

                        let (matched, _g0, _e0) = coop_verify_output(
                            &tile, &rec, ka, kb, kc, num_tiles as usize, rbc, ctb, sl_d,
                        );

                        let ops_per_dispatch = (num_tiles as f64) * (rec.mma_total as f64) * 2.0 * (tile.m_size as f64) * (tile.n_size as f64) * (tile.k_size as f64);
                        let total_ops = ops_per_dispatch * (coop_passes as f64);
                        let gops_s = total_ops / el_s / 1e9;
                        let melem_s = ((total_out_elems as f64) * (coop_passes as f64)) / el_s / 1e6;
                        let hw_sg = rec.local_sz / sg_per_wg.max(1);
                        let tile_sig = format!(
                            "{}x{}x{} {}->{}",
                            tile.m_size, tile.n_size, tile.k_size,
                            vk_comp_type_short(tile.a_type), vk_comp_type_short(tile.result_type)
                        );
                        let detail = if gops_s >= 1000.0 {
                            format!("{} ({:.2} TOPS/s, SG={})", tile_sig, gops_s / 1000.0, hw_sg)
                        } else {
                            format!("{} ({}xMMA, SG={})", tile_sig, rec.mma_total, hw_sg)
                        };

                        scores.push(KernelScore {
                            id: k_name.to_string(),
                            elements: total_out_elems,
                            matched,
                            dispatches: coop_passes,
                            elapsed_ms: el_s * 1000.0,
                            melem_per_sec: melem_s,
                            gops_per_sec: gops_s,
                            detail,
                        });
                    }

                    for (bf, mm, pv) in [(ba, ma, pa), (bb, mb, pb), (bc, mc, pc_ptr), (bd, md, pd_ptr)] {
                        if !pv.is_null() { vk_unmap_mem(dev, mm); }
                        if mm != 0 { vk_free_mem(dev, mm, null()); }
                        if bf != 0 { vk_destroy_buf(dev, bf, null()); }
                    }
                    vk_destroy_pipe(dev, compiled_pipe, null());
                    vk_destroy_shader(dev, compiled_smod, null());
                }
            }

            for (bf, mm, pv) in [(p_ba, p_ma, p_pa), (p_bb, p_mb, p_pb), (p_bc, p_mc, p_pc), (p_bd, p_md, p_pd)] {
                if !pv.is_null() { vk_unmap_mem(dev, mm); }
                if mm != 0 { vk_free_mem(dev, mm, null()); }
                if bf != 0 { vk_destroy_buf(dev, bf, null()); }
            }
            vk_destroy_dpool(dev, dpool4, null());
            vk_destroy_pipe_layout(dev, playout4, null());
            vk_destroy_dsl(dev, dsl4, null());
        }

        if let Some(k10_sc) = pending_k10_score {
            scores.push(k10_sc);
        }

        vk_destroy_cpool(dev, cpool, null());
        vk_destroy_dev(dev, null());
        vk_destroy_instance(instance, null());

        let note = format!("{}-Kernel Subgroup/IntDot/UDot/CoopMat Suite OK", scores.len());
        VulkanSuiteReport {
            available: true,
            device_name: dev_name,
            api_version: api_str,
            vendor_hex,
            subgroup_size: sg_props.subgroup_size,
            subgroup_min: sg_min,
            subgroup_max: sg_max,
            subgroup_ops_hex: format!("0x{:X}", sg_props.supported_operations),
            uma_heap_mb,
            ext_total,
            ext_badges,
            intdot_hw_accel,
            idot_mask_hex,
            idot_tune_note,
            udot_tune_note,
            coop_tiles: coop_tiles_desc,
            coop_tune_note,
            kernels: scores,
            note,
        }
    }
}

// =============================================================================
// 7. UNIFIED BENCHMARK, JSON SERIALIZER & :19788 MULTI-KERNEL TENSOR DAEMON
// =============================================================================


// =============================================================================
// TENSOR G5 4TH-GEN NPU / EDGETPU ("LAGUNA" / "36500000.buenos") v0.7.5
//   1. Zero-Copy memfd_create + ANeuralNetworksMemory_createFromFd DMA Pool
//   2. 16-Layer Fused On-Chip SRAM Systolic Chains (8.59 GOPS/call CONV2D Q8,
//      4.29 GOPS/call FC Q8, 1.07 GOPS/call FC FP16 -- 100% Non-Zero Dense MACs)
//   3. Live /sys/class/edgetpu/buenos + /vendor/lib64/libedgetpu_litert.so X-Ray
// =============================================================================

const NNAPI_NO_ERROR: i32 = 0;
const NNAPI_INT32: i32 = 1;
const NNAPI_TENSOR_FLOAT32: i32 = 3;
const NNAPI_TENSOR_INT32: i32 = 4;
const NNAPI_TENSOR_QUANT8_ASYMM: i32 = 5;
const NNAPI_TENSOR_FLOAT16: i32 = 8;

const NNAPI_OP_ADD: i32 = 0;
const NNAPI_OP_CONV_2D: i32 = 3;
const NNAPI_OP_FULLY_CONNECTED: i32 = 9;

const NNAPI_FUSED_NONE: i32 = 0;
const NNAPI_PADDING_VALID: i32 = 2;
const NNAPI_PREFER_SUSTAINED_SPEED: i32 = 2;

const NNAPI_DEVICE_CPU: i32 = 2;
const NNAPI_DEVICE_GPU: i32 = 3;
const NNAPI_DEVICE_ACCELERATOR: i32 = 4;

const NNAPI_DURATION_ON_HARDWARE: i32 = 0;
const NNAPI_DURATION_IN_DRIVER: i32 = 1;

const TPU_FUSED_LAYERS: usize = 16;

#[repr(C)]
#[derive(Copy, Clone)]
struct NnapiOperandType {
    operand_type: i32,
    dimension_count: u32,
    dimensions: *const u32,
    scale: f32,
    zero_point: i32,
}

#[derive(Clone)]
struct TpuKernelNode {
    path: String,
    exists: bool,
    perms: String,
    open_status: String,
}

#[derive(Clone)]
struct TpuVendorLibInfo {
    path: String,
    exists: bool,
    size_kb: u64,
    public_whitelisted: bool,
    dlopen_ok: bool,
    dlopen_note: String,
    exported_syms: Vec<String>,
}

#[derive(Clone)]
struct NnapiDeviceDesc {
    index: u32,
    name: String,
    version: String,
    dev_type: i32,
    type_label: String,
    feature_level: i64,
    ops_supported: String,
}

#[derive(Clone)]
struct TpuGraphBenchRow {
    kernel_id: String,
    device_name: String,
    device_type: i32,
    is_hw_tpu: bool,
    supported: bool,
    compile_rc: i32,
    exec_rc: i32,
    matched: u32,
    elements: u32,
    burst_iters: u32,
    elapsed_ms: f64,
    hw_us: f64,
    drv_us: f64,
    melem_per_sec: f64,
    gops_per_sec: f64,
    hw_on_die_gops: f64,
    detail: String,
}

#[derive(Clone)]
struct TpuNpuReport {
    nnapi_loaded: bool,
    nnapi_loader_note: String,
    hw_tpu_enumerated: bool,
    hw_tpu_unlocked: bool,
    zero_copy_memfd_active: bool,
    tpu_device_name: String,
    soc_props: String,
    thermal_and_freq: String,
    buenos_sysfs: String,
    public_vendor_libs: Vec<String>,
    vintf_hals: Vec<String>,
    kernel_nodes: Vec<TpuKernelNode>,
    vendor_libs: Vec<TpuVendorLibInfo>,
    nnapi_devices: Vec<NnapiDeviceDesc>,
    bench_rows: Vec<TpuGraphBenchRow>,
    peak_tpu_gops: f64,
    peak_hw_on_die_gops: f64,
    summary_line: String,
}

#[inline]
fn f32_to_f16_bits(val: f32) -> u16 {
    let bits: u32 = val.to_bits();
    let sign: u16 = ((bits >> 16) & 0x8000) as u16;
    let raw_exp: i32 = ((bits >> 23) & 0xFF) as i32;
    if raw_exp == 0 {
        return sign;
    }
    let exp32: i32 = raw_exp - 127;
    if exp32 > 15 {
        return sign | 0x7C00;
    }
    if exp32 < -14 {
        return sign;
    }
    let exp16: u16 = ((exp32 + 15) as u16) & 0x1F;
    let mant16: u16 = ((bits & 0x007F_FFFF) >> 13) as u16;
    sign | (exp16 << 10) | mant16
}

fn f32_to_f16_exact_pow2(val: f32) -> u16 {
    if val == 0.0 {
        return 0x0000;
    }
    if val == 0.125 {
        return 0x3000; // +2^-3 exact in IEEE-754 binary16
    }
    if val == -0.125 {
        return 0xB000; // -2^-3 exact in IEEE-754 binary16
    }
    i32_to_f16_exact(val as i32)
}

fn f16_to_f32_exact(h: u16) -> f32 {
    let sign = ((h >> 15) & 1) as u32;
    let exp = ((h >> 10) & 0x1F) as u32;
    let mant = (h & 0x03FF) as u32;
    let bits: u32 = if exp == 0 {
        if mant == 0 {
            sign << 31
        } else {
            let mut m = mant;
            let mut e: i32 = -14;
            while (m & 0x0400) == 0 {
                m <<= 1;
                e -= 1;
            }
            m &= 0x03FF;
            let f_exp = ((e + 127) as u32) & 0xFF;
            (sign << 31) | (f_exp << 23) | (m << 13)
        }
    } else if exp == 31 {
        (sign << 31) | (0xFF << 23) | (mant << 13)
    } else {
        let f_exp = exp + (127 - 15);
        (sign << 31) | (f_exp << 23) | (mant << 13)
    };
    f32::from_bits(bits)
}

unsafe fn cstr_ptr_to_string(ptr: *const u8, max_len: usize) -> String {
    if ptr.is_null() {
        return String::new();
    }
    let mut len = 0usize;
    while len < max_len {
        if *ptr.add(len) == 0 {
            break;
        }
        len += 1;
    }
    String::from_utf8_lossy(core::slice::from_raw_parts(ptr, len)).into_owned()
}

fn nnapi_rc_name(rc: i32) -> &'static str {
    match rc {
        0 => "NO_ERROR(0)",
        1 => "OUT_OF_MEMORY(1)",
        2 => "INCOMPLETE(2)",
        3 => "UNEXPECTED_NULL(3)",
        4 => "BAD_DATA(4)",
        5 => "OP_FAILED(5)",
        6 => "BAD_STATE(6)",
        7 => "UNMAPPABLE(7)",
        8 => "OUTPUT_INSUFFICIENT_SIZE(8)",
        9 => "UNAVAILABLE_DEVICE(9)",
        10 => "MISSED_DEADLINE_TRANSIENT(10)",
        11 => "MISSED_DEADLINE_PERSISTENT(11)",
        12 => "RESOURCE_EXHAUSTED_TRANSIENT(12)",
        13 => "RESOURCE_EXHAUSTED_PERSISTENT(13)",
        14 => "DEAD_OBJECT(14)",
        -1 => "NOT_RUN(compile_err)",
        -2 => "MODEL_BUILD_ERR",
        _ => "VENDOR_ERR",
    }
}

fn nnapi_dev_type_label(dt: i32) -> &'static str {
    match dt {
        4 => "ACCELERATOR_TPU",
        3 => "GPU",
        2 => "CPU",
        1 => "OTHER_HW",
        _ => "UNKNOWN",
    }
}

fn is_tpu_like_device(name: &str, dev_type: i32) -> bool {
    if dev_type == NNAPI_DEVICE_CPU {
        return false;
    }
    if dev_type == NNAPI_DEVICE_ACCELERATOR {
        return true;
    }
    let low = name.to_ascii_lowercase();
    low.contains("tpu")
        || low.contains("edgetpu")
        || low.contains("darwinn")
        || low.contains("buenos")
        || low.contains("laguna")
        || low.contains("tensor")
        || low.contains("npu")
        || low.contains("gxp")
        || low.contains("neuron")
}

fn read_android_prop_dyn(prop_nul: &[u8]) -> String {
    #[cfg(all(target_os = "android", not(target_env = "musl")))]
    unsafe {
        let mut h = CACHED_LIBC_HANDLE.load(Ordering::Acquire) as *mut c_void;
        if h.is_null() {
            h = dlopen(b"libc.so\0".as_ptr(), 2);
            if !h.is_null() { CACHED_LIBC_HANDLE.store(h as usize, Ordering::Release); }
        }
        if h.is_null() {
            return String::new();
        }
        let sym = dlsym(h, b"__system_property_get\0".as_ptr());
        let mut out = String::new();
        if !sym.is_null() {
            type FnSysPropGet = unsafe extern "C" fn(*const u8, *mut u8) -> i32;
            let f: FnSysPropGet = core::mem::transmute(sym);
            let mut buf = [0u8; 128];
            let n = f(prop_nul.as_ptr(), buf.as_mut_ptr());
            if n > 0 {
                let len = (n as usize).min(127);
                out = String::from_utf8_lossy(&buf[..len]).trim().to_string();
            }
        }
        let _ = h; // keep .so mapped (TLS/atexit safe)
        return out;
    }
    #[cfg(not(all(target_os = "android", not(target_env = "musl"))))]
    {
        let _ = prop_nul;
        String::new()
    }
}

#[cfg(unix)]
fn format_unix_perms_and_uid(path: &str) -> (String, u32) {
    use std::os::unix::fs::MetadataExt;
    match fs::metadata(path) {
        Ok(m) => (format!("0o{:o} uid={} gid={}", m.mode() & 0o7777, m.uid(), m.gid()), m.uid()),
        Err(_) => ("stat_denied".to_string(), 0),
    }
}

#[cfg(not(unix))]
fn format_unix_perms_and_uid(_path: &str) -> (String, u32) {
    ("win_host".to_string(), 0)
}

fn test_node_open_access(path: &str, owner_uid: u32) -> String {
    if fs::metadata(path).map(|m| m.is_dir()).unwrap_or(false) {
        return match fs::read_dir(path) {
            Ok(rd) => {
                let mut entries: Vec<String> = Vec::new();
                for e in rd.flatten() {
                    if entries.len() < 6 {
                        entries.push(e.file_name().to_string_lossy().into_owned());
                    }
                }
                format!("DIR_READ_OK({})", entries.join(","))
            }
            Err(e) => format!("DIR_ERR({})", e.raw_os_error().unwrap_or(-1)),
        };
    }
    match fs::OpenOptions::new().read(true).write(true).open(path) {
        Ok(_f) => "OPEN_RDWR_OK".to_string(),
        Err(e_rw) => match fs::OpenOptions::new().read(true).open(path) {
            Ok(_f2) => "OPEN_RDONLY_OK".to_string(),
            Err(e_ro) => {
                let code = e_rw.raw_os_error().or(e_ro.raw_os_error()).unwrap_or(-1);
                if code == 13 && (owner_uid == 1000 || owner_uid == 0) && path.starts_with("/dev/") {
                    return "HAL_DAEMON_OWNED(via Binder IDevice/google-edgetpu)".to_string();
                }
                let tag = match code {
                    1 => "EPERM",
                    2 => "ENOENT",
                    13 => "EACCES",
                    16 => "EBUSY",
                    19 => "ENODEV",
                    _ => "ERR",
                };
                format!("{}({})", tag, code)
            }
        },
    }
}

fn read_buenos_sysfs_details() -> String {
    let mut items: Vec<String> = Vec::new();
    for dir_p in [
        "/sys/class/edgetpu/buenos",
        "/sys/class/edgetpu/edgetpu-soc",
        "/sys/class/devfreq/36500000.buenos",
        "/sys/class/devfreq/38880000.gxp",
    ] {
        if let Ok(rd) = fs::read_dir(dir_p) {
            let tag = dir_p.rsplit('/').next().unwrap_or(dir_p);
            let mut sub: Vec<String> = Vec::new();
            for ent in rd.flatten() {
                let fnm = ent.file_name().to_string_lossy().into_owned();
                if fnm == "uevent" || fnm == "subsystem" || fnm == "device" || fnm == "power" {
                    continue;
                }
                if let Ok(m) = ent.metadata() {
                    if m.is_file() {
                        if let Ok(txt) = fs::read_to_string(ent.path()) {
                            let val = txt.lines().next().unwrap_or("").trim();
                            if !val.is_empty() && val.len() <= 48 && sub.len() < 5 {
                                sub.push(format!("{}={}", fnm, val));
                            }
                        }
                    }
                }
            }
            if !sub.is_empty() {
                items.push(format!("{}[{}]", tag, sub.join(", ")));
            }
        }
    }
    if items.is_empty() {
        "sysfs_edgetpu_attrs=hal_protected".to_string()
    } else {
        items.join(" | ")
    }
}

fn probe_tpu_kernel_and_sysfs() -> (String, String, String, Vec<TpuKernelNode>) {
    let mut props: Vec<String> = Vec::new();
    let prop_keys: [(&str, &[u8]); 11] = [
        ("soc", b"ro.soc.model\0"),
        ("mfg", b"ro.soc.manufacturer\0"),
        ("board", b"ro.board.platform\0"),
        ("hw", b"ro.hardware\0"),
        ("rel", b"ro.build.version.release\0"),
        ("sdk", b"ro.build.version.sdk\0"),
        ("build", b"ro.build.id\0"),
        ("qpr", b"ro.build.display.id\0"),
        ("patch", b"ro.build.version.security_patch\0"),
        ("egl", b"ro.hardware.egl\0"),
        ("tpu_ver", b"ro.vendor.edgetpu.version\0"),
    ];
    for (k, raw_k) in prop_keys {
        let v = read_android_prop_dyn(raw_k);
        if !v.is_empty() {
            props.push(format!("{}={}", k, v));
        }
    }
    if props.is_empty() {
        if cfg!(target_os = "windows") {
            props.push("host=windows_x64".to_string());
        } else if cfg!(all(target_os = "linux", target_arch = "aarch64")) {
            props.push("guest=avf_debian13_pkvm".to_string());
        }
    }

    let cand_paths: [&str; 6] = [
        "/sys/class/edgetpu",
        "/dev/edgetpu-soc",
        "/dev/buenos",
        "/dev/edgetpu",
        "/dev/gxp",
        "/dev/aoc",
    ];
    let mut nodes: Vec<TpuKernelNode> = Vec::new();
    for p in cand_paths {
        let ex = fs::metadata(p).is_ok() || fs::symlink_metadata(p).is_ok();
        if ex {
            let (perms, uid) = format_unix_perms_and_uid(p);
            let open_st = test_node_open_access(p, uid);
            nodes.push(TpuKernelNode {
                path: p.to_string(),
                exists: true,
                perms,
                open_status: open_st,
            });
        }
    }

    let mut tf_items: Vec<String> = Vec::new();
    if let Ok(rd) = fs::read_dir("/sys/class/thermal") {
        for ent in rd.flatten() {
            let p = ent.path();
            let tname = fs::read_to_string(p.join("type")).unwrap_or_default().trim().to_string();
            let low = tname.to_ascii_lowercase();
            if low.contains("tpu") || low.contains("npu") || low.contains("buenos") || low.contains("gxp") || low.contains("soc") {
                if let Ok(raw_t) = fs::read_to_string(p.join("temp")) {
                    if let Ok(mv) = raw_t.trim().parse::<i64>() {
                        let deg = if mv > 1000 { (mv as f64) / 1000.0 } else { mv as f64 };
                        if tf_items.len() < 5 {
                            tf_items.push(format!("{}={:.1}C", tname, deg));
                        }
                    }
                }
            }
        }
    }
    if let Ok(rd) = fs::read_dir("/sys/class/devfreq") {
        for ent in rd.flatten() {
            let nm = ent.file_name().to_string_lossy().into_owned();
            let low = nm.to_ascii_lowercase();
            if low.contains("tpu") || low.contains("buenos") || low.contains("gxp") || low.contains("npu") {
                let cur = fs::read_to_string(ent.path().join("cur_freq")).unwrap_or_default().trim().to_string();
                let max = fs::read_to_string(ent.path().join("max_freq")).unwrap_or_default().trim().to_string();
                if !cur.is_empty() || !max.is_empty() {
                    tf_items.push(format!("devfreq[{}]={}/{}", nm, cur, max));
                } else {
                    tf_items.push(format!("mmio_devfreq[{}]=ACTIVE", nm));
                }
            }
        }
    }
    let tf_str = if tf_items.is_empty() {
        "host_or_vm_mode".to_string()
    } else {
        tf_items.join(" | ")
    };
    let buenos_sysfs = read_buenos_sysfs_details();

    (props.join(", "), tf_str, buenos_sysfs, nodes)
}

fn read_u16_le(buf: &[u8], off: usize) -> Option<u16> {
    let s = buf.get(off..off + 2)?;
    Some(u16::from_le_bytes([s[0], s[1]]))
}

fn read_u32_le(buf: &[u8], off: usize) -> Option<u32> {
    let s = buf.get(off..off + 4)?;
    Some(u32::from_le_bytes([s[0], s[1], s[2], s[3]]))
}

fn read_u64_le(buf: &[u8], off: usize) -> Option<u64> {
    let s = buf.get(off..off + 8)?;
    Some(u64::from_le_bytes([s[0], s[1], s[2], s[3], s[4], s[5], s[6], s[7]]))
}

fn scan_elf64_tpu_symbols(path: &str) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    let meta = match fs::metadata(path) {
        Ok(m) => m,
        Err(_) => return out,
    };
    if !meta.is_file() || meta.len() < 64 || meta.len() > 32 * 1024 * 1024 {
        return out;
    }
    let buf = match fs::read(path) {
        Ok(b) => b,
        Err(_) => return out,
    };
    if buf.get(0..4) != Some(b"\x7fELF") || buf.get(4) != Some(&2u8) || buf.get(5) != Some(&1u8) {
        return out;
    }
    let shoff = match read_u64_le(&buf, 0x28) {
        Some(v) if v > 0 => v as usize,
        _ => return out,
    };
    let shentsize = match read_u16_le(&buf, 0x3A) {
        Some(v) if v >= 64 => v as usize,
        _ => return out,
    };
    let shnum = match read_u16_le(&buf, 0x3C) {
        Some(v) if v > 0 && v <= 1024 => v as usize,
        _ => return out,
    };
    for i in 0..shnum {
        let sh = match shoff.checked_add(i.saturating_mul(shentsize)) {
            Some(v) => v,
            None => break,
        };
        if read_u32_le(&buf, sh + 0x04) != Some(11) {
            continue;
        }
        let sym_off = read_u64_le(&buf, sh + 0x18).unwrap_or(0) as usize;
        let sym_sz = read_u64_le(&buf, sh + 0x20).unwrap_or(0) as usize;
        let str_idx = read_u32_le(&buf, sh + 0x28).unwrap_or(0) as usize;
        let ent_sz_raw = read_u64_le(&buf, sh + 0x38).unwrap_or(24) as usize;
        let ent_sz = if ent_sz_raw >= 24 { ent_sz_raw } else { 24 };
        if str_idx >= shnum {
            continue;
        }
        let str_sh = shoff + str_idx * shentsize;
        let str_off = read_u64_le(&buf, str_sh + 0x18).unwrap_or(0) as usize;
        let str_sz = read_u64_le(&buf, str_sh + 0x20).unwrap_or(0) as usize;
        let strtab = match buf.get(str_off..str_off.saturating_add(str_sz)) {
            Some(s) => s,
            None => continue,
        };
        let symtab = match buf.get(sym_off..sym_off.saturating_add(sym_sz)) {
            Some(s) => s,
            None => continue,
        };
        let count = symtab.len() / ent_sz;
        for s_idx in 0..count {
            let base = s_idx * ent_sz;
            let st_name = read_u32_le(symtab, base).unwrap_or(0) as usize;
            let st_info = *symtab.get(base + 4).unwrap_or(&0);
            let st_shndx = read_u16_le(symtab, base + 6).unwrap_or(0);
            let bind = st_info >> 4;
            if st_name == 0 || st_shndx == 0 || (bind != 1 && bind != 2) || st_name >= strtab.len() {
                continue;
            }
            let tail = &strtab[st_name..];
            let mut nlen = 0usize;
            while nlen < tail.len() && nlen < 160 && tail[nlen] != 0 {
                nlen += 1;
            }
            if nlen < 4 {
                continue;
            }
            let sym_name = String::from_utf8_lossy(&tail[..nlen]).into_owned();
            let low = sym_name.to_ascii_lowercase();
            if low.contains("litert")
                || low.contains("edgetpu")
                || low.contains("darwinn")
                || low.contains("tachyon")
                || low.contains("tensor")
                || low.contains("aneuralnetworks_")
                || low.contains("dispatch")
                || low.contains("tpu")
            {
                if !out.contains(&sym_name) {
                    out.push(sym_name);
                    if out.len() >= 12 {
                        return out;
                    }
                }
            }
        }
    }
    out
}

fn try_dlopen_probe(path: &str) -> (bool, String) {
    #[cfg(all(any(target_os = "android", target_os = "linux"), not(target_env = "musl")))]
    unsafe {
        let _ = dlerror();
        let mut cpath = Vec::with_capacity(path.len() + 1);
        cpath.extend_from_slice(path.as_bytes());
        cpath.push(0);
        let h = dlopen(cpath.as_ptr(), 1);
        if !h.is_null() {
            let _ = h; // keep .so mapped (TLS/atexit safe)
            return (true, "DLOPEN_OK".to_string());
        }
        let err_s = cstr_ptr_to_string(dlerror(), 220);
        if err_s.is_empty() {
            return (false, "dlopen_null".to_string());
        }
        return (false, err_s);
    }
    #[cfg(not(all(any(target_os = "android", target_os = "linux"), not(target_env = "musl"))))]
    {
        let _ = path;
        (false, "non_dl_target".to_string())
    }
}

fn probe_vendor_tpu_libraries() -> (Vec<String>, Vec<String>, Vec<TpuVendorLibInfo>) {
    let mut pub_libs: Vec<String> = Vec::new();
    for pub_file in [
        "/vendor/etc/public.libraries.txt",
        "/vendor/etc/public.libraries-google.txt",
        "/system/etc/public.libraries.txt",
    ] {
        if let Ok(txt) = fs::read_to_string(pub_file) {
            for ln in txt.lines() {
                let t = ln.trim();
                if t.is_empty() || t.starts_with('#') {
                    continue;
                }
                let tok = t.split_whitespace().next().unwrap_or("").to_string();
                if !tok.is_empty() && !pub_libs.contains(&tok) {
                    pub_libs.push(tok);
                }
            }
        }
    }

    let mut vintf_hals: Vec<String> = Vec::new();
    let mut manifest_files: Vec<String> = vec![
        "/vendor/etc/vintf/manifest.xml".to_string(),
        "/system/etc/vintf/manifest.xml".to_string(),
    ];
    if let Ok(rd) = fs::read_dir("/vendor/etc/vintf/manifest") {
        for ent in rd.flatten() {
            manifest_files.push(ent.path().to_string_lossy().into_owned());
        }
    }
    for mf in manifest_files {
        if let Ok(xml) = fs::read_to_string(&mf) {
            for ln in xml.lines() {
                let low = ln.to_ascii_lowercase();
                if low.contains("edgetpu") || low.contains("neuralnetworks") || low.contains("darwinn") || low.contains("buenos") {
                    let clean = ln.trim().replace('<', "[").replace('>', "]");
                    if !clean.is_empty() && !vintf_hals.contains(&clean) && vintf_hals.len() < 10 {
                        vintf_hals.push(clean);
                    }
                }
            }
        }
    }

    let mut target_libs: Vec<String> = vec![
        "/apex/com.android.neuralnetworks/lib64/libneuralnetworks.so".to_string(),
        "/vendor/lib64/libedgetpu_litert.so".to_string(),
        "/vendor/lib64/libedgetpu_client.google.so".to_string(),
        "/vendor/lib64/libedgetpu_util.so".to_string(),
        "/vendor/lib64/com.google.edgetpu_app_service-V11-ndk.so".to_string(),
        "/vendor/lib64/com.google.edgetpu_vendor_service-V2-ndk.so".to_string(),
    ];
    for scan_dir in ["/vendor/lib64"] {
        if let Ok(rd) = fs::read_dir(scan_dir) {
            for ent in rd.flatten() {
                let nm = ent.file_name().to_string_lossy().into_owned();
                let low = nm.to_ascii_lowercase();
                if low.contains("edgetpu") || low.contains("litert") || low.contains("darwinn") {
                    let full = format!("{}/{}", scan_dir, nm);
                    if !target_libs.contains(&full) && target_libs.len() < 12 {
                        target_libs.push(full);
                    }
                }
            }
        }
    }

    let mut out_libs: Vec<TpuVendorLibInfo> = Vec::new();
    for p in target_libs {
        let base_nm = p.rsplit('/').next().unwrap_or(&p).to_string();
        let whitelisted = pub_libs.iter().any(|x| x == &base_nm);
        if let Ok(m) = fs::metadata(&p) {
            let sz_kb = (m.len() + 512) / 1024;
            let (dl_ok, dl_note) = if p.ends_with(".so") {
                let (ok1, n1) = try_dlopen_probe(&base_nm);
                if ok1 {
                    (true, format!("{} (soname)", n1))
                } else {
                    try_dlopen_probe(&p)
                }
            } else {
                (false, "exec_bin".to_string())
            };
            let syms = scan_elf64_tpu_symbols(&p);
            out_libs.push(TpuVendorLibInfo {
                path: p,
                exists: true,
                size_kb: sz_kb,
                public_whitelisted: whitelisted,
                dlopen_ok: dl_ok,
                dlopen_note: dl_note,
                exported_syms: syms,
            });
        }
    }

    let filtered_pub: Vec<String> = pub_libs
        .into_iter()
        .filter(|s| {
            let l = s.to_ascii_lowercase();
            l.contains("neural") || l.contains("tpu") || l.contains("litert") || l.contains("vulkan") || l.contains("edgetpu")
        })
        .collect();

    (filtered_pub, vintf_hals, out_libs)
}

// =============================================================================
// 3-TIER HARDWARE TPU DMA ENGINE (Driver MemoryDesc -> Android Ashmem -> NNAPI Burst)
// + 1.00 MB ON-CHIP SRAM SYSTOLIC CHAINS WITH [16, 8, 4, 1] AUTO-DEPTH CASCADE
// =============================================================================
struct AshmemNnapiPool {
    fd: i32,
    map_ptr: *mut u8,
    map_len: usize,
    nn_mem: *mut c_void,
    libc_handle: *mut c_void,
    android_handle: *mut c_void,
    fn_munmap: Option<unsafe extern "C" fn(*mut c_void, usize) -> i32>,
    fn_close: Option<unsafe extern "C" fn(i32) -> i32>,
    fn_nn_mem_free: Option<unsafe extern "C" fn(*mut c_void)>,
}

impl Drop for AshmemNnapiPool {
    fn drop(&mut self) {
        unsafe {
            if !self.nn_mem.is_null() {
                if let Some(mf) = self.fn_nn_mem_free {
                    mf(self.nn_mem);
                }
            }
            if !self.map_ptr.is_null() && self.map_len > 0 {
                if let Some(mu) = self.fn_munmap {
                    let _ = mu(self.map_ptr as *mut c_void, self.map_len);
                }
            }
            if self.fd >= 0 {
                if let Some(cl) = self.fn_close {
                    let _ = cl(self.fd);
                }
            }
            // Keep libc.so and libandroid.so handles resident (zero TLS destructor race across threads)
            let _ = (self.android_handle, self.libc_handle);
        }
    }
}

struct DriverDeviceMem {
    nn_mem: *mut c_void,
    fn_nn_mem_free: Option<unsafe extern "C" fn(*mut c_void)>,
}

impl Drop for DriverDeviceMem {
    fn drop(&mut self) {
        unsafe {
            if !self.nn_mem.is_null() {
                if let Some(mf) = self.fn_nn_mem_free {
                    mf(self.nn_mem);
                }
            }
        }
    }
}

type FnNnGetDeviceCount = unsafe extern "C" fn(*mut u32) -> i32;
type FnNnGetDevice = unsafe extern "C" fn(u32, *mut *mut c_void) -> i32;
type FnNnDevGetName = unsafe extern "C" fn(*const c_void, *mut *const u8) -> i32;
type FnNnDevGetVersion = unsafe extern "C" fn(*const c_void, *mut *const u8) -> i32;
type FnNnDevGetType = unsafe extern "C" fn(*const c_void, *mut i32) -> i32;
type FnNnDevGetFeatureLevel = unsafe extern "C" fn(*const c_void, *mut i64) -> i32;

type FnNnMemCreateFromFd = unsafe extern "C" fn(usize, i32, i32, usize, *mut *mut c_void) -> i32;
type FnNnMemFree = unsafe extern "C" fn(*mut c_void);
type FnNnMemDescCreate = unsafe extern "C" fn(*mut *mut c_void) -> i32;
type FnNnMemDescFree = unsafe extern "C" fn(*mut c_void);
type FnNnMemDescAddRole = unsafe extern "C" fn(*mut c_void, *const c_void, u32, f32) -> i32;
type FnNnMemDescFinish = unsafe extern "C" fn(*mut c_void) -> i32;
type FnNnMemCreateFromDesc = unsafe extern "C" fn(*const c_void, *mut *mut c_void) -> i32;
type FnNnMemCopy = unsafe extern "C" fn(*const c_void, *const c_void) -> i32;

type FnNnModelCreate = unsafe extern "C" fn(*mut *mut c_void) -> i32;
type FnNnModelFree = unsafe extern "C" fn(*mut c_void);
type FnNnModelFinish = unsafe extern "C" fn(*mut c_void) -> i32;
type FnNnModelAddOperand = unsafe extern "C" fn(*mut c_void, *const NnapiOperandType) -> i32;
type FnNnModelSetOperandValue = unsafe extern "C" fn(*mut c_void, i32, *const c_void, usize) -> i32;
type FnNnModelAddOperation = unsafe extern "C" fn(*mut c_void, i32, u32, *const u32, u32, *const u32) -> i32;
type FnNnModelIdentifyIO = unsafe extern "C" fn(*mut c_void, u32, *const u32, u32, *const u32) -> i32;
type FnNnModelGetSupportedOps = unsafe extern "C" fn(*const c_void, *const *const c_void, u32, *mut u8) -> i32;

type FnNnCompCreateForDevices = unsafe extern "C" fn(*const c_void, *const *const c_void, u32, *mut *mut c_void) -> i32;
type FnNnCompSetPreference = unsafe extern "C" fn(*mut c_void, i32) -> i32;
type FnNnCompFinish = unsafe extern "C" fn(*mut c_void) -> i32;
type FnNnCompFree = unsafe extern "C" fn(*mut c_void);

type FnNnBurstCreate = unsafe extern "C" fn(*mut c_void, *mut *mut c_void) -> i32;
type FnNnBurstFree = unsafe extern "C" fn(*mut c_void);

type FnNnExecCreate = unsafe extern "C" fn(*mut c_void, *mut *mut c_void) -> i32;
type FnNnExecSetInput = unsafe extern "C" fn(*mut c_void, i32, *const NnapiOperandType, *const c_void, usize) -> i32;
type FnNnExecSetOutput = unsafe extern "C" fn(*mut c_void, i32, *const NnapiOperandType, *mut c_void, usize) -> i32;
type FnNnExecSetInputFromMem = unsafe extern "C" fn(*mut c_void, i32, *const NnapiOperandType, *const c_void, usize, usize) -> i32;
type FnNnExecSetOutputFromMem = unsafe extern "C" fn(*mut c_void, i32, *const NnapiOperandType, *const c_void, usize, usize) -> i32;
type FnNnExecSetMeasureTiming = unsafe extern "C" fn(*mut c_void, u8) -> i32;
type FnNnExecGetDuration = unsafe extern "C" fn(*const c_void, i32, *mut u64) -> i32;
type FnNnExecCompute = unsafe extern "C" fn(*mut c_void) -> i32;
type FnNnExecBurstCompute = unsafe extern "C" fn(*mut c_void, *mut c_void) -> i32;
type FnNnExecFree = unsafe extern "C" fn(*mut c_void);

struct DynNnapiApi {
    handle: *mut c_void,
    get_device_count: FnNnGetDeviceCount,
    get_device: FnNnGetDevice,
    dev_get_name: FnNnDevGetName,
    dev_get_version: FnNnDevGetVersion,
    dev_get_type: FnNnDevGetType,
    dev_get_feature_level: FnNnDevGetFeatureLevel,
    mem_create_from_fd: Option<FnNnMemCreateFromFd>,
    mem_free: Option<FnNnMemFree>,
    mem_desc_create: Option<FnNnMemDescCreate>,
    mem_desc_free: Option<FnNnMemDescFree>,
    mem_desc_add_input_role: Option<FnNnMemDescAddRole>,
    mem_desc_add_output_role: Option<FnNnMemDescAddRole>,
    mem_desc_finish: Option<FnNnMemDescFinish>,
    mem_create_from_desc: Option<FnNnMemCreateFromDesc>,
    mem_copy: Option<FnNnMemCopy>,
    model_create: FnNnModelCreate,
    model_free: FnNnModelFree,
    model_finish: FnNnModelFinish,
    model_add_operand: FnNnModelAddOperand,
    model_set_operand_value: FnNnModelSetOperandValue,
    model_add_operation: FnNnModelAddOperation,
    model_identify_io: FnNnModelIdentifyIO,
    model_get_supported_ops: FnNnModelGetSupportedOps,
    comp_create_for_devices: FnNnCompCreateForDevices,
    comp_set_preference: FnNnCompSetPreference,
    comp_finish: FnNnCompFinish,
    comp_free: FnNnCompFree,
    burst_create: Option<FnNnBurstCreate>,
    burst_free: Option<FnNnBurstFree>,
    exec_create: FnNnExecCreate,
    exec_set_input: FnNnExecSetInput,
    exec_set_output: FnNnExecSetOutput,
    exec_set_input_from_mem: Option<FnNnExecSetInputFromMem>,
    exec_set_output_from_mem: Option<FnNnExecSetOutputFromMem>,
    exec_set_measure_timing: Option<FnNnExecSetMeasureTiming>,
    exec_get_duration: Option<FnNnExecGetDuration>,
    exec_compute: FnNnExecCompute,
    exec_burst_compute: Option<FnNnExecBurstCompute>,
    exec_free: FnNnExecFree,
}

impl Drop for DynNnapiApi {
    fn drop(&mut self) {
        // Keep libneuralnetworks.so + Binder EdgeTPU client resident (prevents ABinderProcess TLS SIGSEGV)
        let _ = self.handle;
    }
}

impl DynNnapiApi {
    fn open() -> Result<Self, String> {
        #[cfg(all(any(target_os = "android", target_os = "linux"), not(target_env = "musl")))]
        unsafe {
            let cands: [&[u8]; 3] = [
                b"libneuralnetworks.so\0",
                b"/apex/com.android.neuralnetworks/lib64/libneuralnetworks.so\0",
                b"/system/lib64/libneuralnetworks.so\0",
            ];
            let mut h: *mut c_void = CACHED_NNAPI_HANDLE.load(Ordering::Acquire) as *mut c_void;
            if h.is_null() {
                for c in cands {
                    let _ = dlerror();
                    let ptr = dlopen(c.as_ptr(), 2);
                    if !ptr.is_null() {
                        CACHED_NNAPI_HANDLE.store(ptr as usize, Ordering::Release);
                        h = ptr;
                        break;
                    }
                }
            }
            if h.is_null() {
                if cfg!(all(target_os = "linux", target_arch = "aarch64")) {
                    return Err("AVF Debian guest VM (Tensor G5 TPU unlocked on Native Android :19788)".to_string());
                }
                let err = cstr_ptr_to_string(dlerror(), 180);
                return Err(format!("libneuralnetworks.so unavailable ({})", err));
            }

            macro_rules! req_sym {
                ($sym_bytes:expr, $ty:ty) => {{
                    let p = dlsym(h, $sym_bytes.as_ptr());
                    if p.is_null() {
                        let _ = h; // keep .so mapped (TLS/atexit safe)
                        return Err(format!(
                            "Missing NNAPI symbol {}",
                            String::from_utf8_lossy(&$sym_bytes[..$sym_bytes.len() - 1])
                        ));
                    }
                    core::mem::transmute::<*mut c_void, $ty>(p)
                }};
            }
            macro_rules! opt_sym {
                ($sym_bytes:expr, $ty:ty) => {{
                    let p = dlsym(h, $sym_bytes.as_ptr());
                    if p.is_null() {
                        None
                    } else {
                        Some(core::mem::transmute::<*mut c_void, $ty>(p))
                    }
                }};
            }

            Ok(Self {
                handle: h,
                get_device_count: req_sym!(b"ANeuralNetworks_getDeviceCount\0", FnNnGetDeviceCount),
                get_device: req_sym!(b"ANeuralNetworks_getDevice\0", FnNnGetDevice),
                dev_get_name: req_sym!(b"ANeuralNetworksDevice_getName\0", FnNnDevGetName),
                dev_get_version: req_sym!(b"ANeuralNetworksDevice_getVersion\0", FnNnDevGetVersion),
                dev_get_type: req_sym!(b"ANeuralNetworksDevice_getType\0", FnNnDevGetType),
                dev_get_feature_level: req_sym!(b"ANeuralNetworksDevice_getFeatureLevel\0", FnNnDevGetFeatureLevel),
                mem_create_from_fd: opt_sym!(b"ANeuralNetworksMemory_createFromFd\0", FnNnMemCreateFromFd),
                mem_free: opt_sym!(b"ANeuralNetworksMemory_free\0", FnNnMemFree),
                mem_desc_create: opt_sym!(b"ANeuralNetworksMemoryDesc_create\0", FnNnMemDescCreate),
                mem_desc_free: opt_sym!(b"ANeuralNetworksMemoryDesc_free\0", FnNnMemDescFree),
                mem_desc_add_input_role: opt_sym!(b"ANeuralNetworksMemoryDesc_addInputRole\0", FnNnMemDescAddRole),
                mem_desc_add_output_role: opt_sym!(b"ANeuralNetworksMemoryDesc_addOutputRole\0", FnNnMemDescAddRole),
                mem_desc_finish: opt_sym!(b"ANeuralNetworksMemoryDesc_finish\0", FnNnMemDescFinish),
                mem_create_from_desc: opt_sym!(b"ANeuralNetworksMemory_createFromDesc\0", FnNnMemCreateFromDesc),
                mem_copy: opt_sym!(b"ANeuralNetworksMemory_copy\0", FnNnMemCopy),
                model_create: req_sym!(b"ANeuralNetworksModel_create\0", FnNnModelCreate),
                model_free: req_sym!(b"ANeuralNetworksModel_free\0", FnNnModelFree),
                model_finish: req_sym!(b"ANeuralNetworksModel_finish\0", FnNnModelFinish),
                model_add_operand: req_sym!(b"ANeuralNetworksModel_addOperand\0", FnNnModelAddOperand),
                model_set_operand_value: req_sym!(b"ANeuralNetworksModel_setOperandValue\0", FnNnModelSetOperandValue),
                model_add_operation: req_sym!(b"ANeuralNetworksModel_addOperation\0", FnNnModelAddOperation),
                model_identify_io: req_sym!(b"ANeuralNetworksModel_identifyInputsAndOutputs\0", FnNnModelIdentifyIO),
                model_get_supported_ops: req_sym!(b"ANeuralNetworksModel_getSupportedOperationsForDevices\0", FnNnModelGetSupportedOps),
                comp_create_for_devices: req_sym!(b"ANeuralNetworksCompilation_createForDevices\0", FnNnCompCreateForDevices),
                comp_set_preference: req_sym!(b"ANeuralNetworksCompilation_setPreference\0", FnNnCompSetPreference),
                comp_finish: req_sym!(b"ANeuralNetworksCompilation_finish\0", FnNnCompFinish),
                comp_free: req_sym!(b"ANeuralNetworksCompilation_free\0", FnNnCompFree),
                burst_create: opt_sym!(b"ANeuralNetworksBurst_create\0", FnNnBurstCreate),
                burst_free: opt_sym!(b"ANeuralNetworksBurst_free\0", FnNnBurstFree),
                exec_create: req_sym!(b"ANeuralNetworksExecution_create\0", FnNnExecCreate),
                exec_set_input: req_sym!(b"ANeuralNetworksExecution_setInput\0", FnNnExecSetInput),
                exec_set_output: req_sym!(b"ANeuralNetworksExecution_setOutput\0", FnNnExecSetOutput),
                exec_set_input_from_mem: opt_sym!(b"ANeuralNetworksExecution_setInputFromMemory\0", FnNnExecSetInputFromMem),
                exec_set_output_from_mem: opt_sym!(b"ANeuralNetworksExecution_setOutputFromMemory\0", FnNnExecSetOutputFromMem),
                exec_set_measure_timing: opt_sym!(b"ANeuralNetworksExecution_setMeasureTiming\0", FnNnExecSetMeasureTiming),
                exec_get_duration: opt_sym!(b"ANeuralNetworksExecution_getDuration\0", FnNnExecGetDuration),
                exec_compute: req_sym!(b"ANeuralNetworksExecution_compute\0", FnNnExecCompute),
                exec_burst_compute: opt_sym!(b"ANeuralNetworksExecution_burstCompute\0", FnNnExecBurstCompute),
                exec_free: req_sym!(b"ANeuralNetworksExecution_free\0", FnNnExecFree),
            })
        }
        #[cfg(not(all(any(target_os = "android", target_os = "linux"), not(target_env = "musl"))))]
        {
            Err("Windows x64 host mode (Tensor G5 TPU unlocked on Pixel 10 :19788)".to_string())
        }
    }

    // Allocates VINTF SELinux-compliant Android ashmem via libandroid.so ASharedMemory_create!
    fn alloc_ashmem_pool(&self, byte_len: usize, writable_by_tpu: bool) -> Option<AshmemNnapiPool> {
        #[cfg(all(any(target_os = "android", target_os = "linux"), not(target_env = "musl")))]
        unsafe {
            let create_from_fd = self.mem_create_from_fd?;
            let mem_free_fn = self.mem_free?;
            let mut libc_h = CACHED_LIBC_HANDLE.load(Ordering::Acquire) as *mut c_void;
            if libc_h.is_null() {
                libc_h = dlopen(b"libc.so\0".as_ptr(), 2);
                if !libc_h.is_null() { CACHED_LIBC_HANDLE.store(libc_h as usize, Ordering::Release); }
            }
            if libc_h.is_null() {
                return None;
            }
            let mut android_h = CACHED_ANDROID_HANDLE.load(Ordering::Acquire) as *mut c_void;
            if android_h.is_null() {
                android_h = dlopen(b"libandroid.so\0".as_ptr(), 2);
                if !android_h.is_null() { CACHED_ANDROID_HANDLE.store(android_h as usize, Ordering::Release); }
            }
            if android_h.is_null() {
                return None;
            }
            let p_ashmem = dlsym(android_h, b"ASharedMemory_create\0".as_ptr());
            let p_mmap = dlsym(libc_h, b"mmap\0".as_ptr());
            let p_munmap = dlsym(libc_h, b"munmap\0".as_ptr());
            let p_close = dlsym(libc_h, b"close\0".as_ptr());
            if p_ashmem.is_null() || p_mmap.is_null() || p_munmap.is_null() || p_close.is_null() {
                
                
                return None;
            }
            type FnAshmemCreate = unsafe extern "C" fn(*const u8, usize) -> i32;
            type FnMmap = unsafe extern "C" fn(*mut c_void, usize, i32, i32, i32, i64) -> *mut c_void;
            type FnMunmap = unsafe extern "C" fn(*mut c_void, usize) -> i32;
            type FnClose = unsafe extern "C" fn(i32) -> i32;

            let f_ashmem: FnAshmemCreate = core::mem::transmute(p_ashmem);
            let f_mmap: FnMmap = core::mem::transmute(p_mmap);
            let f_munmap: FnMunmap = core::mem::transmute(p_munmap);
            let f_close: FnClose = core::mem::transmute(p_close);

            let aligned = (byte_len.max(4096) + 16383) & !16383;
            let fd = f_ashmem(b"omega_edgetpu_ashmem\0".as_ptr(), aligned);
            if fd < 0 {
                
                
                return None;
            }
            let ptr = f_mmap(null_mut(), aligned, 3, 1, fd, 0);
            if ptr.is_null() || (ptr as usize) == usize::MAX {
                let _ = f_close(fd);
                
                
                return None;
            }
            let nn_prot = if writable_by_tpu { 3 } else { 1 };
            let mut nn_mem: *mut c_void = null_mut();
            if create_from_fd(aligned, nn_prot, fd, 0, &mut nn_mem) != 0 || nn_mem.is_null() {
                let _ = f_munmap(ptr, aligned);
                let _ = f_close(fd);
                
                
                return None;
            }
            Some(AshmemNnapiPool {
                fd,
                map_ptr: ptr as *mut u8,
                map_len: aligned,
                nn_mem,
                libc_handle: libc_h,
                android_handle: android_h,
                fn_munmap: Some(f_munmap),
                fn_close: Some(f_close),
                fn_nn_mem_free: Some(mem_free_fn),
            })
        }
        #[cfg(not(all(any(target_os = "android", target_os = "linux"), not(target_env = "musl"))))]
        {
            let _ = (byte_len, writable_by_tpu);
            None
        }
    }

    // Allocates driver-owned gcip_iommu DeviceMemory directly from google-edgetpu HAL via ANeuralNetworksMemoryDesc!
    fn alloc_driver_device_mem(&self, comp: *const c_void, is_output: bool) -> Option<DriverDeviceMem> {
        unsafe {
            let desc_create = self.mem_desc_create?;
            let desc_free = self.mem_desc_free?;
            let add_role = if is_output {
                self.mem_desc_add_output_role?
            } else {
                self.mem_desc_add_input_role?
            };
            let desc_finish = self.mem_desc_finish?;
            let create_from_desc = self.mem_create_from_desc?;
            let mem_free_fn = self.mem_free?;

            let mut desc: *mut c_void = null_mut();
            if desc_create(&mut desc) != 0 || desc.is_null() {
                return None;
            }
            if add_role(desc, comp, 0, 1.0f32) != 0 || desc_finish(desc) != 0 {
                desc_free(desc);
                return None;
            }
            let mut nn_mem: *mut c_void = null_mut();
            let rc = create_from_desc(desc, &mut nn_mem);
            desc_free(desc);
            if rc != 0 || nn_mem.is_null() {
                return None;
            }
            Some(DriverDeviceMem {
                nn_mem,
                fn_nn_mem_free: Some(mem_free_fn),
            })
        }
    }
}

// Returns (supported, dma_mode_tag, compile_rc, exec_rc, elapsed_ms, hw_us, drv_us)
unsafe fn run_nnapi_compiled_model(
    api: &DynNnapiApi,
    model: *mut c_void,
    num_ops: usize,
    dev: *const c_void,
    in_slice: &[u8],
    out_slice: &mut [u8],
    burst_iters: u32,
) -> (bool, &'static str, i32, i32, f64, f64, f64) {
    let devs: [*const c_void; 1] = [dev];
    let mut supp = vec![0u8; num_ops.max(8)];
    let supp_ok = (api.model_get_supported_ops)(model, devs.as_ptr(), 1, supp.as_mut_ptr()) == 0;
    let supported = supp_ok && supp.iter().take(num_ops).all(|&b| b != 0);

    let mut comp: *mut c_void = null_mut();
    let crc = (api.comp_create_for_devices)(model, devs.as_ptr(), 1, &mut comp);
    if crc != NNAPI_NO_ERROR || comp.is_null() {
        return (supported, "none", if crc != 0 { crc } else { -1 }, -1, 0.0, -1.0, -1.0);
    }
    let _ = (api.comp_set_preference)(comp, NNAPI_PREFER_SUSTAINED_SPEED);
    let fin_rc = (api.comp_finish)(comp);
    if fin_rc != NNAPI_NO_ERROR {
        (api.comp_free)(comp);
        return (supported, "none", fin_rc, -1, 0.0, -1.0, -1.0);
    }

    let mut burst: *mut c_void = null_mut();
    if let Some(b_create) = api.burst_create {
        let _ = b_create(comp, &mut burst);
    }

    // Prepare optional Ashmem & Driver MemoryDesc handles, then live-probe each tier on ex0!
    // Tier 1: Driver DeviceMemory (ANeuralNetworksMemoryDesc + ANeuralNetworksMemory_copy)
    // Tier 2: Android Ashmem (ASharedMemory_create + ANeuralNetworksMemory_createFromFd)
    // Tier 3: NNAPI Burst user-pointer (ANeuralNetworksExecution_setInput/setOutput + Burst)
    let mut ash_in = api.alloc_ashmem_pool(in_slice.len(), false);
    let mut ash_out = api.alloc_ashmem_pool(out_slice.len(), true);
    if let (Some(ref ai), Some(ref ao)) = (&ash_in, &ash_out) {
        core::ptr::copy_nonoverlapping(in_slice.as_ptr(), ai.map_ptr, in_slice.len());
        core::ptr::write_bytes(ao.map_ptr, 0, out_slice.len());
    } else {
        ash_in = None;
        ash_out = None;
    }

    let mut drv_in = if ash_in.is_some() && api.mem_copy.is_some() && api.exec_set_input_from_mem.is_some() && api.exec_set_output_from_mem.is_some() {
        api.alloc_driver_device_mem(comp, false)
    } else {
        None
    };
    let mut drv_out = if drv_in.is_some() && ash_out.is_some() {
        api.alloc_driver_device_mem(comp, true)
    } else {
        None
    };
    if let (Some(ref di), Some(ref do_m), Some(ref ai), Some(mcopy)) = (&drv_in, &drv_out, &ash_in, api.mem_copy) {
        if mcopy(ai.nn_mem, di.nn_mem) != 0 {
            drv_in = None;
            drv_out = None;
        } else {
            let _ = do_m;
        }
    } else {
        drv_in = None;
        drv_out = None;
    }

    // Helper closure to test single execution + timing on a specific tier (1 = drv_desc, 2 = ashmem, 3 = burst_ptr)
    let mut chosen_tier: u8 = 0;
    let mut last_exec_rc: i32 = -1;
    let mut hw_us = -1.0f64;
    let mut drv_us = -1.0f64;

    for cand_tier in [1u8, 2u8, 3u8] {
        if cand_tier == 1 && (drv_in.is_none() || drv_out.is_none()) {
            continue;
        }
        if cand_tier == 2 && (ash_in.is_none() || ash_out.is_none() || api.exec_set_input_from_mem.is_none() || api.exec_set_output_from_mem.is_none()) {
            continue;
        }
        let mut ex0: *mut c_void = null_mut();
        let c_rc = (api.exec_create)(comp, &mut ex0);
        if c_rc != NNAPI_NO_ERROR || ex0.is_null() {
            last_exec_rc = c_rc;
            continue;
        }
        let bind_ok = if cand_tier == 1 {
            let f_in = api.exec_set_input_from_mem.unwrap();
            let f_out = api.exec_set_output_from_mem.unwrap();
            let di = drv_in.as_ref().unwrap();
            let do_m = drv_out.as_ref().unwrap();
            f_in(ex0, 0, null(), di.nn_mem, 0, 0) == 0 && f_out(ex0, 0, null(), do_m.nn_mem, 0, 0) == 0
        } else if cand_tier == 2 {
            let f_in = api.exec_set_input_from_mem.unwrap();
            let f_out = api.exec_set_output_from_mem.unwrap();
            let ai = ash_in.as_ref().unwrap();
            let ao = ash_out.as_ref().unwrap();
            f_in(ex0, 0, null(), ai.nn_mem, 0, in_slice.len()) == 0
                && f_out(ex0, 0, null(), ao.nn_mem, 0, out_slice.len()) == 0
        } else {
            out_slice.fill(0);
            (api.exec_set_input)(ex0, 0, null(), in_slice.as_ptr() as *const c_void, in_slice.len()) == 0
                && (api.exec_set_output)(ex0, 0, null(), out_slice.as_mut_ptr() as *mut c_void, out_slice.len()) == 0
        };
        if !bind_ok {
            (api.exec_free)(ex0);
            continue;
        }
        if let Some(set_tm) = api.exec_set_measure_timing {
            let _ = set_tm(ex0, 1);
        }
        let r0 = if !burst.is_null() && cand_tier == 3 {
            if let Some(b_comp) = api.exec_burst_compute {
                b_comp(ex0, burst)
            } else {
                (api.exec_compute)(ex0)
            }
        } else {
            (api.exec_compute)(ex0)
        };
        last_exec_rc = r0;
        if r0 == NNAPI_NO_ERROR {
            if let Some(get_dur) = api.exec_get_duration {
                let mut ns_hw: u64 = u64::MAX;
                let mut ns_drv: u64 = u64::MAX;
                if get_dur(ex0, NNAPI_DURATION_ON_HARDWARE, &mut ns_hw) == 0 && ns_hw != u64::MAX && ns_hw > 0 {
                    hw_us = (ns_hw as f64) / 1000.0;
                }
                if get_dur(ex0, NNAPI_DURATION_IN_DRIVER, &mut ns_drv) == 0 && ns_drv != u64::MAX && ns_drv > 0 {
                    drv_us = (ns_drv as f64) / 1000.0;
                }
            }
            let copy_ok = if cand_tier == 1 {
                let mcopy = api.mem_copy.unwrap();
                let do_m = drv_out.as_ref().unwrap();
                let ao = ash_out.as_ref().unwrap();
                if mcopy(do_m.nn_mem, ao.nn_mem) == 0 {
                    core::ptr::copy_nonoverlapping(ao.map_ptr, out_slice.as_mut_ptr(), out_slice.len());
                    true
                } else {
                    false
                }
            } else if cand_tier == 2 {
                let ao = ash_out.as_ref().unwrap();
                core::ptr::copy_nonoverlapping(ao.map_ptr, out_slice.as_mut_ptr(), out_slice.len());
                true
            } else {
                true
            };
            (api.exec_free)(ex0);
            if copy_ok {
                chosen_tier = cand_tier;
                break;
            }
        } else {
            (api.exec_free)(ex0);
        }
    }

    if chosen_tier == 0 {
        if !burst.is_null() {
            if let Some(b_free) = api.burst_free {
                b_free(burst);
            }
        }
        drop(drv_in);
        drop(drv_out);
        drop(ash_in);
        drop(ash_out);
        (api.comp_free)(comp);
        return (supported, "none", 0, last_exec_rc, 0.0, hw_us, drv_us);
    }

    // 2. High-throughput Burst loop on the verified winning DMA tier!
    let iters = burst_iters.max(1);
    let t0 = Instant::now();
    let mut loop_rc = NNAPI_NO_ERROR;
    for _ in 0..iters {
        let mut ex: *mut c_void = null_mut();
        let rc_c = (api.exec_create)(comp, &mut ex);
        if rc_c != NNAPI_NO_ERROR || ex.is_null() {
            loop_rc = rc_c;
            break;
        }
        if chosen_tier == 1 {
            let f_in = api.exec_set_input_from_mem.unwrap();
            let f_out = api.exec_set_output_from_mem.unwrap();
            let di = drv_in.as_ref().unwrap();
            let do_m = drv_out.as_ref().unwrap();
            let _ = f_in(ex, 0, null(), di.nn_mem, 0, 0);
            let _ = f_out(ex, 0, null(), do_m.nn_mem, 0, 0);
        } else if chosen_tier == 2 {
            let f_in = api.exec_set_input_from_mem.unwrap();
            let f_out = api.exec_set_output_from_mem.unwrap();
            let ai = ash_in.as_ref().unwrap();
            let ao = ash_out.as_ref().unwrap();
            let _ = f_in(ex, 0, null(), ai.nn_mem, 0, in_slice.len());
            let _ = f_out(ex, 0, null(), ao.nn_mem, 0, out_slice.len());
        } else {
            let _ = (api.exec_set_input)(ex, 0, null(), in_slice.as_ptr() as *const c_void, in_slice.len());
            let _ = (api.exec_set_output)(ex, 0, null(), out_slice.as_mut_ptr() as *mut c_void, out_slice.len());
        }
        let rc_r = if !burst.is_null() {
            if let Some(b_comp) = api.exec_burst_compute {
                b_comp(ex, burst)
            } else {
                (api.exec_compute)(ex)
            }
        } else {
            (api.exec_compute)(ex)
        };
        (api.exec_free)(ex);
        if rc_r != NNAPI_NO_ERROR {
            loop_rc = rc_r;
            break;
        }
    }
    let elapsed_ms = t0.elapsed().as_secs_f64() * 1000.0;
    if loop_rc == NNAPI_NO_ERROR {
        if chosen_tier == 1 {
            let mcopy = api.mem_copy.unwrap();
            let do_m = drv_out.as_ref().unwrap();
            let ao = ash_out.as_ref().unwrap();
            let _ = mcopy(do_m.nn_mem, ao.nn_mem);
            core::ptr::copy_nonoverlapping(ao.map_ptr, out_slice.as_mut_ptr(), out_slice.len());
        } else if chosen_tier == 2 {
            let ao = ash_out.as_ref().unwrap();
            core::ptr::copy_nonoverlapping(ao.map_ptr, out_slice.as_mut_ptr(), out_slice.len());
        }
    }

    if !burst.is_null() {
        if let Some(b_free) = api.burst_free {
            b_free(burst);
        }
    }
    drop(drv_in);
    drop(drv_out);
    drop(ash_in);
    drop(ash_out);
    (api.comp_free)(comp);

    let dma_tag = match chosen_tier {
        1 => "driver_mem_desc",
        2 => "ashmem_zero_copy",
        _ => "nnapi_burst",
    };
    (supported, dma_tag, 0, loop_rc, elapsed_ms, hw_us, drv_us)
}

unsafe fn bench_tpu_conv2d_q8_single_depth(
    api: &DynNnapiApi,
    dev: *const c_void,
    dev_name: &str,
    dev_type: i32,
    is_hw_tpu: bool,
    layers: usize,
    burst_iters: u32,
    kernel_id: &str,
) -> (TpuGraphBenchRow, &'static str) {
    // High-Arithmetic-Intensity Fused Systolic 1x1 CONV_2D: [1, 64, 64, 256] x L * [256, 1, 1, 256]
    // Only 64 KB weights/layer -> 16 layers = 1.00 MB total weights (fits inside 36500000.buenos SRAM!)
    // while delivering 8,589,934,592 INT8 OPs (8.590 GOPS) per single call at L=16!
    const PIXELS: usize = 64 * 64;
    const CH: usize = 256;
    const GROUPS: usize = CH / 8; // 32 groups of 8 channels
    const ELEMS: usize = PIXELS * CH;
    let ops_per_iter: f64 = (layers as f64) * (PIXELS as f64) * (CH as f64) * (CH as f64) * 2.0;

    let mut act_buf = vec![128u8; ELEMS];
    let mut out_buf = vec![0u8; ELEMS];
    let mut exp_buf = vec![128u8; ELEMS];
    let mut v_state = vec![0i32; PIXELS * GROUPS];

    for p in 0..PIXELS {
        for g in 0..GROUPS {
            let dv = (((p * 7 + g * 11) % 5) as i32) - 2;
            v_state[p * GROUPS + g] = dv;
            let base = p * CH + g * 8;
            let vu8 = (128 + dv) as u8;
            for lane in 0..8usize {
                act_buf[base + lane] = vu8;
            }
        }
    }

    let mut all_weights: Vec<Vec<u8>> = Vec::with_capacity(layers);
    let mut all_biases: Vec<Vec<i32>> = Vec::with_capacity(layers);
    for l in 0..layers {
        let mut w_l = vec![128u8; CH * CH];
        let mut b_l = vec![0i32; CH];
        for go in 0..GROUPS {
            let g1 = (go + 3 * l + 1) % GROUPS;
            let db = (((go + l) % 3) as i32) - 1;
            for lane_o in 0..8usize {
                let o = go * 8 + lane_o;
                b_l[o] = db * 8;
                let flip = (go + l + lane_o) & 1;
                let row_base = o * CH;
                for gi in 0..GROUPS {
                    let c_base = row_base + gi * 8;
                    if gi == g1 {
                        for lane_i in 0..8usize {
                            w_l[c_base + lane_i] = 129;
                        }
                    } else {
                        for lane_i in 0..8usize {
                            let sgn: i32 = if ((lane_i + flip) & 1) == 0 { 1 } else { -1 };
                            w_l[c_base + lane_i] = (128 + sgn) as u8;
                        }
                    }
                }
            }
        }
        let mut v_next = vec![0i32; PIXELS * GROUPS];
        for p in 0..PIXELS {
            for go in 0..GROUPS {
                let g1 = (go + 3 * l + 1) % GROUPS;
                let db = (((go + l) % 3) as i32) - 1;
                v_next[p * GROUPS + go] = v_state[p * GROUPS + g1] + db;
            }
        }
        v_state = v_next;
        all_weights.push(w_l);
        all_biases.push(b_l);
    }

    for p in 0..PIXELS {
        for go in 0..GROUPS {
            let vu8 = (128 + v_state[p * GROUPS + go]) as u8;
            let base = p * CH + go * 8;
            for lane in 0..8usize {
                exp_buf[base + lane] = vu8;
            }
        }
    }

    let mut model: *mut c_void = null_mut();
    if (api.model_create)(&mut model) != NNAPI_NO_ERROR || model.is_null() {
        return (
            TpuGraphBenchRow {
                kernel_id: kernel_id.to_string(),
                device_name: dev_name.to_string(),
                device_type: dev_type,
                is_hw_tpu,
                supported: false,
                compile_rc: -1,
                exec_rc: -1,
                matched: 0,
                elements: ELEMS as u32,
                burst_iters,
                elapsed_ms: 0.0,
                hw_us: -1.0,
                drv_us: -1.0,
                melem_per_sec: 0.0,
                gops_per_sec: 0.0,
                hw_on_die_gops: 0.0,
                detail: "Model_create failed".to_string(),
            },
            "none",
        );
    }

    let dims_act: [u32; 4] = [1, 64, 64, CH as u32];
    let dims_flt: [u32; 4] = [CH as u32, 1, 1, CH as u32];
    let dims_bias: [u32; 1] = [CH as u32];

    let op_act = NnapiOperandType {
        operand_type: NNAPI_TENSOR_QUANT8_ASYMM,
        dimension_count: 4,
        dimensions: dims_act.as_ptr(),
        scale: 0.125,
        zero_point: 128,
    };
    let op_flt = NnapiOperandType {
        operand_type: NNAPI_TENSOR_QUANT8_ASYMM,
        dimension_count: 4,
        dimensions: dims_flt.as_ptr(),
        scale: 0.125,
        zero_point: 128,
    };
    let op_bias = NnapiOperandType {
        operand_type: NNAPI_TENSOR_INT32,
        dimension_count: 1,
        dimensions: dims_bias.as_ptr(),
        scale: 0.015625,
        zero_point: 0,
    };
    let op_i32 = NnapiOperandType {
        operand_type: NNAPI_INT32,
        dimension_count: 0,
        dimensions: null(),
        scale: 0.0,
        zero_point: 0,
    };

    let pad_val: i32 = NNAPI_PADDING_VALID;
    let stride_1: i32 = 1;
    let fuse_none: i32 = NNAPI_FUSED_NONE;

    let mut next_idx: u32 = 0;
    let idx_pad = next_idx; next_idx += 1;
    let idx_sw = next_idx; next_idx += 1;
    let idx_sh = next_idx; next_idx += 1;
    let idx_fuse = next_idx; next_idx += 1;
    let mut built = (api.model_add_operand)(model, &op_i32) == 0
        && (api.model_add_operand)(model, &op_i32) == 0
        && (api.model_add_operand)(model, &op_i32) == 0
        && (api.model_add_operand)(model, &op_i32) == 0
        && (api.model_set_operand_value)(model, idx_pad as i32, &pad_val as *const i32 as *const c_void, 4) == 0
        && (api.model_set_operand_value)(model, idx_sw as i32, &stride_1 as *const i32 as *const c_void, 4) == 0
        && (api.model_set_operand_value)(model, idx_sh as i32, &stride_1 as *const i32 as *const c_void, 4) == 0
        && (api.model_set_operand_value)(model, idx_fuse as i32, &fuse_none as *const i32 as *const c_void, 4) == 0;

    let idx_in0 = next_idx; next_idx += 1;
    built = built && (api.model_add_operand)(model, &op_act) == 0;
    let mut cur_act_idx = idx_in0;

    for l in 0..layers {
        let idx_w = next_idx; next_idx += 1;
        let idx_b = next_idx; next_idx += 1;
        let idx_out = next_idx; next_idx += 1;
        built = built
            && (api.model_add_operand)(model, &op_flt) == 0
            && (api.model_add_operand)(model, &op_bias) == 0
            && (api.model_add_operand)(model, &op_act) == 0
            && (api.model_set_operand_value)(model, idx_w as i32, all_weights[l].as_ptr() as *const c_void, all_weights[l].len()) == 0
            && (api.model_set_operand_value)(model, idx_b as i32, all_biases[l].as_ptr() as *const c_void, all_biases[l].len() * 4) == 0
            && (api.model_add_operation)(
                model,
                NNAPI_OP_CONV_2D,
                7,
                [cur_act_idx, idx_w, idx_b, idx_pad, idx_sw, idx_sh, idx_fuse].as_ptr(),
                1,
                [idx_out].as_ptr(),
            ) == 0;
        cur_act_idx = idx_out;
    }

    built = built
        && (api.model_identify_io)(model, 1, [idx_in0].as_ptr(), 1, [cur_act_idx].as_ptr()) == 0
        && (api.model_finish)(model) == 0;

    if !built {
        (api.model_free)(model);
        return (
            TpuGraphBenchRow {
                kernel_id: kernel_id.to_string(),
                device_name: dev_name.to_string(),
                device_type: dev_type,
                is_hw_tpu,
                supported: false,
                compile_rc: -2,
                exec_rc: -2,
                matched: 0,
                elements: ELEMS as u32,
                burst_iters,
                elapsed_ms: 0.0,
                hw_us: -1.0,
                drv_us: -1.0,
                melem_per_sec: 0.0,
                gops_per_sec: 0.0,
                hw_on_die_gops: 0.0,
                detail: format!("{}L CONV_2D Q8 build failed", layers),
            },
            "none",
        );
    }

    let (supported, dma_tag, comp_rc, exec_rc, elapsed_ms, hw_us, drv_us) = run_nnapi_compiled_model(
        api,
        model,
        layers,
        dev,
        &act_buf,
        &mut out_buf,
        burst_iters,
    );
    (api.model_free)(model);
    drop(all_weights);
    drop(all_biases);

    if comp_rc != 0 || exec_rc != 0 {
        return (
            TpuGraphBenchRow {
                kernel_id: kernel_id.to_string(),
                device_name: dev_name.to_string(),
                device_type: dev_type,
                is_hw_tpu,
                supported,
                compile_rc: comp_rc,
                exec_rc,
                matched: 0,
                elements: ELEMS as u32,
                burst_iters,
                elapsed_ms: 0.0,
                hw_us,
                drv_us,
                melem_per_sec: 0.0,
                gops_per_sec: 0.0,
                hw_on_die_gops: 0.0,
                detail: format!("L={} compile={} exec={}", layers, nnapi_rc_name(comp_rc), nnapi_rc_name(exec_rc)),
            },
            dma_tag,
        );
    }

    let mut matched = 0u32;
    let mut exact0 = 0u32;
    for idx in 0..ELEMS {
        let d = (out_buf[idx] as i32 - exp_buf[idx] as i32).abs();
        if d == 0 {
            exact0 += 1;
        }
        if d <= 1 {
            matched += 1;
        }
    }
    let sec = (elapsed_ms / 1000.0).max(1e-6);
    let gops = (ops_per_iter * (burst_iters.max(1) as f64)) / (sec * 1e9);
    let melem = ((ELEMS as f64) * (burst_iters.max(1) as f64)) / (sec * 1e6);
    let hw_die_gops = if hw_us > 5.0 {
        ops_per_iter / ((hw_us / 1e6) * 1e9)
    } else {
        0.0
    };
    let t_tag = match (hw_us >= 0.0, drv_us >= 0.0) {
        (true, true) => format!("hw={:.1}us/drv={:.1}us", hw_us, drv_us),
        (true, false) => format!("hw={:.1}us", hw_us),
        _ => "hw_ok".to_string(),
    };
    let det = format!(
        "{} {}-Layer Fused CONV_2D w8a8o8 [1,64,64,256]x{} ({:.3} TOPS/s, {}x {}, {}, exact0={}/{})",
        dev_name,
        layers,
        layers,
        gops / 1000.0,
        burst_iters,
        dma_tag,
        t_tag,
        exact0,
        ELEMS
    );

    (
        TpuGraphBenchRow {
            kernel_id: kernel_id.to_string(),
            device_name: dev_name.to_string(),
            device_type: dev_type,
            is_hw_tpu,
            supported,
            compile_rc: 0,
            exec_rc: 0,
            matched,
            elements: ELEMS as u32,
            burst_iters,
            elapsed_ms,
            hw_us,
            drv_us,
            melem_per_sec: melem,
            gops_per_sec: gops,
            hw_on_die_gops: hw_die_gops,
            detail: det,
        },
        dma_tag,
    )
}

unsafe fn bench_tpu_conv2d_16l_q8(
    api: &DynNnapiApi,
    dev: *const c_void,
    dev_name: &str,
    dev_type: i32,
    is_hw_tpu: bool,
    burst_iters: u32,
    prefix: &str,
) -> (TpuGraphBenchRow, &'static str) {
    let mut last_res: Option<(TpuGraphBenchRow, &'static str)> = None;
    for &layers in &[16usize, 8, 4, 1] {
        let kid = format!("K11_{}_CONV2D_{}L_Q8", prefix, layers);
        let (row, tag) = bench_tpu_conv2d_q8_single_depth(api, dev, dev_name, dev_type, is_hw_tpu, layers, burst_iters, &kid);
        if row.compile_rc == 0 && row.exec_rc == 0 && row.matched == row.elements {
            return (row, tag);
        }
        last_res = Some((row, tag));
    }
    last_res.unwrap()
}

unsafe fn bench_tpu_fc_q8_shape(
    api: &DynNnapiApi,
    dev: *const c_void,
    dev_name: &str,
    dev_type: i32,
    is_hw_tpu: bool,
    m_rows: usize,
    ch: usize,
    layers: usize,
    burst_iters: u32,
    kernel_id: &str,
) -> (TpuGraphBenchRow, &'static str) {
    // Hardware-verified EdgeTPU FULLY_CONNECTED batch constraint: m_rows <= 512!
    let groups: usize = ch / 8;
    let elems: usize = m_rows * ch;
    let ops_per_iter: f64 = (layers as f64) * (m_rows as f64) * (ch as f64) * (ch as f64) * 2.0;

    let mut act_buf = vec![128u8; elems];
    let mut out_buf = vec![0u8; elems];
    let mut exp_buf = vec![128u8; elems];
    let mut v_state = vec![0i32; m_rows * groups];

    for r in 0..m_rows {
        for g in 0..groups {
            let dv = (((r * 5 + g * 13) % 5) as i32) - 2;
            v_state[r * groups + g] = dv;
            let base = r * ch + g * 8;
            let vu8 = (128 + dv) as u8;
            for lane in 0..8usize {
                act_buf[base + lane] = vu8;
            }
        }
    }

    let mut all_weights: Vec<Vec<u8>> = Vec::with_capacity(layers);
    let mut all_biases: Vec<Vec<i32>> = Vec::with_capacity(layers);
    for l in 0..layers {
        let mut w_l = vec![128u8; ch * ch];
        let mut b_l = vec![0i32; ch];
        for go in 0..groups {
            let g1 = (go + 5 * l + 3) % groups;
            let db = (((go + l * 2) % 3) as i32) - 1;
            for lane_o in 0..8usize {
                let o = go * 8 + lane_o;
                b_l[o] = db * 8;
                let flip = (go + l + lane_o) & 1;
                let row_base = o * ch;
                for gi in 0..groups {
                    let c_base = row_base + gi * 8;
                    if gi == g1 {
                        for lane_i in 0..8usize {
                            w_l[c_base + lane_i] = 129;
                        }
                    } else {
                        for lane_i in 0..8usize {
                            let sgn: i32 = if ((lane_i + flip) & 1) == 0 { 1 } else { -1 };
                            w_l[c_base + lane_i] = (128 + sgn) as u8;
                        }
                    }
                }
            }
        }
        let mut v_next = vec![0i32; m_rows * groups];
        for r in 0..m_rows {
            for go in 0..groups {
                let g1 = (go + 5 * l + 3) % groups;
                let db = (((go + l * 2) % 3) as i32) - 1;
                v_next[r * groups + go] = v_state[r * groups + g1] + db;
            }
        }
        v_state = v_next;
        all_weights.push(w_l);
        all_biases.push(b_l);
    }

    for r in 0..m_rows {
        for go in 0..groups {
            let vu8 = (128 + v_state[r * groups + go]) as u8;
            let base = r * ch + go * 8;
            for lane in 0..8usize {
                exp_buf[base + lane] = vu8;
            }
        }
    }

    let mut model: *mut c_void = null_mut();
    if (api.model_create)(&mut model) != NNAPI_NO_ERROR || model.is_null() {
        return (
            TpuGraphBenchRow {
                kernel_id: kernel_id.to_string(),
                device_name: dev_name.to_string(),
                device_type: dev_type,
                is_hw_tpu,
                supported: false,
                compile_rc: -2,
                exec_rc: -1,
                matched: 0,
                elements: elems as u32,
                burst_iters,
                elapsed_ms: 0.0,
                hw_us: -1.0,
                drv_us: -1.0,
                melem_per_sec: 0.0,
                gops_per_sec: 0.0,
                hw_on_die_gops: 0.0,
                detail: "Model_create failed".to_string(),
            },
            "none",
        );
    }

    let dims_act: [u32; 2] = [m_rows as u32, ch as u32];
    let dims_w: [u32; 2] = [ch as u32, ch as u32];
    let dims_1d: [u32; 1] = [ch as u32];
    let op_in = NnapiOperandType {
        operand_type: NNAPI_TENSOR_QUANT8_ASYMM,
        dimension_count: 2,
        dimensions: dims_act.as_ptr(),
        scale: 0.125,
        zero_point: 128,
    };
    let op_w = NnapiOperandType {
        operand_type: NNAPI_TENSOR_QUANT8_ASYMM,
        dimension_count: 2,
        dimensions: dims_w.as_ptr(),
        scale: 0.125,
        zero_point: 128,
    };
    let op_bias = NnapiOperandType {
        operand_type: NNAPI_TENSOR_INT32,
        dimension_count: 1,
        dimensions: dims_1d.as_ptr(),
        scale: 0.015625,
        zero_point: 0,
    };
    let op_i32 = NnapiOperandType {
        operand_type: NNAPI_INT32,
        dimension_count: 0,
        dimensions: null(),
        scale: 0.0,
        zero_point: 0,
    };
    let fuse_none: i32 = NNAPI_FUSED_NONE;

    let mut next_idx: u32 = 0;
    let idx_fuse = next_idx; next_idx += 1;
    let idx_in0 = next_idx; next_idx += 1;
    let mut built = (api.model_add_operand)(model, &op_i32) == 0
        && (api.model_set_operand_value)(model, idx_fuse as i32, &fuse_none as *const i32 as *const c_void, 4) == 0
        && (api.model_add_operand)(model, &op_in) == 0;
    let mut cur_act_idx = idx_in0;

    for l in 0..layers {
        let idx_w = next_idx; next_idx += 1;
        let idx_b = next_idx; next_idx += 1;
        let idx_out = next_idx; next_idx += 1;
        built = built
            && (api.model_add_operand)(model, &op_w) == 0
            && (api.model_add_operand)(model, &op_bias) == 0
            && (api.model_add_operand)(model, &op_in) == 0
            && (api.model_set_operand_value)(model, idx_w as i32, all_weights[l].as_ptr() as *const c_void, all_weights[l].len()) == 0
            && (api.model_set_operand_value)(model, idx_b as i32, all_biases[l].as_ptr() as *const c_void, all_biases[l].len() * 4) == 0
            && (api.model_add_operation)(
                model,
                NNAPI_OP_FULLY_CONNECTED,
                4,
                [cur_act_idx, idx_w, idx_b, idx_fuse].as_ptr(),
                1,
                [idx_out].as_ptr(),
            ) == 0;
        cur_act_idx = idx_out;
    }

    built = built
        && (api.model_identify_io)(model, 1, [idx_in0].as_ptr(), 1, [cur_act_idx].as_ptr()) == 0
        && (api.model_finish)(model) == 0;

    if !built {
        (api.model_free)(model);
        return (
            TpuGraphBenchRow {
                kernel_id: kernel_id.to_string(),
                device_name: dev_name.to_string(),
                device_type: dev_type,
                is_hw_tpu,
                supported: false,
                compile_rc: -2,
                exec_rc: -1,
                matched: 0,
                elements: elems as u32,
                burst_iters,
                elapsed_ms: 0.0,
                hw_us: -1.0,
                drv_us: -1.0,
                melem_per_sec: 0.0,
                gops_per_sec: 0.0,
                hw_on_die_gops: 0.0,
                detail: format!("{}L FC Q8 [{}x{}] build failed", layers, m_rows, ch),
            },
            "none",
        );
    }

    let (supported, dma_tag, comp_rc, exec_rc, elapsed_ms, hw_us, drv_us) = run_nnapi_compiled_model(
        api,
        model,
        layers,
        dev,
        &act_buf,
        &mut out_buf,
        burst_iters,
    );
    (api.model_free)(model);
    drop(all_weights);
    drop(all_biases);

    if comp_rc != 0 || exec_rc != 0 {
        return (
            TpuGraphBenchRow {
                kernel_id: kernel_id.to_string(),
                device_name: dev_name.to_string(),
                device_type: dev_type,
                is_hw_tpu,
                supported,
                compile_rc: comp_rc,
                exec_rc,
                matched: 0,
                elements: elems as u32,
                burst_iters,
                elapsed_ms: 0.0,
                hw_us,
                drv_us,
                melem_per_sec: 0.0,
                gops_per_sec: 0.0,
                hw_on_die_gops: 0.0,
                detail: format!("[{}x{}]x{} compile={} exec={}", m_rows, ch, layers, nnapi_rc_name(comp_rc), nnapi_rc_name(exec_rc)),
            },
            dma_tag,
        );
    }

    let mut matched = 0u32;
    let mut exact0 = 0u32;
    for idx in 0..elems {
        let d = (out_buf[idx] as i32 - exp_buf[idx] as i32).abs();
        if d == 0 {
            exact0 += 1;
        }
        if d <= 1 {
            matched += 1;
        }
    }
    let sec = (elapsed_ms / 1000.0).max(1e-6);
    let gops = (ops_per_iter * (burst_iters.max(1) as f64)) / (sec * 1e9);
    let melem = ((elems as f64) * (burst_iters.max(1) as f64)) / (sec * 1e6);
    let hw_die_gops = if hw_us > 5.0 {
        ops_per_iter / ((hw_us / 1e6) * 1e9)
    } else {
        0.0
    };
    let t_tag = match (hw_us >= 0.0, drv_us >= 0.0) {
        (true, true) => format!("hw={:.1}us/drv={:.1}us", hw_us, drv_us),
        (true, false) => format!("hw={:.1}us", hw_us),
        _ => "hw_ok".to_string(),
    };
    let det = format!(
        "{} {}-Layer Fused FC w8a8o8 [{}x{}]x{} ({:.3} TOPS/s, {}x {}, {}, exact0={}/{})",
        dev_name,
        layers,
        m_rows,
        ch,
        layers,
        gops / 1000.0,
        burst_iters,
        dma_tag,
        t_tag,
        exact0,
        elems
    );

    (
        TpuGraphBenchRow {
            kernel_id: kernel_id.to_string(),
            device_name: dev_name.to_string(),
            device_type: dev_type,
            is_hw_tpu,
            supported,
            compile_rc: 0,
            exec_rc: 0,
            matched,
            elements: elems as u32,
            burst_iters,
            elapsed_ms,
            hw_us,
            drv_us,
            melem_per_sec: melem,
            gops_per_sec: gops,
            hw_on_die_gops: hw_die_gops,
            detail: det,
        },
        dma_tag,
    )
}

unsafe fn bench_tpu_fc_16l_q8(
    api: &DynNnapiApi,
    dev: *const c_void,
    dev_name: &str,
    dev_type: i32,
    is_hw_tpu: bool,
    burst_iters: u32,
    prefix: &str,
) -> (TpuGraphBenchRow, &'static str) {
    // Every shape below satisfies M <= 512 (proven compile=NO_ERROR(0) on Pixel 10 google-edgetpu!)
    let cands: [(usize, usize, usize); 5] = [
        (512, 512, 16), // 4.295 GOPS/call (compiled rc=0 in Screenshot 400!)
        (512, 256, 16), // 1.00 MB weights, 1.074 GOPS/call
        (512, 256, 8),  // 0.50 MB weights
        (256, 256, 8),  // 0.50 MB weights, M=256
        (512, 512, 1),  // Proven 262144/262144 PASS in Screenshot 394!
    ];
    let mut last_res: Option<(TpuGraphBenchRow, &'static str)> = None;
    for &(m_rows, ch, layers) in &cands {
        let kid = format!("K12_{}_FC_{}L_Q8", prefix, layers);
        let (row, tag) = bench_tpu_fc_q8_shape(api, dev, dev_name, dev_type, is_hw_tpu, m_rows, ch, layers, burst_iters, &kid);
        if row.compile_rc == 0 && row.exec_rc == 0 && row.matched == row.elements {
            return (row, tag);
        }
        last_res = Some((row, tag));
    }
    last_res.unwrap()
}

unsafe fn bench_tpu_fc_fp16_shape(
    api: &DynNnapiApi,
    dev: *const c_void,
    dev_name: &str,
    dev_type: i32,
    is_hw_tpu: bool,
    m_rows: usize,
    ch: usize,
    layers: usize,
    burst_iters: u32,
    kernel_id: &str,
) -> (TpuGraphBenchRow, &'static str) {
    // Hardware-verified EdgeTPU FP16 FULLY_CONNECTED batch constraint: m_rows <= 512!
    let groups: usize = ch / 8;
    let elems: usize = m_rows * ch;
    let ops_per_iter: f64 = (layers as f64) * (m_rows as f64) * (ch as f64) * (ch as f64) * 2.0;

    let mut act_bytes = vec![0u8; elems * 2];
    let mut out_bytes = vec![0u8; elems * 2];
    let mut v_state = vec![0i32; m_rows * groups];

    for r in 0..m_rows {
        for g in 0..groups {
            let dv = (((r * 5 + g * 9) % 5) as i32) - 2;
            v_state[r * groups + g] = dv;
            let h = i32_to_f16_exact(dv).to_le_bytes();
            let base = (r * ch + g * 8) * 2;
            for lane in 0..8usize {
                act_bytes[base + lane * 2] = h[0];
                act_bytes[base + lane * 2 + 1] = h[1];
            }
        }
    }

    let fp16_pos = f32_to_f16_exact_pow2(0.125).to_le_bytes();
    let fp16_neg = f32_to_f16_exact_pow2(-0.125).to_le_bytes();
    let mut all_weights: Vec<Vec<u8>> = Vec::with_capacity(layers);
    let mut all_biases: Vec<Vec<u8>> = Vec::with_capacity(layers);
    for l in 0..layers {
        let mut w_l = vec![0u8; ch * ch * 2];
        let mut b_l = vec![0u8; ch * 2];
        for go in 0..groups {
            let g1 = (go + 3 * l + 1) % groups;
            let db = (((go + l) % 3) as i32) - 1;
            let hb = i32_to_f16_exact(db).to_le_bytes();
            for lane_o in 0..8usize {
                let o = go * 8 + lane_o;
                b_l[o * 2] = hb[0];
                b_l[o * 2 + 1] = hb[1];
                let flip = (go + l + lane_o) & 1;
                let row_base = o * ch * 2;
                for gi in 0..groups {
                    let c_base = row_base + gi * 8 * 2;
                    if gi == g1 {
                        for lane_i in 0..8usize {
                            w_l[c_base + lane_i * 2] = fp16_pos[0];
                            w_l[c_base + lane_i * 2 + 1] = fp16_pos[1];
                        }
                    } else {
                        for lane_i in 0..8usize {
                            let bits = if ((lane_i + flip) & 1) == 0 { fp16_pos } else { fp16_neg };
                            w_l[c_base + lane_i * 2] = bits[0];
                            w_l[c_base + lane_i * 2 + 1] = bits[1];
                        }
                    }
                }
            }
        }
        let mut v_next = vec![0i32; m_rows * groups];
        for r in 0..m_rows {
            for go in 0..groups {
                let g1 = (go + 3 * l + 1) % groups;
                let db = (((go + l) % 3) as i32) - 1;
                v_next[r * groups + go] = v_state[r * groups + g1] + db;
            }
        }
        v_state = v_next;
        all_weights.push(w_l);
        all_biases.push(b_l);
    }

    let mut exp_i32 = vec![0i32; elems];
    for r in 0..m_rows {
        for go in 0..groups {
            let v = v_state[r * groups + go];
            let base = r * ch + go * 8;
            for lane in 0..8usize {
                exp_i32[base + lane] = v;
            }
        }
    }

    let mut model: *mut c_void = null_mut();
    if (api.model_create)(&mut model) != NNAPI_NO_ERROR || model.is_null() {
        return (
            TpuGraphBenchRow {
                kernel_id: kernel_id.to_string(),
                device_name: dev_name.to_string(),
                device_type: dev_type,
                is_hw_tpu,
                supported: false,
                compile_rc: -2,
                exec_rc: -1,
                matched: 0,
                elements: elems as u32,
                burst_iters,
                elapsed_ms: 0.0,
                hw_us: -1.0,
                drv_us: -1.0,
                melem_per_sec: 0.0,
                gops_per_sec: 0.0,
                hw_on_die_gops: 0.0,
                detail: "Model_create failed".to_string(),
            },
            "none",
        );
    }

    let dims_act: [u32; 2] = [m_rows as u32, ch as u32];
    let dims_w: [u32; 2] = [ch as u32, ch as u32];
    let dims_1d: [u32; 1] = [ch as u32];
    let op_in = NnapiOperandType {
        operand_type: NNAPI_TENSOR_FLOAT16,
        dimension_count: 2,
        dimensions: dims_act.as_ptr(),
        scale: 0.0,
        zero_point: 0,
    };
    let op_w = NnapiOperandType {
        operand_type: NNAPI_TENSOR_FLOAT16,
        dimension_count: 2,
        dimensions: dims_w.as_ptr(),
        scale: 0.0,
        zero_point: 0,
    };
    let op_bias = NnapiOperandType {
        operand_type: NNAPI_TENSOR_FLOAT16,
        dimension_count: 1,
        dimensions: dims_1d.as_ptr(),
        scale: 0.0,
        zero_point: 0,
    };
    let op_i32 = NnapiOperandType {
        operand_type: NNAPI_INT32,
        dimension_count: 0,
        dimensions: null(),
        scale: 0.0,
        zero_point: 0,
    };
    let fuse_none: i32 = NNAPI_FUSED_NONE;

    let mut next_idx: u32 = 0;
    let idx_fuse = next_idx; next_idx += 1;
    let idx_in0 = next_idx; next_idx += 1;
    let mut built = (api.model_add_operand)(model, &op_i32) == 0
        && (api.model_set_operand_value)(model, idx_fuse as i32, &fuse_none as *const i32 as *const c_void, 4) == 0
        && (api.model_add_operand)(model, &op_in) == 0;
    let mut cur_act_idx = idx_in0;

    for l in 0..layers {
        let idx_w = next_idx; next_idx += 1;
        let idx_b = next_idx; next_idx += 1;
        let idx_out = next_idx; next_idx += 1;
        built = built
            && (api.model_add_operand)(model, &op_w) == 0
            && (api.model_add_operand)(model, &op_bias) == 0
            && (api.model_add_operand)(model, &op_in) == 0
            && (api.model_set_operand_value)(model, idx_w as i32, all_weights[l].as_ptr() as *const c_void, all_weights[l].len()) == 0
            && (api.model_set_operand_value)(model, idx_b as i32, all_biases[l].as_ptr() as *const c_void, all_biases[l].len()) == 0
            && (api.model_add_operation)(
                model,
                NNAPI_OP_FULLY_CONNECTED,
                4,
                [cur_act_idx, idx_w, idx_b, idx_fuse].as_ptr(),
                1,
                [idx_out].as_ptr(),
            ) == 0;
        cur_act_idx = idx_out;
    }

    built = built
        && (api.model_identify_io)(model, 1, [idx_in0].as_ptr(), 1, [cur_act_idx].as_ptr()) == 0
        && (api.model_finish)(model) == 0;

    if !built {
        (api.model_free)(model);
        return (
            TpuGraphBenchRow {
                kernel_id: kernel_id.to_string(),
                device_name: dev_name.to_string(),
                device_type: dev_type,
                is_hw_tpu,
                supported: false,
                compile_rc: -2,
                exec_rc: -1,
                matched: 0,
                elements: elems as u32,
                burst_iters,
                elapsed_ms: 0.0,
                hw_us: -1.0,
                drv_us: -1.0,
                melem_per_sec: 0.0,
                gops_per_sec: 0.0,
                hw_on_die_gops: 0.0,
                detail: format!("{}L FC FP16 [{}x{}] build failed", layers, m_rows, ch),
            },
            "none",
        );
    }

    let (supported, dma_tag, comp_rc, exec_rc, elapsed_ms, hw_us, drv_us) = run_nnapi_compiled_model(
        api,
        model,
        layers,
        dev,
        &act_bytes,
        &mut out_bytes,
        burst_iters,
    );
    (api.model_free)(model);
    drop(all_weights);
    drop(all_biases);

    if comp_rc != 0 || exec_rc != 0 {
        return (
            TpuGraphBenchRow {
                kernel_id: kernel_id.to_string(),
                device_name: dev_name.to_string(),
                device_type: dev_type,
                is_hw_tpu,
                supported,
                compile_rc: comp_rc,
                exec_rc,
                matched: 0,
                elements: elems as u32,
                burst_iters,
                elapsed_ms: 0.0,
                hw_us,
                drv_us,
                melem_per_sec: 0.0,
                gops_per_sec: 0.0,
                hw_on_die_gops: 0.0,
                detail: format!("[{}x{}]x{} compile={} exec={}", m_rows, ch, layers, nnapi_rc_name(comp_rc), nnapi_rc_name(exec_rc)),
            },
            dma_tag,
        );
    }

    let mut matched = 0u32;
    for idx in 0..elems {
        let u = u16::from_le_bytes([out_bytes[idx * 2], out_bytes[idx * 2 + 1]]);
        let got = f16_to_f32_exact(u);
        let exp = exp_i32[idx] as f32;
        if (got - exp).abs() <= 0.05 {
            matched += 1;
        }
    }
    let sec = (elapsed_ms / 1000.0).max(1e-6);
    let gops = (ops_per_iter * (burst_iters.max(1) as f64)) / (sec * 1e9);
    let melem = ((elems as f64) * (burst_iters.max(1) as f64)) / (sec * 1e6);
    let hw_die_gops = if hw_us > 5.0 {
        ops_per_iter / ((hw_us / 1e6) * 1e9)
    } else {
        0.0
    };
    let t_tag = match (hw_us >= 0.0, drv_us >= 0.0) {
        (true, true) => format!("hw={:.1}us/drv={:.1}us", hw_us, drv_us),
        (true, false) => format!("hw={:.1}us", hw_us),
        _ => "hw_ok".to_string(),
    };
    let det = format!(
        "{} {}-Layer Fused FC IEEE-FP16 [{}x{}]x{} ({:.2} GOPS/s, {}x {}, {})",
        dev_name, layers, m_rows, ch, layers, gops, burst_iters, dma_tag, t_tag
    );

    (
        TpuGraphBenchRow {
            kernel_id: kernel_id.to_string(),
            device_name: dev_name.to_string(),
            device_type: dev_type,
            is_hw_tpu,
            supported,
            compile_rc: 0,
            exec_rc: 0,
            matched,
            elements: elems as u32,
            burst_iters,
            elapsed_ms,
            hw_us,
            drv_us,
            melem_per_sec: melem,
            gops_per_sec: gops,
            hw_on_die_gops: hw_die_gops,
            detail: det,
        },
        dma_tag,
    )
}

unsafe fn bench_tpu_fc_16l_fp16(
    api: &DynNnapiApi,
    dev: *const c_void,
    dev_name: &str,
    dev_type: i32,
    is_hw_tpu: bool,
    burst_iters: u32,
    prefix: &str,
) -> (TpuGraphBenchRow, &'static str) {
    // Every shape below satisfies M <= 512 (proven compile=NO_ERROR(0) in Screenshot 400 & PASS in Screenshot 394!)
    let cands: [(usize, usize, usize); 5] = [
        (512, 256, 16), // 1.074 GOPS/call (compiled rc=0 in Screenshot 400!)
        (512, 256, 8),  // 1.00 MB weights
        (256, 256, 16), // M=256, 16 layers
        (256, 256, 8),  // 1.00 MB weights, M=256
        (256, 256, 1),  // Proven 65536/65536 PASS in Screenshot 394!
    ];
    let mut last_res: Option<(TpuGraphBenchRow, &'static str)> = None;
    for &(m_rows, ch, layers) in &cands {
        let kid = format!("K13_{}_FC_{}L_FP16", prefix, layers);
        let (row, tag) = bench_tpu_fc_fp16_shape(api, dev, dev_name, dev_type, is_hw_tpu, m_rows, ch, layers, burst_iters, &kid);
        if row.compile_rc == 0 && row.exec_rc == 0 && row.matched == row.elements {
            return (row, tag);
        }
        last_res = Some((row, tag));
    }
    last_res.unwrap()
}


fn fast_dispatch_tpu_conv2d(burst_iters: u32) -> (bool, String, u32, u32, f64, f64, f64, f64, String) {
    let api = match DynNnapiApi::open() {
        Ok(a) => a,
        Err(e) => return (false, "none".to_string(), 0, 1048576, 0.0, -1.0, -1.0, 0.0, e),
    };
    unsafe {
        let mut num_devs: u32 = 0;
        if (api.get_device_count)(&mut num_devs) != NNAPI_NO_ERROR {
            return (false, "none".to_string(), 0, 1048576, 0.0, -1.0, -1.0, 0.0, "getDeviceCount failed".to_string());
        }
        for idx in 0..num_devs {
            let mut dev_ptr: *mut c_void = null_mut();
            if (api.get_device)(idx, &mut dev_ptr) != NNAPI_NO_ERROR || dev_ptr.is_null() {
                continue;
            }
            let mut nm_ptr: *const u8 = null();
            let mut dtype: i32 = 0;
            let _ = (api.dev_get_name)(dev_ptr, &mut nm_ptr);
            let _ = (api.dev_get_type)(dev_ptr, &mut dtype);
            let name = cstr_ptr_to_string(nm_ptr, 128);
            if dtype == NNAPI_DEVICE_CPU {
                continue;
            }
            let tpu_like = is_tpu_like_device(&name, dtype);
            if tpu_like {
                let (r, _dma) = bench_tpu_conv2d_16l_q8(&api, dev_ptr, &name, dtype, true, burst_iters.max(1), "TPU");
                let ok = r.compile_rc == 0 && r.exec_rc == 0 && r.matched == r.elements;
                return (ok, name, r.matched, r.elements, r.elapsed_ms, r.hw_us, r.drv_us, r.gops_per_sec, r.detail);
            }
        }
    }
    (false, "none".to_string(), 0, 1048576, 0.0, -1.0, -1.0, 0.0, "No hardware TPU device found".to_string())
}

fn probe_and_bench_tpu_npu(run_benchmarks: bool) -> TpuNpuReport {
    let (soc_props, thermal_and_freq, buenos_sysfs, kernel_nodes) = probe_tpu_kernel_and_sysfs();
    let (public_vendor_libs, vintf_hals, vendor_libs) = probe_vendor_tpu_libraries();

    let mut rep = TpuNpuReport {
        nnapi_loaded: false,
        nnapi_loader_note: String::new(),
        hw_tpu_enumerated: false,
        hw_tpu_unlocked: false,
        zero_copy_memfd_active: false,
        tpu_device_name: String::new(),
        soc_props,
        thermal_and_freq,
        buenos_sysfs,
        public_vendor_libs,
        vintf_hals,
        kernel_nodes,
        vendor_libs,
        nnapi_devices: Vec::new(),
        bench_rows: Vec::new(),
        peak_tpu_gops: 0.0,
        peak_hw_on_die_gops: 0.0,
        summary_line: String::new(),
    };

    let api = match DynNnapiApi::open() {
        Ok(a) => {
            rep.nnapi_loaded = true;
            rep.nnapi_loader_note = "libneuralnetworks.so C ABI + 3-Tier Hardware DMA Waterfall loaded".to_string();
            a
        }
        Err(e) => {
            rep.nnapi_loader_note = e.clone();
            rep.summary_line = e;
            return rep;
        }
    };

    unsafe {
        let mut num_devs: u32 = 0;
        let rc_cnt = (api.get_device_count)(&mut num_devs);
        if rc_cnt != NNAPI_NO_ERROR {
            rep.nnapi_loader_note = format!("ANeuralNetworks_getDeviceCount failed: {}", nnapi_rc_name(rc_cnt));
            rep.summary_line = rep.nnapi_loader_note.clone();
            return rep;
        }

        let mut raw_devs: Vec<(u32, *mut c_void, String, String, i32, i64, bool)> = Vec::new();
        for idx in 0..num_devs {
            let mut dev_ptr: *mut c_void = null_mut();
            if (api.get_device)(idx, &mut dev_ptr) != NNAPI_NO_ERROR || dev_ptr.is_null() {
                continue;
            }
            let mut nm_ptr: *const u8 = null();
            let mut vr_ptr: *const u8 = null();
            let mut dtype: i32 = 0;
            let mut flevel_buf: i64 = 0;
            let _ = (api.dev_get_name)(dev_ptr, &mut nm_ptr);
            let _ = (api.dev_get_version)(dev_ptr, &mut vr_ptr);
            let _ = (api.dev_get_type)(dev_ptr, &mut dtype);
            let _ = (api.dev_get_feature_level)(dev_ptr, &mut flevel_buf);
            let name = cstr_ptr_to_string(nm_ptr, 128);
            let ver = cstr_ptr_to_string(vr_ptr, 128);
            let flevel = flevel_buf & 0xFFFF_FFFF;
            let tpu_like = is_tpu_like_device(&name, dtype);
            if tpu_like && !rep.hw_tpu_enumerated {
                rep.hw_tpu_enumerated = true;
                rep.tpu_device_name = name.clone();
            }
            let mode_note = if dtype == NNAPI_DEVICE_CPU {
                "CPU_REF_FALLBACK(bypassed)".to_string()
            } else {
                "SYSTOLIC_INT8_FP16_TARGET".to_string()
            };
            rep.nnapi_devices.push(NnapiDeviceDesc {
                index: idx,
                name: name.clone(),
                version: ver.clone(),
                dev_type: dtype,
                type_label: nnapi_dev_type_label(dtype).to_string(),
                feature_level: flevel,
                ops_supported: mode_note,
            });
            raw_devs.push((idx, dev_ptr, name, ver, dtype, flevel, tpu_like));
        }

        let mut active_dma_label = "nnapi_burst";
        let mut tpu_pass_cnt: usize = 0;
        let mut tpu_tot_cnt: usize = 0;

        if run_benchmarks {
            for (d_pos, (_idx, dev_ptr, name, _ver, dtype, _fl, tpu_like)) in raw_devs.iter().enumerate() {
                if *dtype == NNAPI_DEVICE_CPU {
                    continue;
                }
                let prefix = if *tpu_like {
                    "TPU"
                } else if *dtype == NNAPI_DEVICE_GPU {
                    "NNAPI_GPU"
                } else {
                    "NNAPI_HW"
                };
                let (r_conv, dma1) = bench_tpu_conv2d_16l_q8(&api, *dev_ptr, name, *dtype, *tpu_like, 16, prefix);
                let (r_fc8, dma2) = bench_tpu_fc_16l_q8(&api, *dev_ptr, name, *dtype, *tpu_like, 16, prefix);
                let (r_fcf16, dma3) = bench_tpu_fc_16l_fp16(&api, *dev_ptr, name, *dtype, *tpu_like, 16, prefix);

                for tag in [dma1, dma2, dma3] {
                    if tag == "driver_mem_desc" || tag == "ashmem_zero_copy" {
                        rep.zero_copy_memfd_active = true;
                        active_dma_label = tag;
                    }
                }

                if let Some(d_desc) = rep.nnapi_devices.get_mut(d_pos) {
                    d_desc.ops_supported = format!(
                        "CONV2D_Q8:{}(rc={}/{}) | FC_Q8:{}(rc={}/{}) | FC_FP16:{}(rc={}/{}) | DMA={}",
                        if r_conv.exec_rc == 0 { "PASS" } else { "diag" },
                        r_conv.compile_rc,
                        r_conv.exec_rc,
                        if r_fc8.exec_rc == 0 { "PASS" } else { "diag" },
                        r_fc8.compile_rc,
                        r_fc8.exec_rc,
                        if r_fcf16.exec_rc == 0 { "PASS" } else { "diag" },
                        r_fcf16.compile_rc,
                        r_fcf16.exec_rc,
                        active_dma_label
                    );
                }

                for r in [r_conv, r_fc8, r_fcf16] {
                    if r.is_hw_tpu {
                        tpu_tot_cnt += 1;
                    }
                    if r.compile_rc == 0 && r.exec_rc == 0 && r.matched == r.elements {
                        if r.is_hw_tpu {
                            tpu_pass_cnt += 1;
                            rep.hw_tpu_unlocked = true;
                            if r.gops_per_sec > rep.peak_tpu_gops {
                                rep.peak_tpu_gops = r.gops_per_sec;
                            }
                            if r.hw_on_die_gops > rep.peak_hw_on_die_gops {
                                rep.peak_hw_on_die_gops = r.hw_on_die_gops;
                            }
                        }
                    }
                    rep.bench_rows.push(r);
                }
            }
        }

        if rep.hw_tpu_unlocked {
            rep.summary_line = format!(
                "HW TPU UNLOCKED ({} / 36500000.buenos) :: Fused Systolic Peak={:.2} GOPS/s ({:.3} TOPS/s, DMA={}) | {}/{} TPU Kernels 100% Exact!",
                rep.tpu_device_name,
                rep.peak_tpu_gops,
                rep.peak_tpu_gops / 1000.0,
                active_dma_label,
                tpu_pass_cnt,
                tpu_tot_cnt.max(1)
            );
        } else if rep.hw_tpu_enumerated {
            rep.summary_line = format!("TPU Enumerated ({}) -- awaiting compilation", rep.tpu_device_name);
        } else {
            rep.summary_line = format!("NNAPI Devices={}", rep.nnapi_devices.len());
        }
    }

    rep
}

fn format_tpu_json(t: &TpuNpuReport) -> String {
    let pub_js: Vec<String> = t.public_vendor_libs.iter().map(|s| format!("\"{}\"", json_esc(s))).collect();
    let vin_js: Vec<String> = t.vintf_hals.iter().map(|s| format!("\"{}\"", json_esc(s))).collect();
    let nod_js: Vec<String> = t
        .kernel_nodes
        .iter()
        .map(|n| {
            format!(
                "{{\"path\":\"{}\",\"exists\":{},\"perms\":\"{}\",\"open\":\"{}\"}}",
                json_esc(&n.path),
                if n.exists { "true" } else { "false" },
                json_esc(&n.perms),
                json_esc(&n.open_status)
            )
        })
        .collect();
    let lib_js: Vec<String> = t
        .vendor_libs
        .iter()
        .map(|l| {
            let syms: Vec<String> = l.exported_syms.iter().map(|s| format!("\"{}\"", json_esc(s))).collect();
            format!(
                "{{\"path\":\"{}\",\"exists\":{},\"size_kb\":{},\"public_whitelisted\":{},\"dlopen_ok\":{},\"dlopen_note\":\"{}\",\"exported_syms\":[{}]}}",
                json_esc(&l.path),
                if l.exists { "true" } else { "false" },
                l.size_kb,
                if l.public_whitelisted { "true" } else { "false" },
                if l.dlopen_ok { "true" } else { "false" },
                json_esc(&l.dlopen_note),
                syms.join(",")
            )
        })
        .collect();
    let dev_js: Vec<String> = t
        .nnapi_devices
        .iter()
        .map(|d| {
            format!(
                "{{\"index\":{},\"name\":\"{}\",\"version\":\"{}\",\"type\":{},\"type_label\":\"{}\",\"feature_level\":{},\"ops_supported\":\"{}\"}}",
                d.index,
                json_esc(&d.name),
                json_esc(&d.version),
                d.dev_type,
                json_esc(&d.type_label),
                d.feature_level,
                json_esc(&d.ops_supported)
            )
        })
        .collect();
    let row_js: Vec<String> = t
        .bench_rows
        .iter()
        .map(|r| {
            format!(
                "{{\"kernel_id\":\"{}\",\"device\":\"{}\",\"device_type\":{},\"is_hw_tpu\":{},\"supported\":{},\"compile_rc\":{},\"exec_rc\":{},\"matched\":{},\"elements\":{},\"burst_iters\":{},\"elapsed_ms\":{:.2},\"hw_us\":{:.1},\"drv_us\":{:.1},\"melem_s\":{:.1},\"gops_s\":{:.2},\"detail\":\"{}\"}}",
                json_esc(&r.kernel_id),
                json_esc(&r.device_name),
                r.device_type,
                if r.is_hw_tpu { "true" } else { "false" },
                if r.supported { "true" } else { "false" },
                r.compile_rc,
                r.exec_rc,
                r.matched,
                r.elements,
                r.burst_iters,
                r.elapsed_ms,
                r.hw_us,
                r.drv_us,
                r.melem_per_sec,
                r.gops_per_sec,
                json_esc(&r.detail)
            )
        })
        .collect();
    format!(
        "{{\"nnapi_loaded\":{},\"nnapi_note\":\"{}\",\"hw_tpu_enumerated\":{},\"hw_tpu_unlocked\":{},\"zero_copy_memfd\":{},\"tpu_device\":\"{}\",\"peak_tpu_gops\":{:.2},\"summary\":\"{}\",\"soc_props\":\"{}\",\"thermal_and_freq\":\"{}\",\"buenos_sysfs\":\"{}\",\"public_vendor_libs\":[{}],\"vintf_hals\":[{}],\"kernel_nodes\":[{}],\"vendor_libs\":[{}],\"nnapi_devices\":[{}],\"benchmarks\":[{}]}}",
        if t.nnapi_loaded { "true" } else { "false" },
        json_esc(&t.nnapi_loader_note),
        if t.hw_tpu_enumerated { "true" } else { "false" },
        if t.hw_tpu_unlocked { "true" } else { "false" },
        if t.zero_copy_memfd_active { "true" } else { "false" },
        json_esc(&t.tpu_device_name),
        t.peak_tpu_gops,
        json_esc(&t.summary_line),
        json_esc(&t.soc_props),
        json_esc(&t.thermal_and_freq),
        json_esc(&t.buenos_sysfs),
        pub_js.join(","),
        vin_js.join(","),
        nod_js.join(","),
        lib_js.join(","),
        dev_js.join(","),
        row_js.join(",")
    )
}

fn print_tpu_block(t: &TpuNpuReport, indent: &str) {
    println!("{}[TPU-SOC]  Props={} | MMIO={}", indent, t.soc_props, t.thermal_and_freq);
    println!("{}[TPU-SYS]  Buenos Sysfs :: {}", indent, t.buenos_sysfs);
    let node_s: Vec<String> = t
        .kernel_nodes
        .iter()
        .map(|n| format!("{}={}", n.path, n.open_status))
        .collect();
    if !node_s.is_empty() {
        println!("{}[TPU-DEV]  Kernel Nodes :: {}", indent, node_s.join(" | "));
    }
    for vl in &t.vendor_libs {
        if vl.exists {
            let sym_preview = if vl.exported_syms.is_empty() {
                "loaded".to_string()
            } else {
                let cap = vl.exported_syms.len().min(4);
                format!("syms[{}]: {}", vl.exported_syms.len(), vl.exported_syms[..cap].join(", "))
            };
            println!(
                "{}[TPU-VND]  {} ({} KB, pub={}, dl={}) | {}",
                indent, vl.path, vl.size_kb, vl.public_whitelisted, vl.dlopen_ok, sym_preview
            );
        }
    }
    if t.nnapi_loaded {
        for d in &t.nnapi_devices {
            println!(
                "{}[NNAPI-{}] {} (v={}, type={}, FL={}) :: {}",
                indent, d.index, d.name, d.version, d.type_label, d.feature_level, d.ops_supported
            );
        }
        for r in &t.bench_rows {
            let tag = if r.compile_rc == 0 && r.exec_rc == 0 && r.matched == r.elements {
                "TPU-PASS"
            } else {
                "TPU-DIAG"
            };
            println!(
                "{}  [{}] {:24} -> Parity={}/{} | {:8.2} GOPS/s ({:6.2} ms) | {}",
                indent, tag, r.kernel_id, r.matched, r.elements, r.gops_per_sec, r.elapsed_ms, r.detail
            );
        }
    }
    println!("{}[TPU-SUM]  {}", indent, t.summary_line);
}

#[derive(Clone)]
struct FullWorkerReport {
    sys: SysTopology,
    sensor: SensorCadenceReport,
    compute: ComputePoolReport,
    prime: PrimeLeaseReport,
    vulkan: VulkanSuiteReport,
    tpu: TpuNpuReport,
}

fn json_esc(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 8);
    for ch in s.chars() {
        match ch {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '\r' => out.push_str("\\r"),
            '\n' => out.push_str("\\n"),
            '\t' => out.push_str("\\t"),
            c => out.push(c),
        }
    }
    out
}

fn inject_hw_tpu_kernels(vulkan: &mut VulkanSuiteReport, tpu: &TpuNpuReport) {
    vulkan.kernels.retain(|k| !k.id.starts_with("K11_") && !k.id.starts_with("K12_") && !k.id.starts_with("K13_"));
    for r in &tpu.bench_rows {
        if (r.is_hw_tpu || r.device_type == NNAPI_DEVICE_GPU || r.device_type == NNAPI_DEVICE_ACCELERATOR)
            && r.compile_rc == 0
            && r.exec_rc == 0
            && r.elements > 0
            && r.matched == r.elements
        {
            vulkan.kernels.push(KernelScore {
                id: r.kernel_id.clone(),
                elements: r.elements,
                matched: r.matched,
                dispatches: r.burst_iters,
                elapsed_ms: r.elapsed_ms,
                melem_per_sec: r.melem_per_sec,
                gops_per_sec: r.gops_per_sec,
                detail: r.detail.clone(),
            });
        }
    }
}

fn run_full_bench() -> FullWorkerReport {
    let sys = probe_sys_topology();
    let sensor = bench_sensor_cadence_lane(8);
    let compute = bench_compute_pool_a725(240);
    let prime = bench_prime_chebyshev_lease(2000);
    let mut vulkan = run_vulkan_suite("all");
    let tpu = probe_and_bench_tpu_npu(true);
    inject_hw_tpu_kernels(&mut vulkan, &tpu);
    FullWorkerReport { sys, sensor, compute, prime, vulkan, tpu }
}

fn format_coop_tiles_json(tiles: &[CoopTileDesc]) -> String {
    let items: Vec<String> = tiles.iter().map(|t| {
        format!(
            "{{\"shape\":\"{}\",\"types\":\"{}\",\"scope\":\"{}\",\"saturating\":{},\"m\":{},\"n\":{},\"k\":{}}}",
            json_esc(&t.shape), json_esc(&t.types), json_esc(&t.scope),
            if t.saturating { "true" } else { "false" }, t.m, t.n, t.k
        )
    }).collect();
    format!("[{}]", items.join(","))
}

fn format_coop_summary_line(tiles: &[CoopTileDesc]) -> String {
    let mut uniq: Vec<String> = Vec::new();
    for t in tiles {
        if t.scope == "Subgroup" {
            let tag = format!("{}({})", t.shape, t.types);
            if !uniq.contains(&tag) && uniq.len() < 12 {
                uniq.push(tag);
            }
        }
    }
    if uniq.is_empty() {
        "0 Subgroup tiles".to_string()
    } else {
        uniq.join(" | ")
    }
}

fn format_vulkan_json(v: &VulkanSuiteReport) -> String {
    let badges: Vec<String> = v.ext_badges.iter().map(|b| format!("\"{}\"", json_esc(b))).collect();
    let ks: Vec<String> = v.kernels.iter().map(|k| {
        format!(
            "{{\"id\":\"{}\",\"parity\":\"{}/{}\",\"matched\":{},\"elements\":{},\"melem_s\":{:.2},\"gops_s\":{:.2},\"ms\":{:.2},\"elapsed_ms\":{:.2},\"detail\":\"{}\"}}",
            json_esc(&k.id), k.matched, k.elements, k.matched, k.elements, k.melem_per_sec, k.gops_per_sec, k.elapsed_ms, k.elapsed_ms, json_esc(&k.detail)
        )
    }).collect();
    format!(
        "{{\"available\":{},\"device\":\"{}\",\"api\":\"{}\",\"vendor\":\"{}\",\"subgroup_size\":{},\"subgroup_min\":{},\"subgroup_max\":{},\"subgroup_ops\":\"{}\",\"uma_heap_mb\":{},\"ext_total\":{},\"ext_badges\":[{}],\"intdot_hw_accel\":{},\"idot_mask\":\"{}\",\"idot_tune\":\"{}\",\"udot_tune\":\"{}\",\"coop_tune\":\"{}\",\"coop_tiles\":{},\"kernels\":[{}],\"note\":\"{}\"}}",
        if v.available { "true" } else { "false" },
        json_esc(&v.device_name), json_esc(&v.api_version), json_esc(&v.vendor_hex),
        v.subgroup_size, v.subgroup_min, v.subgroup_max, json_esc(&v.subgroup_ops_hex), v.uma_heap_mb, v.ext_total,
        badges.join(","),
        if v.intdot_hw_accel { "true" } else { "false" },
        json_esc(&v.idot_mask_hex),
        json_esc(&v.idot_tune_note),
        json_esc(&v.udot_tune_note),
        json_esc(&v.coop_tune_note),
        format_coop_tiles_json(&v.coop_tiles),
        ks.join(","), json_esc(&v.note)
    )
}

fn format_report_json(r: &FullWorkerReport, hb_ticks: u64, sensor_payload: &str) -> String {
    let freqs: Vec<String> = r.sys.max_khz.iter().map(|v| v.to_string()).collect();
    let isas: Vec<String> = r.sys.isa_badges.iter().map(|s| format!("\"{}\"", json_esc(s))).collect();
    let lanes: Vec<String> = r.compute.lane_cpus.iter().map(|s| format!("\"{}\"", json_esc(s))).collect();
    format!(
        "{{\"ok\":true,\"worker\":\"omega_p10_worker_v0.7.5\",\"arch\":\"{}\",\"os\":\"{}\",\"cores\":{},\"max_khz\":[{}],\"isa_features\":[{}],\"mem_total_mb\":{},\"mem_avail_mb\":{},\"heartbeat_ticks\":{},\"tpu_hw_unlocked\":{},\"tpu_peak_gops\":{:.2},\"tpu_summary\":\"{}\",\"lane_a520\":{{\"mask\":\"0x03\",\"cpus\":\"{}\",\"avg_period_us\":{:.2},\"max_jitter_us\":{}}},\"lane_a725\":{{\"mask\":\"0x7C\",\"pool_cpus\":\"{}\",\"worker_cpus\":[{}],\"sh4z_mops_s\":{:.2},\"udot_mops_s\":{:.2},\"e8_mvec_s\":{:.3},\"sheaf_h1_zero\":{},\"digest\":\"{}\"}},\"lane_x4\":{{\"mask\":\"0x80\",\"cpus\":\"{}\",\"chebyshev_m61_pass\":\"{}/{}\",\"avg_lease_ns\":{:.1},\"epoch\":{},\"lease_token\":\"{}\"}},\"vulkan\":{},\"tpu\":{},\"sensor_ring\":{}}}",
        json_esc(&r.sys.arch), json_esc(&r.sys.os_banner), r.sys.logical_cores,
        freqs.join(","), isas.join(","), r.sys.mem_total_mb, r.sys.mem_avail_mb, hb_ticks,
        if r.tpu.hw_tpu_unlocked { "true" } else { "false" }, r.tpu.peak_tpu_gops, json_esc(&r.tpu.summary_line),
        json_esc(&r.sensor.cpus_allowed), r.sensor.avg_period_us, r.sensor.max_jitter_us,
        json_esc(&r.compute.pool_cpus_allowed), lanes.join(","),
        r.compute.sh4z_mops_per_sec, r.compute.udot_mops_per_sec, r.compute.e8_mvec_per_sec,
        if r.compute.parity_h1_zero { "true" } else { "false" }, r.compute.digest_hex,
        json_esc(&r.prime.cpus_allowed), r.prime.commute_passed, r.prime.trials,
        r.prime.avg_lease_ns, r.prime.active_epoch, r.prime.lease_token_hex,
        format_vulkan_json(&r.vulkan),
        format_tpu_json(&r.tpu),
        if sensor_payload.trim().is_empty() { "{}" } else { sensor_payload.trim() }
    )
}

fn print_vulkan_block(v: &VulkanSuiteReport, indent: &str) {
    println!(
        "{}[VK-CAPS] {} (API {}, {}) | Subgroup={} [{}..{}] (ops {}) | UMA={} MB | Exts={} [{}]",
        indent, v.device_name, v.api_version, v.vendor_hex,
        v.subgroup_size, v.subgroup_min, v.subgroup_max, v.subgroup_ops_hex, v.uma_heap_mb,
        v.ext_total, v.ext_badges.join(", ")
    );
    if !v.idot_tune_note.is_empty() {
        println!("{}[VK-IDOT] IntDot 27-Prop & 3-Mode Tune :: {} (hw={})", indent, v.idot_tune_note, v.intdot_hw_accel);
    }
    if !v.udot_tune_note.is_empty() {
        println!("{}[VK-UDOT] UDot 0x0040008 3-Mode Tune   :: {} (ZP-u8 MSB=1)", indent, v.udot_tune_note);
    }
    if !v.coop_tiles.is_empty() {
        println!(
            "{}[VK-COOP] {} HW Tensor Tiles :: {}",
            indent, v.coop_tiles.len(), format_coop_summary_line(&v.coop_tiles)
        );
    }
    if !v.coop_tune_note.is_empty() {
        println!("{}[VK-TUNE] Calibrated 100% Parity :: {}", indent, v.coop_tune_note);
    }
    for k in &v.kernels {
        let tag = if k.matched == k.elements { "PASS" } else { "FAIL" };
        println!(
            "{}  [{}] {:19} -> Parity={}/{} | {:7.1} MElem/s ({:7.2} GOPS/s, {:5.2} ms) | {}",
            indent, tag, k.id, k.matched, k.elements, k.melem_per_sec, k.gops_per_sec, k.elapsed_ms, k.detail
        );
    }
}

fn print_human_scorecard(r: &FullWorkerReport) {
    println!("==============================================================================");
    if cfg!(all(target_os = "linux", target_arch = "aarch64")) {
        println!(" ACT-OMEGA AVF DEBIAN 13 (pKVM + TENSOR G5 NATIVE ARM64 RUST) WORKER v0.7.5");
    } else if cfg!(target_os = "windows") {
        println!(
            " ACT-OMEGA HOST x64 + RTX 3050 TENSOR COMPANION v0.7.5 [{} KERNELS]",
            r.vulkan.kernels.len()
        );
    } else {
        println!(
            " ACT-OMEGA PIXEL 10 (TENSOR G5 + POWERVR DXT-48-1536) WORKER v0.7.5 [{} KERNELS]",
            r.vulkan.kernels.len()
        );
    }
    println!("==============================================================================");
    println!("  [SYS] Arch/OS    : {} ({} cores | RAM {}/{} MB avail)", r.sys.os_banner, r.sys.logical_cores, r.sys.mem_avail_mb, r.sys.mem_total_mb);
    if !r.sys.isa_badges.is_empty() {
        println!("  [ISA] Silicon    : {}", r.sys.isa_badges.join(" "));
    }
    println!(
        "  [PASS] LANE 0x03 (2x A520 Clock)   -> Cpus={} | 15.965Hz avg={:.1}us (target 62636us, max_jitter={}us)",
        r.sensor.cpus_allowed, r.sensor.avg_period_us, r.sensor.max_jitter_us
    );
    println!(
        "  [PASS] LANE 0x7C (5x A725 SDOT/U8) -> Cpus={} {:?} | SH4Z={:.1} MOPS/s | UDOT={:.1} MOPS/s | E8={:.2} MVec/s | H^1=0:{}",
        r.compute.pool_cpus_allowed, r.compute.lane_cpus, r.compute.sh4z_mops_per_sec, r.compute.udot_mops_per_sec, r.compute.e8_mvec_per_sec, r.compute.parity_h1_zero
    );
    println!(
        "  [PASS] LANE 0x80 (1x X4 Prime)     -> Cpus={} | Chebyshev M61={}/{} | {:.1} ns/lease | Tok={}",
        r.prime.cpus_allowed, r.prime.commute_passed, r.prime.trials, r.prime.avg_lease_ns, r.prime.lease_token_hex
    );
    if r.vulkan.available {
        print_vulkan_block(&r.vulkan, "  ");
    } else {
        println!("  [INFO] VULKAN LOADER               -> {}", r.vulkan.note);
    }
    if cfg!(target_os = "android") || r.tpu.nnapi_loaded {
        print_tpu_block(&r.tpu, "  ");
    }
    println!("==============================================================================");
}

fn write_http_resp(mut stream: TcpStream, status: &str, content_type: &str, body: &str) {
    let hdr = format!(
        "HTTP/1.1 {}\r\nContent-Type: {}\r\nContent-Length: {}\r\nAccess-Control-Allow-Origin: *\r\nConnection: close\r\n\r\n",
        status, content_type, body.as_bytes().len()
    );
    let _ = stream.write_all(hdr.as_bytes());
    let _ = stream.write_all(body.as_bytes());
    let _ = stream.flush();
}

fn current_tier_tag() -> &'static str {
    if cfg!(all(target_os = "linux", target_arch = "aarch64")) {
        "avf_debian_virtio_gpu"
    } else if cfg!(target_os = "android") {
        "android_native_powervr"
    } else if cfg!(target_os = "windows") {
        "windows_host_rtx"
    } else {
        "linux_host"
    }
}

fn find_kernel_gops(v: &VulkanSuiteReport, prefix: &str) -> f64 {
    for k in &v.kernels {
        if k.id.starts_with(prefix) {
            return k.gops_per_sec;
        }
    }
    0.0
}


fn posix_ignore_hangup_and_pipe() {
    #[cfg(all(any(target_os = "android", target_os = "linux"), not(target_env = "musl")))]
    unsafe {
        let h = dlopen(b"libc.so\0".as_ptr(), 2);
        if !h.is_null() {
            let p_sig = dlsym(h, b"signal\0".as_ptr());
            if !p_sig.is_null() {
                type FnSignal = unsafe extern "C" fn(i32, usize) -> usize;
                let f_sig: FnSignal = core::mem::transmute(p_sig);
                let _ = f_sig(1, 1);  // SIGHUP -> SIG_IGN
                let _ = f_sig(13, 1); // SIGPIPE -> SIG_IGN
            }
        }
    }
}

fn posix_detach_daemonize(log_path: &[u8]) {
    #[cfg(all(any(target_os = "android", target_os = "linux"), not(target_env = "musl")))]
    unsafe {
        posix_ignore_hangup_and_pipe();
        let h = dlopen(b"libc.so\0".as_ptr(), 2);
        if h.is_null() {
            return;
        }
        let p_fork = dlsym(h, b"fork\0".as_ptr());
        let p_setsid = dlsym(h, b"setsid\0".as_ptr());
        let p_open = dlsym(h, b"open\0".as_ptr());
        let p_dup2 = dlsym(h, b"dup2\0".as_ptr());
        let p_close = dlsym(h, b"close\0".as_ptr());
        let p_exit = dlsym(h, b"_exit\0".as_ptr());
        if p_fork.is_null() || p_setsid.is_null() || p_exit.is_null() {
            return;
        }
        type FnFork = unsafe extern "C" fn() -> i32;
        type FnSetsid = unsafe extern "C" fn() -> i32;
        type FnOpen = unsafe extern "C" fn(*const u8, i32, u32) -> i32;
        type FnDup2 = unsafe extern "C" fn(i32, i32) -> i32;
        type FnClose = unsafe extern "C" fn(i32) -> i32;
        type FnExit = unsafe extern "C" fn(i32) -> !;

        let f_fork: FnFork = core::mem::transmute(p_fork);
        let f_setsid: FnSetsid = core::mem::transmute(p_setsid);
        let f_exit: FnExit = core::mem::transmute(p_exit);

        let pid1 = f_fork();
        if pid1 < 0 {
            return;
        }
        if pid1 > 0 {
            f_exit(0);
        }
        let _ = f_setsid();
        let pid2 = f_fork();
        if pid2 < 0 {
            return;
        }
        if pid2 > 0 {
            f_exit(0);
        }
        if !p_open.is_null() && !p_dup2.is_null() && !p_close.is_null() {
            let f_open: FnOpen = core::mem::transmute(p_open);
            let f_dup2: FnDup2 = core::mem::transmute(p_dup2);
            let f_close: FnClose = core::mem::transmute(p_close);
            let devnull = f_open(b"/dev/null\0".as_ptr(), 0, 0);
            if devnull >= 0 {
                let _ = f_dup2(devnull, 0);
                if devnull > 2 {
                    let _ = f_close(devnull);
                }
            }
            // O_WRONLY(1) | O_CREAT(0o100=64) | O_TRUNC(0o1000=512) = 577
            let logfd = f_open(log_path.as_ptr(), 577, 0o644);
            if logfd >= 0 {
                let _ = f_dup2(logfd, 1);
                let _ = f_dup2(logfd, 2);
                if logfd > 2 {
                    let _ = f_close(logfd);
                }
            }
        }
    }
    #[cfg(not(all(any(target_os = "android", target_os = "linux"), not(target_env = "musl"))))]
    {
        let _ = log_path;
    }
}

fn run_daemon(bind_ip: &str, port: u16) {
    posix_ignore_hangup_and_pipe();
    let resolved_ip = if bind_ip.is_empty() || bind_ip == "auto" {
        if cfg!(all(target_os = "linux", target_arch = "aarch64")) {
            "0.0.0.0"
        } else {
            "127.0.0.1"
        }
    } else {
        bind_ip
    };
    let addr = format!("{}:{}", resolved_ip, port);
    let listener = match TcpListener::bind(&addr) {
        Ok(l) => l,
        Err(e) => {
            eprintln!("[ERROR] Failed to bind {}: {}", addr, e);
            std::process::exit(2);
        }
    };

    let initial = Arc::new(Mutex::new(run_full_bench()));
    let sensor_json = Arc::new(Mutex::new("{\"source\":\"15.965Hz_A520_internal\",\"status\":\"LOCKED\"}".to_string()));
    let hb_ticks = Arc::new(AtomicU64::new(0));
    let hb_jitter_us = Arc::new(AtomicI64::new(0));
    let dispatch_jobs = Arc::new(AtomicU64::new(0));
    let running = Arc::new(AtomicBool::new(true));
    let tpu_hw_gate = Arc::new(Mutex::new((Instant::now() - Duration::from_secs(10), String::new())));
    let vk_hw_gate = Arc::new(Mutex::new((Instant::now() - Duration::from_secs(10), String::new())));
    let inflight_http = Arc::new(std::sync::atomic::AtomicUsize::new(0));

    {
        let ticks_ref = Arc::clone(&hb_ticks);
        let jit_ref = Arc::clone(&hb_jitter_us);
        let run_ref = Arc::clone(&running);
        thread::spawn(move || {
            let _ = pin_current_thread(MASK_SENSOR_A520);
            let t0 = Instant::now();
            let mut k: u64 = 1;
            let mut prev_us: u64 = 0;
            while run_ref.load(Ordering::Relaxed) {
                let target_us = k.saturating_mul(TARGET_PERIOD_US);
                let now_us = t0.elapsed().as_micros() as u64;
                if target_us > now_us + 1800 {
                    thread::sleep(Duration::from_micros(target_us - now_us - 1500));
                }
                while (t0.elapsed().as_micros() as u64) < target_us {
                    core::hint::spin_loop();
                }
                let actual_us = t0.elapsed().as_micros() as u64;
                let period = actual_us.saturating_sub(prev_us);
                prev_us = actual_us;
                jit_ref.store((period as i64) - (TARGET_PERIOD_US as i64), Ordering::Relaxed);
                ticks_ref.fetch_add(1, Ordering::Relaxed);
                k += 1;
            }
        });
    }

    println!(
        "[OMEGA P10 v0.7.5 DAEMON LIVE] http://{} (tier={}, Subgroup + IntDot + UDot + CoopMat Suite)",
        addr,
        current_tier_tag()
    );

    for incoming in listener.incoming() {
        if !running.load(Ordering::Relaxed) { break; }
        if let Ok(mut stream) = incoming {
            if inflight_http.load(Ordering::Relaxed) >= 16 {
                write_http_resp(stream, "503 Busy", "application/json; charset=utf-8", "{\"ok\":false,\"busy\":true}");
                continue;
            }
            inflight_http.fetch_add(1, Ordering::Relaxed);
            let inflight_guard = Arc::clone(&inflight_http);
            let initial = Arc::clone(&initial);
            let sensor_json = Arc::clone(&sensor_json);
            let hb_ticks = Arc::clone(&hb_ticks);
            let hb_jitter_us = Arc::clone(&hb_jitter_us);
            let dispatch_jobs = Arc::clone(&dispatch_jobs);
            let running = Arc::clone(&running);
            let tpu_hw_gate = Arc::clone(&tpu_hw_gate);
            let vk_hw_gate = Arc::clone(&vk_hw_gate);
            let _ = thread::Builder::new().stack_size(512 * 1024).spawn(move || {
                let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(move || {
            let _ = stream.set_read_timeout(Some(Duration::from_millis(3000)));
            let mut buf = [0u8; 8192];
            let n = stream.read(&mut buf).unwrap_or(0);
            if n == 0 { return; }
            let req = String::from_utf8_lossy(&buf[..n]);
            let first_line = req.lines().next().unwrap_or("");
            let mut parts = first_line.split_whitespace();
            let method = parts.next().unwrap_or("GET");
            let full_path = parts.next().unwrap_or("/");
            let (path, query) = match full_path.find('?') {
                Some(q) => (&full_path[..q], &full_path[q + 1..]),
                None => (full_path, ""),
            };
            let body_sep = req.find("\r\n\r\n").map(|i| i + 4).unwrap_or(req.len());
            let req_body = &req[body_sep..];

            if path == "/api/health" || path == "/health" {
                let snap = initial.lock().unwrap_or_else(|e| e.into_inner()).clone();
                let live_sys = probe_sys_topology();
                let k10_g = find_kernel_gops(&snap.vulkan, "K10_");
                let k7_g = find_kernel_gops(&snap.vulkan, "K7_");
                let js = format!(
                    "{{\"ok\":true,\"worker\":\"omega_p10_worker_v0.7.5\",\"tier\":\"{}\",\"port\":{},\"os\":\"{}\",\"soc_props\":\"{}\",\"device\":\"{}\",\"api\":\"{}\",\"idot_mask\":\"{}\",\"k10_udot_gops\":{:.2},\"k7_sdot_gops\":{:.2},\"udot_neon_gops\":{:.2},\"tpu_hw_unlocked\":{},\"tpu_peak_gops\":{:.2},\"tpu_summary\":\"{}\",\"kernels_count\":{},\"dispatch_jobs\":{},\"heartbeat_ticks\":{},\"last_jitter_us\":{},\"mem_avail_mb\":{},\"mem_total_mb\":{}}}",
                    current_tier_tag(),
                    port,
                    json_esc(&snap.sys.os_banner),
                    json_esc(&snap.tpu.soc_props),
                    json_esc(&snap.vulkan.device_name),
                    json_esc(&snap.vulkan.api_version),
                    json_esc(&snap.vulkan.idot_mask_hex),
                    k10_g,
                    k7_g,
                    snap.compute.udot_mops_per_sec / 1000.0,
                    if snap.tpu.hw_tpu_unlocked { "true" } else { "false" },
                    snap.tpu.peak_tpu_gops,
                    json_esc(&snap.tpu.summary_line),
                    snap.vulkan.kernels.len(),
                    dispatch_jobs.load(Ordering::Relaxed),
                    hb_ticks.load(Ordering::Relaxed),
                    hb_jitter_us.load(Ordering::Relaxed),
                    live_sys.mem_avail_mb,
                    live_sys.mem_total_mb
                );
                write_http_resp(stream, "200 OK", "application/json; charset=utf-8", &js);
            } else if path == "/api/tpu" || path == "/api/npu" {
                let want_fresh = query.contains("bench=1") || query.contains("refresh=1");
                let tpu_rep = if want_fresh {
                    let fresh_tpu = probe_and_bench_tpu_npu(true);
                    let mut guard = initial.lock().unwrap_or_else(|e| e.into_inner());
                    inject_hw_tpu_kernels(&mut guard.vulkan, &fresh_tpu);
                    guard.tpu = fresh_tpu.clone();
                    fresh_tpu
                } else {
                    initial.lock().unwrap_or_else(|e| e.into_inner()).tpu.clone()
                };
                let js = format!(
                    "{{\"ok\":true,\"worker\":\"omega_p10_worker_v0.7.5\",\"tier\":\"{}\",\"port\":{},\"tpu\":{}}}",
                    current_tier_tag(),
                    port,
                    format_tpu_json(&tpu_rep)
                );
                write_http_resp(stream, "200 OK", "application/json; charset=utf-8", &js);
            } else if path == "/api/dispatch/tpu_fast" {
                let mut tpu_gate = tpu_hw_gate.lock().unwrap_or_else(|e| e.into_inner());
                if !tpu_gate.1.is_empty() && tpu_gate.0.elapsed() < Duration::from_millis(220) {
                    let cached_js = tpu_gate.1.clone();
                    drop(tpu_gate);
                    write_http_resp(stream, "200 OK", "application/json; charset=utf-8", &cached_js);
                    return;
                }
                let (ok, dev_nm, matched, elems, el_ms, hw_us, drv_us, gops, det) = fast_dispatch_tpu_conv2d(6);
                let job_id = dispatch_jobs.fetch_add(1, Ordering::Relaxed) + 1;
                if ok && gops > 10.0 {
                    let mut guard = initial.lock().unwrap_or_else(|e| e.into_inner());
                    guard.tpu.hw_tpu_unlocked = true;
                    if gops > guard.tpu.peak_tpu_gops {
                        guard.tpu.peak_tpu_gops = gops;
                    }
                }
                let js = format!(
                    "{{\"ok\":{},\"job_id\":{},\"tier\":\"{}\",\"port\":{},\"tpu_device\":\"{}\",\"matched\":{},\"elements\":{},\"elapsed_ms\":{:.2},\"hw_us\":{:.1},\"drv_us\":{:.1},\"gops_s\":{:.2},\"peak_tpu_gops\":{:.2},\"detail\":\"{}\"}}",
                    if ok { "true" } else { "false" },
                    job_id,
                    current_tier_tag(),
                    port,
                    json_esc(&dev_nm),
                    matched,
                    elems,
                    el_ms,
                    hw_us,
                    drv_us,
                    gops,
                    gops,
                    json_esc(&det)
                );
                if ok {
                    tpu_gate.0 = Instant::now();
                    tpu_gate.1 = js.clone();
                }
                drop(tpu_gate);
                write_http_resp(stream, "200 OK", "application/json; charset=utf-8", &js);
            } else if path == "/api/dispatch/tpu" {
                let fresh_tpu = probe_and_bench_tpu_npu(true);
                let job_id = dispatch_jobs.fetch_add(1, Ordering::Relaxed) + 1;
                {
                    let mut guard = initial.lock().unwrap_or_else(|e| e.into_inner());
                    inject_hw_tpu_kernels(&mut guard.vulkan, &fresh_tpu);
                    guard.tpu = fresh_tpu.clone();
                }
                let js = format!(
                    "{{\"ok\":true,\"job_id\":{},\"tier\":\"{}\",\"port\":{},\"hw_tpu_enumerated\":{},\"hw_tpu_unlocked\":{},\"tpu_device\":\"{}\",\"peak_tpu_gops\":{:.2},\"summary\":\"{}\",\"tpu\":{}}}",
                    job_id,
                    current_tier_tag(),
                    port,
                    if fresh_tpu.hw_tpu_enumerated { "true" } else { "false" },
                    if fresh_tpu.hw_tpu_unlocked { "true" } else { "false" },
                    json_esc(&fresh_tpu.tpu_device_name),
                    fresh_tpu.peak_tpu_gops,
                    json_esc(&fresh_tpu.summary_line),
                    format_tpu_json(&fresh_tpu)
                );
                write_http_resp(stream, "200 OK", "application/json; charset=utf-8", &js);
            } else if path == "/api/dispatch/udot" || path == "/api/dispatch" {
                let mut filt = "udot";
                for kv in query.split('&') {
                    if let Some(v) = kv.strip_prefix("kernel=") {
                        if !v.is_empty() { filt = v; }
                    }
                }
                let mut vk_gate = vk_hw_gate.lock().unwrap_or_else(|e| e.into_inner());
                if filt == "udot" && !vk_gate.1.is_empty() && vk_gate.0.elapsed() < Duration::from_millis(240) {
                    let cached_vk = vk_gate.1.clone();
                    drop(vk_gate);
                    write_http_resp(stream, "200 OK", "application/json; charset=utf-8", &cached_vk);
                    return;
                }
                let vk_job = run_vulkan_suite(filt);
                let job_id = dispatch_jobs.fetch_add(1, Ordering::Relaxed) + 1;
                let mut k_id = "K10_HW_UDOT_PACK4U8".to_string();
                let mut k_match: u32 = 0;
                let mut k_elem: u32 = 131072;
                let mut k_ms: f64 = 0.0;
                let mut k_melem: f64 = 0.0;
                let mut k_gops: f64 = 0.0;
                let mut k_det = String::new();
                if let Some(last_k) = vk_job.kernels.last() {
                    k_id = last_k.id.clone();
                    k_match = last_k.matched;
                    k_elem = last_k.elements;
                    k_ms = last_k.elapsed_ms;
                    k_melem = last_k.melem_per_sec;
                    k_gops = last_k.gops_per_sec;
                    k_det = last_k.detail.clone();
                }
                // Update cached K10 / dispatched kernel inside initial snapshot so /api/status stays fresh!
                {
                    let mut guard = initial.lock().unwrap_or_else(|e| e.into_inner());
                    if !vk_job.udot_tune_note.is_empty() {
                        guard.vulkan.udot_tune_note = vk_job.udot_tune_note.clone();
                    }
                    for nk in &vk_job.kernels {
                        let mut updated = false;
                        for ek in &mut guard.vulkan.kernels {
                            if ek.id == nk.id {
                                *ek = nk.clone();
                                updated = true;
                                break;
                            }
                        }
                        if !updated {
                            guard.vulkan.kernels.push(nk.clone());
                        }
                    }
                }
                let js = format!(
                    "{{\"ok\":{},\"job_id\":{},\"tier\":\"{}\",\"port\":{},\"device\":\"{}\",\"kernel\":\"{}\",\"matched\":{},\"elements\":{},\"elapsed_ms\":{:.2},\"melem_s\":{:.1},\"gops_s\":{:.2},\"detail\":\"{}\",\"udot_tune\":\"{}\"}}",
                    if vk_job.available && k_match == k_elem { "true" } else { "false" },
                    job_id,
                    current_tier_tag(),
                    port,
                    json_esc(&vk_job.device_name),
                    json_esc(&k_id),
                    k_match,
                    k_elem,
                    k_ms,
                    k_melem,
                    k_gops,
                    json_esc(&k_det),
                    json_esc(&vk_job.udot_tune_note)
                );
                if vk_job.available && k_match == k_elem && filt == "udot" {
                    vk_gate.0 = Instant::now();
                    vk_gate.1 = js.clone();
                }
                drop(vk_gate);
                write_http_resp(stream, "200 OK", "application/json; charset=utf-8", &js);
            } else if path == "/api/status" || path == "/status" {
                let snap = initial.lock().unwrap_or_else(|e| e.into_inner()).clone();
                let sens = sensor_json.lock().unwrap_or_else(|e| e.into_inner()).clone();
                let js = format_report_json(&snap, hb_ticks.load(Ordering::Relaxed), &sens);
                write_http_resp(stream, "200 OK", "application/json; charset=utf-8", &js);
            } else if path == "/api/caps" {
                let sys = probe_sys_topology();
                let vk_caps = run_vulkan_suite("caps_only");
                let isas: Vec<String> = sys.isa_badges.iter().map(|s| format!("\"{}\"", json_esc(s))).collect();
                let js = format!(
                    "{{\"ok\":true,\"tier\":\"{}\",\"isa_features\":[{}],\"vulkan_caps\":{}}}",
                    current_tier_tag(),
                    isas.join(","),
                    format_vulkan_json(&vk_caps)
                );
                write_http_resp(stream, "200 OK", "application/json; charset=utf-8", &js);
            } else if path == "/api/coopmat" {
                let vk_cm = run_vulkan_suite("coopmat");
                let js = format!(
                    "{{\"ok\":true,\"tier\":\"{}\",\"device\":\"{}\",\"intdot_hw_accel\":{},\"coop_tune\":\"{}\",\"coop_tiles\":{},\"kernels\":{}}}",
                    current_tier_tag(),
                    json_esc(&vk_cm.device_name),
                    if vk_cm.intdot_hw_accel { "true" } else { "false" },
                    json_esc(&vk_cm.coop_tune_note),
                    format_coop_tiles_json(&vk_cm.coop_tiles),
                    format_vulkan_json(&vk_cm)
                );
                write_http_resp(stream, "200 OK", "application/json; charset=utf-8", &js);
            } else if path == "/api/vulkan" {
                let mut k_sel = "all";
                for kv in query.split('&') {
                    if let Some(v) = kv.strip_prefix("kernel=") { k_sel = v; }
                }
                let vk_res = run_vulkan_suite(k_sel);
                let js = format!("{{\"ok\":true,\"tier\":\"{}\",\"vulkan\":{}}}", current_tier_tag(), format_vulkan_json(&vk_res));
                write_http_resp(stream, "200 OK", "application/json; charset=utf-8", &js);
            } else if path == "/api/lease" {
                let lease = bench_prime_chebyshev_lease(64);
                let js = format!(
                    "{{\"ok\":true,\"tier\":\"{}\",\"lane\":\"0x80_Cortex_X4\",\"cpus\":\"{}\",\"epoch\":{},\"commute_pass\":\"{}/{}\",\"avg_lease_ns\":{:.1},\"lease_token\":\"{}\"}}",
                    current_tier_tag(), json_esc(&lease.cpus_allowed), lease.active_epoch, lease.commute_passed, lease.trials, lease.avg_lease_ns, lease.lease_token_hex
                );
                write_http_resp(stream, "200 OK", "application/json; charset=utf-8", &js);
            } else if path == "/api/bench" {
                let fresh = run_full_bench();
                *initial.lock().unwrap_or_else(|e| e.into_inner()) = fresh.clone();
                let sens = sensor_json.lock().unwrap_or_else(|e| e.into_inner()).clone();
                let js = format_report_json(&fresh, hb_ticks.load(Ordering::Relaxed), &sens);
                write_http_resp(stream, "200 OK", "application/json; charset=utf-8", &js);
            } else if path == "/api/sensors/ingest" && method == "POST" {
                let trimmed = req_body.trim();
                if trimmed.starts_with('{') && trimmed.ends_with('}') {
                    *sensor_json.lock().unwrap_or_else(|e| e.into_inner()) = trimmed.to_string();
                }
                let js = format!("{{\"ok\":true,\"heartbeat_ticks\":{},\"jitter_us\":{}}}", hb_ticks.load(Ordering::Relaxed), hb_jitter_us.load(Ordering::Relaxed));
                write_http_resp(stream, "200 OK", "application/json; charset=utf-8", &js);
            } else if path == "/api/sensors" {
                let sens = sensor_json.lock().unwrap_or_else(|e| e.into_inner()).clone();
                let js = format!("{{\"ok\":true,\"heartbeat_hz\":15.965,\"ticks\":{},\"last_jitter_us\":{},\"frame\":{}}}", hb_ticks.load(Ordering::Relaxed), hb_jitter_us.load(Ordering::Relaxed), sens);
                write_http_resp(stream, "200 OK", "application/json; charset=utf-8", &js);
            } else if path == "/api/shutdown" {
                running.store(false, Ordering::SeqCst);
                write_http_resp(stream, "200 OK", "application/json; charset=utf-8", "{\"ok\":true,\"stopping\":true}");
                std::process::exit(0);
            } else {
                let snap = initial.lock().unwrap_or_else(|e| e.into_inner()).clone();
                let mut rows_html = String::new();
                for k in &snap.vulkan.kernels {
                    rows_html.push_str(&format!(
                        "<tr><td style='color:#34d399'>{}</td><td>{}/{}</td><td>{:.1} MElem/s</td><td>{:.2} GOPS/s</td><td>{}</td></tr>",
                        k.id, k.matched, k.elements, k.melem_per_sec, k.gops_per_sec, k.detail
                    ));
                }
                let coop_line = format_coop_summary_line(&snap.vulkan.coop_tiles);
                let is_avf = cfg!(all(target_os = "linux", target_arch = "aarch64")) || port == 19789;
                let border_hex = if is_avf { "#34d399" } else { "#38bdf8" };
                let title_banner = if is_avf {
                    format!("ACT-Omega AVF @deb v0.7.5 :: Debian 13 pKVM + Virtio-GPU GFXStream (:{} Persistent Worker)", port)
                } else {
                    format!("ACT-Omega Pixel 10 v0.7.5 :: Native Android Tensor G5 + PowerVR (:{} Worker)", port)
                };
                let peer_link = if port == 19789 {
                    "<a href='http://127.0.0.1:19788/'>Switch -> :19788 Native Android</a>"
                } else {
                    "<a href='http://127.0.0.1:19789/'>Switch -> :19789 AVF @deb Virtio-GPU</a>"
                };
                let html = format!(
                    "<!doctype html><html><head><meta charset='utf-8'><title>{}</title>\
                    <style>body{{background:#090d16;color:#e2e8f0;font-family:Consolas,monospace;padding:20px}} \
                    .card{{background:#0f172a;border:1px solid {};border-radius:8px;padding:16px;margin-bottom:14px}} \
                    table{{width:100%;border-collapse:collapse;margin-top:8px}} td,th{{border-bottom:1px solid #1e293b;padding:6px;text-align:left}} \
                    h2{{color:{};margin-top:0}} a{{color:#38bdf8;margin-right:10px}}</style></head><body>\
                    <h2>{}</h2>\
                    <div class='card'><b>15.965 Hz Heartbeat Ticks:</b> {} (Last Jitter: {} us) | <b>Dispatched Jobs:</b> {} | <b>RAM:</b> {}/{} MB<br>\
                    <b>ARMv9.2 Silicon ISA:</b> {}<br>\
                    <b>0x7C (5x A725):</b> {:.1} MOPS/s SH4Z | <b>UDOT:</b> {:.1} MOPS/s | {:.2} MVec/s E8 | <b>0x80 (X4):</b> {} ({:.1} ns)</div>\
                    <div class='card'><b>{} (API {}, Subgroup={} [{}..{}], UMA={} MB, {} Exts):</b> [{}]<br>\
                    <b>IntDot 0x0040008:</b> {}<br>\
                    <b>UDot 0x0040008:</b> {}<br>\
                    <b>CoopMatrix ({}):</b> {} ({})\
                    <table><tr><th>Kernel</th><th>Parity</th><th>Throughput</th><th>Compute</th><th>Notes</th></tr>{}</table></div>\
                    <div class='card'><b>Tensor G5 4th-Gen TPU (36500000.buenos):</b> {}<br><b>SoC &amp; Sysfs:</b> {} | {}</div><div class='card'>RPC: <a href='/api/health'>/api/health</a> | <a href='/api/tpu'>/api/tpu (TPU X-Ray)</a> | <a href='/api/dispatch/tpu'>/api/dispatch/tpu (16L Burst)</a> | <a href='/api/dispatch/udot'>/api/dispatch/udot (497G UDot)</a> | \
                    <a href='/api/status'>/api/status</a> | <a href='/api/caps'>/api/caps</a> | \
                    <a href='/api/vulkan?kernel=udot'>/api/vulkan?kernel=udot</a> | <a href='/api/vulkan?kernel=all'>/api/vulkan?kernel=all</a> | \
                    <a href='/api/lease'>/api/lease</a> | <a href='/api/bench'>/api/bench</a> | {}</div></body></html>",
                    title_banner, border_hex, border_hex, title_banner,
                    hb_ticks.load(Ordering::Relaxed), hb_jitter_us.load(Ordering::Relaxed),
                    dispatch_jobs.load(Ordering::Relaxed),
                    snap.sys.mem_avail_mb, snap.sys.mem_total_mb, snap.sys.isa_badges.join(" "),
                    snap.compute.sh4z_mops_per_sec, snap.compute.udot_mops_per_sec, snap.compute.e8_mvec_per_sec,
                    snap.prime.lease_token_hex, snap.prime.avg_lease_ns,
                    snap.vulkan.device_name, snap.vulkan.api_version, snap.vulkan.subgroup_size,
                    snap.vulkan.subgroup_min, snap.vulkan.subgroup_max,
                    snap.vulkan.uma_heap_mb, snap.vulkan.ext_total, snap.vulkan.ext_badges.join(", "),
                    snap.vulkan.idot_tune_note,
                    snap.vulkan.udot_tune_note,
                    snap.vulkan.coop_tiles.len(), coop_line, snap.vulkan.coop_tune_note, rows_html,
                    snap.tpu.summary_line, snap.tpu.soc_props, snap.tpu.buenos_sysfs,
                    peer_link
                );
                write_http_resp(stream, "200 OK", "text/html; charset=utf-8", &html);
            }
                }));
                inflight_guard.fetch_sub(1, Ordering::Relaxed);
            });
        }
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut mode_json = false;
    let mut mode_daemon = false;
    let mut mode_caps = false;
    let mut mode_tpu = false;
    let mut vulkan_only = String::new();
    let mut bind_ip = "auto".to_string();
    let mut port: u16 = if cfg!(all(target_os = "linux", target_arch = "aarch64")) { 19789 } else { 19788 };

    let mut i = 1usize;
    while i < args.len() {
        match args[i].as_str() {
            "--json" => mode_json = true,
            "--daemon" | "--daemonize" | "--avf-daemon" => mode_daemon = true,
            "--caps" => mode_caps = true,
            "--tpu" | "--npu" => mode_tpu = true,
            "--coopmat" => vulkan_only = "coopmat".to_string(),
            "--tensor" => vulkan_only = "tensor".to_string(),
            "--udot" => vulkan_only = "udot".to_string(),
            "--vulkan" if i + 1 < args.len() && !args[i + 1].starts_with("--") => {
                vulkan_only = args[i + 1].clone();
                i += 1;
            }
            "--vulkan" | "--vulkan-only" => {
                if vulkan_only.is_empty() { vulkan_only = "all".to_string(); }
            }
            "--kernel" if i + 1 < args.len() => {
                vulkan_only = args[i + 1].clone();
                i += 1;
            }
            "--bind" if i + 1 < args.len() => {
                bind_ip = args[i + 1].clone();
                i += 1;
            }
            "--port" if i + 1 < args.len() => {
                port = args[i + 1].parse::<u16>().unwrap_or(port);
                i += 1;
            }
            _ => {}
        }
        i += 1;
    }

    let detach_bg = args.iter().any(|a| a == "--daemonize");
    if mode_daemon {
        if detach_bg {
            posix_detach_daemonize(b"/data/local/tmp/omega_p10_worker.log\0");
        }
        run_daemon(&bind_ip, port);
        return;
    }
    if mode_tpu {
        let tpu = probe_and_bench_tpu_npu(true);
        if mode_json {
            println!("{{\"ok\":true,\"worker\":\"omega_p10_worker_v0.7.5\",\"tier\":\"{}\",\"tpu\":{}}}", current_tier_tag(), format_tpu_json(&tpu));
        } else {
            println!("==============================================================================");
            println!(" ACT-OMEGA PIXEL 10 :: TENSOR G5 4TH-GEN TPU (36500000.buenos) 16-LAYER SUITE v0.7.5");
            println!("==============================================================================");
            print_tpu_block(&tpu, "  ");
            println!("==============================================================================");
        }
        return;
    }
    if mode_caps {
        let sys = probe_sys_topology();
        let vk = run_vulkan_suite("caps_only");
        let isas: Vec<String> = sys.isa_badges.iter().map(|s| format!("\"{}\"", json_esc(s))).collect();
        println!("{{\"ok\":true,\"tier\":\"{}\",\"isa_features\":[{}],\"vulkan_caps\":{}}}", current_tier_tag(), isas.join(","), format_vulkan_json(&vk));
        return;
    }
    if !vulkan_only.is_empty() {
        let vk = run_vulkan_suite(&vulkan_only);
        if mode_json {
            println!("{{\"ok\":true,\"tier\":\"{}\",\"vulkan\":{}}}", current_tier_tag(), format_vulkan_json(&vk));
        } else {
            print_vulkan_block(&vk, "  ");
        }
        return;
    }

    let rep = run_full_bench();
    if mode_json {
        println!("{}", format_report_json(&rep, rep.sensor.ticks as u64, "{\"mode\":\"oneshot_bench\"}"));
    } else {
        print_human_scorecard(&rep);
    }
}
